 fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(database,Self::SQLITE_SCHEMA,control.limits()).map_err(|e|e.to_string())?;let names=[("equation_document",1),("equation_notation_child",7),("equation_results_child",7),("equation_computed_child",7),("equation_expression",5),("equation_node",5),("equation_integer",2),("equation_rational",3),("equation_symbol",2),("equation_add",1),("equation_mul",1),("equation_pow",3),("equation_add_term",4),("equation_mul_factor",4)];let mut maps=Vec::with_capacity(names.len());let mut total=0;for(name,width)in names{let table=database.table(name)?;let mut map=BTreeMap::new();for row in&table.rows{if row.values.len()!=width||row.rowid<1||row.integer(0)?!=row.rowid||map.insert(row.rowid,row).is_some(){return Err("Equation row identity differs".into())}total+=1;if total%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,total,0)?;}}maps.push(map);}let mut used=BTreeSet::new();for table in 0..5{if maps[table].len()!=1||!maps[table].contains_key(&1){return Err("Equation fixed entity differs".into())}}take(&maps,&mut used,0,1)?;
 let mut child=|table|->Result<(String,store::os_io::ArtifactRef),String>{let row=take(&maps,&mut used,table,1)?;if row.integer(1)?!=1{return Err("Equation child parent differs".into())}let mut r=Reconstruction::new(control)?;Ok((r.text(row.text(2)?)?,store::os_io::ArtifactRef{artifact_id:r.text(row.text(3)?)?,dialect:store::os_io::ArtifactDialect{artifact_kind:r.text(row.text(4)?)?,standard:r.text(row.text(5)?)?,subset:r.text(row.text(6)?)?}}))};let(id,target)=child(1)?;let notation=store::ArtifactChild::new(id,target);let(id,target)=child(2)?;let results=store::ArtifactChild::new(id,target);let(id,target)=child(3)?;let computed=store::ArtifactChild::new(id,target);let expression=take(&maps,&mut used,4,1)?;if expression.integer(1)?!=1{return Err("Equation expression parent differs".into())}let root=expression.integer(2)?;let next_label=word(expression,3)?;let mut edges:[Edges<'_>;2]=[BTreeMap::new(),BTreeMap::new()];for table in[12,13]{for(index,row)in maps[table].values().enumerate(){let owner=row.integer(1)?;let ordinal=usize::try_from(row.integer(2)?).map_err(|e|e.to_string())?;if edges[table-12].entry(owner).or_default().insert(ordinal,row).is_some(){return Err("Equation repeated ordinal".into())}if index%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,index,maps[table].len())?;}}}let mut pending=vec![root];let mut plans=Vec::new();while let Some(id)=pending.pop(){let node=take(&maps,&mut used,5,id)?;if node.integer(1)?!=1{return Err("Equation node expression differs".into())}let kind=node.text(4)?;let table=match kind{"integer"=>6,"rational"=>7,"symbol"=>8,"add"=>9,"mul"=>10,"pow"=>11,_=>return Err("Equation node variant differs".into())};let row=take(&maps,&mut used,table,id)?;let kids=match kind{"add"=>ordered(12,id,&edges,&maps,&mut used)?,"mul"=>ordered(13,id,&edges,&maps,&mut used)?,"pow"=>vec![row.integer(1)?,row.integer(2)?],_=>vec![]};pending.extend(kids.iter().copied());plans.push((id,word(node,2)?,kind,row,kids));if plans.len()%256