# Real grammar for `LayoutSnapshot::print_dsl`/`parse_dsl`: the derived spec-driven text of
# `LayoutSnapshot`'s `dsl::DslRecord` spec (📸️snapshot/🦀️.rs), the same record the pack encodes.
# Conventions of the derived text:
#   - a field is `key=value`; fields are space-separated and may appear in any order; an absent
#     optional field is omitted;
#   - a nested record prints its own fields inline after `key=`;
#   - a list prints its elements between `[` and `]`;
#   - a block field prints `key {` … `}` on its own lines, without `=`;
#   - a table prints `key [column:TYPE …] {` one space-separated row per line `}`;
#   - a statement prints its keyword followed by that variant's fields.
artifact-mark = "semio layout.layout.dsl v1"
document = artifact-mark doc-field*
doc-field = {"schema" "=" TEXT} | {"name" "=" TEXT} | {"grid" "=" grid-field+}
  | {"paragraph-styles" "=" "[" paragraph-style* "]"} | {"character-styles" "=" "[" character-style* "]"}
  | {"stories" "=" "[" story* "]"} | {"links" "=" "[" link* "]"} | {"parent-pages" "=" "[" parent-page* "]"}
  | {"spreads" "=" "[" spread* "]"} | {"pages" "=" "[" page* "]"} | {"print-target" "=" TEXT}
  | {"data-fields-json" "=" TEXT} | {"background-drawing" "=" background-drawing-field+}
  | {"referenced-model" "=" referenced-model-field+}

grid-field = {"baseline-grid" "=" NUMBER} | {"baseline-offset" "=" NUMBER} | {"snap-to-baseline" "=" BOOL}
paragraph-style = paragraph-style-field+
paragraph-style-field = {"id" "=" TEXT} | {"name" "=" TEXT} | {"font-family" "=" TEXT} | {"font-size" "=" NUMBER} | {"font-weight" "=" UINT} | {"leading" "=" NUMBER} | {"tracking" "=" NUMBER} | {"alignment" "=" TEXT}
character-style = character-style-field+
character-style-field = {"id" "=" TEXT} | {"name" "=" TEXT} | {"font-family" "=" TEXT} | {"font-size" "=" NUMBER} | {"font-weight" "=" UINT} | {"italic" "=" BOOL} | {"color" "=" rgba} | {"tracking" "=" NUMBER}
story = story-field+
story-field = {"id" "=" TEXT} | {"content" "=" TEXT} | style-runs
style-runs = "style-runs" "[" "start:UINT" "end:UINT" "paragraph-style-id:REF" "character-style-id:REF" "]" "{" style-run* "}"
style-run = UINT UINT TEXT TEXT
link = link-field+
link-field = {"id" "=" TEXT} | {"path" "=" TEXT} | {"hash" "=" TEXT} | {"width" "=" UINT} | {"height" "=" UINT} | {"dpi" "=" UINT} | {"color-profile" "=" TEXT} | {"state" "=" TEXT} | {"proxy-data-url" "=" TEXT} | {"artifact-kind" "=" TEXT} | {"artifact-ref" "=" TEXT}
parent-page = parent-page-field+
parent-page-field = {"id" "=" TEXT} | {"name" "=" TEXT} | {"width" "=" NUMBER} | {"height" "=" NUMBER} | {"layer-ids" "=" "[" TEXT* "]"} | layers | frames
spread = spread-field+
spread-field = {"id" "=" TEXT} | {"name" "=" TEXT} | {"page-ids" "=" "[" TEXT* "]"}
page = page-field+
page-field = {"id" "=" TEXT} | {"name" "=" TEXT} | {"spread-id" "=" TEXT} | {"parent-page-id" "=" TEXT} | {"width" "=" NUMBER} | {"height" "=" NUMBER}
  | {"margins" "{" margin-field* "}"} | {"columns" "{" column-field* "}"} | guides | {"layer-ids" "=" "[" TEXT* "]"} | layers | frames | overrides
margin-field = {"top" "=" NUMBER} | {"right" "=" NUMBER} | {"bottom" "=" NUMBER} | {"left" "=" NUMBER}
column-field = {"count" "=" UINT} | {"gutter" "=" NUMBER}
guides = "guides" "[" "x:NUM" "y:NUM" "width:NUM" "height:NUM" "]" "{" guide* "}"
guide = NUMBER NUMBER NUMBER NUMBER
layers = "layers" "[" "id:TEXT" "name:TEXT" "visible:BOOL" "locked:BOOL" "object-ids:LIST" "]" "{" layer* "}"
layer = TEXT TEXT BOOL BOOL "[" TEXT* "]"
overrides = "overrides" "[" "object-id:REF" "bounds:BLOCK" "visible:BOOL" "locked:BOOL" "]" "{" override* "}"
override = TEXT {"{" bounds-field* "}"}? BOOL? BOOL?
frames = "frames" "{" frame* "}"
frame = image-frame | rect-frame | text-frame
image-frame = "image" frame-field* {"link-id" "=" TEXT}
rect-frame = "rect" frame-field* rect-field*
text-frame = "text" frame-field* text-field*
frame-field = {"id" "=" TEXT} | {"layer-id" "=" TEXT} | {"bounds" "{" bounds-field* "}"} | {"locked" "=" BOOL} | {"visible" "=" BOOL}
rect-field = {"fill" "=" rgba} | {"stroke" "=" rgba}
text-field = {"story-id" "=" TEXT} | {"thread-next" "=" TEXT} | {"columns" "=" UINT} | {"inset" "{" inset-field* "}"} | {"wrap-mode" "=" TEXT}
bounds-field = {"x" "=" NUMBER} | {"y" "=" NUMBER} | {"width" "=" NUMBER} | {"height" "=" NUMBER} | {"rotation" "=" NUMBER}
inset-field = {"x" "=" NUMBER} | {"y" "=" NUMBER} | {"width" "=" NUMBER} | {"height" "=" NUMBER}
background-drawing-field = {"handle" "=" child-handle} | {"content" "=" VALUE}
referenced-model-field = {"target" "=" TEXT} | {"pin" "=" pin-field+} | {"role" "=" TEXT}
pin-field = {"kind" "=" {"head" | "checkpoint" | "snapshot"}} | {"checkpoint_id" "=" TEXT} | {"blob_hash" "=" TEXT} | {"blob_size" "=" UINT} | {"blob_media_type" "=" TEXT}
child-handle = {"child_id" "=" TEXT} {"target" "=" TEXT}
rgba = NUMBER "," NUMBER "," NUMBER "," NUMBER

