    fn diff_patch(&self, other: &Self) -> Option<crate::standards::v1::subsets::any::schema::diff::SpreadPatch> {
        (self.name != other.name).then(|| crate::standards::v1::subsets::any::schema::diff::SpreadPatch { name: Some(other.name.clone()) })
    }
}

