async fn sqlite_snapshot_wav_actual_erased_capability_retains_all_owned_sample_states() {
    use semio_framework_os_kernel::{
        io::{ArtifactDialect, IoPayload},
        sqlite_snapshot::SnapshotEncoding,
    };
