            ("mutation grammar", mutations::text::COMPONENT_GRAMMAR_SEMIO),
            ("mutation protocol", mutations::binary::COMPONENT_PROTOCOL_SEMIO),
            ("inference grammar", inferences::text::COMPONENT_GRAMMAR_SEMIO),
