//! 🧾️ Handcrafted RFC8259 value/member/element relations for JSON artifact snapshots only.

use super::{JsonMember, JsonSnapshot, JsonValue};
use semio_framework_os_kernel::{sqlite_snapshot::{validate_sqlite_database_schema, SqliteDatabase, SqliteRow, SqliteSnapshotControl, SqliteSnapshotPhase, SqliteValue}, ArtifactSqliteSnapshot};
use std::collections::{BTreeMap, BTreeSet};

enum Parent<'a> { Root, Member(i64, usize, &'a str), Element(i64, usize) }

fn integer(value: usize) -> Result<i64, String> { i64::try_from(value).map_err(|error| error.to_string()) }
fn add(value: &mut usize, amount: usize) -> Result<(), String> { *value = value.checked_add(amount).ok_or("JSON relational size overflow")?; Ok(()) }
fn kind(value: &JsonValue) -> &'static str { match value { JsonValue::Null => "null", JsonValue::Bool { .. } => "boolean", JsonValue::Number { .. } => "number", JsonValue::String { .. } => "string", JsonValue::Array { .. } => "array", JsonValue::Object { .. } => "object" } }

fn measure(snapshot: &JsonSnapshot, control: &mut SqliteSnapshotControl<'_>) -> Result<usize, String> {
    let mut rows = 1usize; let mut bytes = snapshot.schema.len().checked_add(16).ok_or("JSON document size overflow")?;
    control.check_value_bytes(bytes)?; let mut stack = vec![&snapshot.value]; let mut visited = 0usize;
    while let Some(value) = stack.pop() {
        add(&mut rows, 1)?; add(&mut bytes, 8 + kind(value).len())?;
        match value {
            JsonValue::Bool { .. } => add(&mut bytes, 8)?,
            JsonValue::Number { lexeme } => { add(&mut bytes, lexeme.len())?; add(&mut bytes,8)?; control.check_value_bytes(bytes)?; }
            JsonValue::String { value } => add(&mut bytes, value.len())?,
            JsonValue::Array { items } => { control.check_rows(rows.checked_add(items.len().checked_mul(2).ok_or("JSON array size overflow")?).ok_or("JSON array size overflow")?)?; add(&mut rows, items.len())?; add(&mut bytes, items.len().checked_mul(32).ok_or("JSON array size overflow")?)?; stack.extend(items.iter().rev()); }
            JsonValue::Object { members } => { control.check_rows(rows.checked_add(members.len().checked_mul(2).ok_or("JSON object size overflow")?).ok_or("JSON object size overflow")?)?; add(&mut rows, members.len())?; add(&mut bytes, members.len().checked_mul(32).ok_or("JSON object size overflow")?)?; for member in members.iter().rev() { add(&mut bytes, member.key.len())?; stack.push(&member.value); } }
            JsonValue::Null => {}
        }
        control.check_rows(rows)?; control.check_value_bytes(bytes)?; visited += 1;
        if visited % 256 == 0 { control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot, 0, rows)?; }
    }
    Ok(rows)
}

impl ArtifactSqliteSnapshot for JsonSnapshot {
    fn retire_sqlite_snapshot(self) { super::owned_pack::retire(self); }
    fn preflight_sqlite_snapshot_encoding(&self, _encoding: semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding, control: &mut SqliteSnapshotControl<'_>) -> Result<(), String> {
        super::owned_pack::preflight(self, control)
    }
    fn validate_sqlite_snapshot_subset(&self,dialect:&semio_framework_os_kernel::io_schema::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->semio_framework_os_kernel::io_schema::IoResult<()>{
        control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;
        if dialect.artifact_kind!="s.stdio.json"||dialect.standard!="rfc8259"{return Err(String::from("JSON owned snapshot dialect differs from RFC8259").into());}
        let row=database.table("json_document")?.single_row()?;if row.rowid!=1||row.text(1)?!=self.schema{return Err(String::from("JSON owned document identity differs from semantic projection").into());}
        let diagnostics=match dialect.subset.as_str(){"*"=>Vec::new(),"i-json"=>crate::standards::v_rfc8259::subsets::i_json::schema::check_i_json_conformance_controlled(self,control)?,"geojson"=>crate::standards::v_rfc8259::subsets::geojson::schema::check_geojson_conformance_controlled(self,control)?,_=>return Err(String::from("JSON named subset has no owned semantic validator").into())};
        Ok(semio_framework_os_kernel::io_schema::IoOutcome{value:(),diagnostics})
    }

    fn decode_sqlite_snapshot_native(payload:&store::os_io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{
        let limits=control.limits();control.checkpoint(SqliteSnapshotPhase::DecodeNative,0,0)?;
        let length=match payload{store::os_io::IoPayload::Binary(bytes)=>bytes.len(),store::os_io::IoPayload::Text(text)=>text.len()};
        if length>limits.max_file_bytes{return Err("JSON native input exceeds file byte limit".into())}
        let mut progress=|state:protocol::native_decoding::NativeDecodeProgress|control.checkpoint(SqliteSnapshotPhase::DecodeNative,state.completed,state.total).is_ok();
        let mut native=protocol::native_decoding::NativeDecodeControl::new(limits.max_value_bytes,&mut progress);
        let spec=<Self as store::ArtifactPack>::record_spec().ok_or("JSON logical record specification missing")?;
        let record=match payload{
            store::os_io::IoPayload::Binary(bytes)=>{let body=store::semio_format::unwrap_binary_controlled(bytes,"stdio.json",store::semio_format::Component::Pack,1,&mut native).map_err(|e|e.to_string())?;store::pack_rt::decode_document_controlled(body,&spec,&store::PackDecodeOptions::default(),&mut native).map_err(|e|e.to_string())?.0},
            store::os_io::IoPayload::Text(text)=>{let body=store::semio_format::split_text_preamble_controlled(text,"stdio.json",store::semio_format::Component::Dsl,1,&mut native).map_err(|e|e.to_string())?;dsl::schema::parse_exact_controlled(body,&spec,&dsl::ParseOptions{limits:dsl::Limits::default(),mode:dsl::SourceMode::Document},&mut native).map_err(|e|e.message)?}
        };
        super::owned_pack::reconstruct_record(&record,&mut native,limits.max_rows)
    }

    const SQLITE_SCHEMA: &'static str = include_str!("🗄️.sql");

    fn to_sqlite_database(&self, control: &mut SqliteSnapshotControl<'_>) -> Result<SqliteDatabase, String> {
        control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot, 0, 0)?; let total = measure(self, control)?;
        let mut database = SqliteDatabase::from_schema(Self::SQLITE_SCHEMA).map_err(|error| error.to_string())?;
        database.table_mut("json_document")?.rows.push(SqliteRow { rowid: 1, values: vec![SqliteValue::Integer(1), SqliteValue::Text(self.schema.clone()), SqliteValue::Integer(1)] });
        let mut values = Vec::new(); let mut members = Vec::new(); let mut elements = Vec::new(); let mut stack = vec![(&self.value, Parent::Root)];
        while let Some((value, parent)) = stack.pop() {
            if matches!(value, JsonValue::String { value } if value.len() > 65536) || matches!(value, JsonValue::Number { lexeme } if lexeme.len() > 65536) { control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot, 1 + values.len() + members.len() + elements.len(), total)?; }
            let id = integer(values.len() + 1)?; let mut boolean = SqliteValue::Null; let mut number = SqliteValue::Null; let mut string = SqliteValue::Null;let mut query_number=SqliteValue::Null;
            match value {
                JsonValue::Bool { value } => boolean = SqliteValue::Integer(i64::from(*value)),
                JsonValue::Number { lexeme } => {query_number=super::number::meaning(lexeme,control,SqliteSnapshotPhase::ProjectSnapshot,1+values.len()+members.len()+elements.len(),total)?.numeric.map(SqliteValue::Real).unwrap_or(SqliteValue::Null);number=SqliteValue::Text(lexeme.clone());},
                JsonValue::String { value } => string = SqliteValue::Text(value.clone()),
                JsonValue::Array { items } => for (ordinal, child) in items.iter().enumerate().rev() { stack.push((child, Parent::Element(id, ordinal))); },
                JsonValue::Object { members } => for (ordinal, member) in members.iter().enumerate().rev() { stack.push((&member.value, Parent::Member(id, ordinal, &member.key))); },
                JsonValue::Null => {}
            }
            values.push(SqliteRow { rowid: id, values: vec![SqliteValue::Integer(id), SqliteValue::Text(kind(value).into()), boolean, number, string, query_number] });
            match parent {
                Parent::Root => {}
                Parent::Member(parent, ordinal, key) => { let member_id = integer(members.len() + 1)?; members.push(SqliteRow { rowid: member_id, values: vec![SqliteValue::Integer(member_id), SqliteValue::Integer(parent), SqliteValue::Integer(integer(ordinal)?), SqliteValue::Text(key.into()), SqliteValue::Integer(id)] }); }
                Parent::Element(parent, ordinal) => { let element_id = integer(elements.len() + 1)?; elements.push(SqliteRow { rowid: element_id, values: vec![SqliteValue::Integer(element_id), SqliteValue::Integer(parent), SqliteValue::Integer(integer(ordinal)?), SqliteValue::Integer(id)] }); }
            }
            let completed = 1 + values.len() + members.len() + elements.len(); if values.len() % 256 == 0 { control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot, completed, total)?; }
        }
        database.table_mut("json_value")?.rows = values; database.table_mut("json_object_member")?.rows = members; database.table_mut("json_array_element")?.rows = elements;
        control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot, total, total)?; Ok(database)
    }

    fn from_sqlite_database(database: &SqliteDatabase, control: &mut SqliteSnapshotControl<'_>) -> Result<Self, String> {
        control.check_database(database, SqliteSnapshotPhase::ReconstructSnapshot)?;
        validate_sqlite_database_schema(database, Self::SQLITE_SCHEMA, control.limits()).map_err(|error| error.to_string())?;
        if database.tables.len() != 4 { return Err("JSON snapshot requires exactly its four domain tables".into()); }
        let total = database.tables.iter().map(|table| table.rows.len()).sum(); let mut checked = 0usize;
        let document = database.table("json_document")?.single_row()?;
        if document.values.len() != 3 || document.rowid != 1 || document.integer(0)? != 1 { return Err("JSON document requires identifier 1 and three columns".into()); }
        let root = document.integer(2)?; let mut values = BTreeMap::new();
        for row in &database.table("json_value")?.rows {
            if row.values.len() != 6 || row.integer(0)? != row.rowid || values.insert(row.rowid, row).is_some() { return Err("JSON value identity or column count is invalid".into()); }
            checked += 1; if checked % 256 == 0 { control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, 0, total)?; }
            let kind = row.text(1)?;
            let empty = |index| matches!(row.values.get(index), Some(SqliteValue::Null));
            match kind {
                "null" | "array" | "object" if empty(2) && empty(3) && empty(4) && empty(5) => {}
                "boolean" if empty(3) && empty(4) && empty(5) && matches!(row.integer(2)?, 0 | 1) => {}
                "number" if empty(2) && empty(4) => {let expected=super::number::meaning(row.text(3)?,control,SqliteSnapshotPhase::ReconstructSnapshot,0,total)?.numeric;if match expected{None=>!empty(5),Some(value)=>empty(5)||row.real(5)?!=value}{return Err("JSON derived numeric value disagrees with its owned lexeme".into())}},
                "string" if empty(2) && empty(3) && empty(5) => { row.text(4)?; }
                _ => return Err("JSON primitive kind and payload columns disagree".into()),
            }
        }
        if !values.contains_key(&root) { return Err("JSON document root is dangling".into()); }
        let mut ownership = BTreeSet::from([root]); let mut links = BTreeMap::<i64, Vec<(i64, i64, Option<&str>)>>::new();
        for (name, required_kind) in [("json_object_member", "object"), ("json_array_element", "array")] {
            let mut ids = BTreeSet::new();
            for row in &database.table(name)?.rows {
                if row.values.len() != (if required_kind == "object" { 5 } else { 4 }) || row.integer(0)? != row.rowid || !ids.insert(row.rowid) { return Err("JSON relationship identity or column count is invalid".into()); }
                let parent = row.integer(1)?; let ordinal = row.integer(2)?; let key = if required_kind == "object" { Some(row.text(3)?) } else { None }; let child = row.integer(if required_kind == "object" { 4 } else { 3 })?;
                if values.get(&parent).ok_or("JSON relationship parent is dangling")?.text(1)? != required_kind || !values.contains_key(&child) || ordinal < 0 { return Err("JSON relationship parent, child or ordinal is invalid".into()); }
                if !ownership.insert(child) { return Err("JSON value has multiple owners or creates a cycle".into()); }
                links.entry(parent).or_default().push((ordinal, child, key)); checked += 1; if checked % 256 == 0 { control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, 0, total)?; }
            }
        }
        for ordered in links.values_mut() { control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, 0, total)?; ordered.sort_by_key(|(ordinal, _, _)| *ordinal); for (expected, (ordinal, _, _)) in ordered.iter().enumerate() { if *ordinal != integer(expected)? { return Err("JSON child ordinals must be contiguous and zero-based".into()); } } }
        if ownership.len() != values.len() { return Err("JSON value has no document or container owner".into()); }
        let mut visited = BTreeSet::new(); let mut reconstructed = BTreeMap::new(); let mut stack = vec![(root, false)]; let mut completed = 1usize;
        while let Some((id, finish)) = stack.pop() {
            if !finish {
                if !visited.insert(id) { return Err("JSON relationships contain a cycle".into()); }
                stack.push((id, true)); if let Some(children) = links.get(&id) { stack.extend(children.iter().rev().map(|(_, child, _)| (*child, false))); }
                if visited.len() % 256 == 0 { control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, completed, total)?; } continue;
            }
            let row = values[&id]; if row.values.iter().any(|value| matches!(value, SqliteValue::Text(text) if text.len() > 65536)) { control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, completed, total)?; } let children = links.remove(&id).unwrap_or_default(); let child_count = children.len();
            let value = match row.text(1)? {
                "null" => JsonValue::Null,
                "boolean" => JsonValue::Bool { value: row.integer(2)? == 1 },
                "number" => JsonValue::Number { lexeme: row.text(3)?.into() },
                "string" => JsonValue::String { value: row.text(4)?.into() },
                "array" => { let mut items = Vec::new(); for (_, child, _) in children { items.push(reconstructed.remove(&child).ok_or("JSON child was not reconstructed")?); checked += 1; if checked % 256 == 0 { control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, completed, total)?; } } JsonValue::Array { items } },
                "object" => { let mut members = Vec::new(); for (_, child, key) in children { members.push(JsonMember { key: key.ok_or("JSON object member lacks a key")?.into(), value: reconstructed.remove(&child).ok_or("JSON child was not reconstructed")? }); checked += 1; if checked % 256 == 0 { control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, completed, total)?; } } JsonValue::Object { members } },
                _ => return Err("JSON value kind is invalid".into()),
            };
            reconstructed.insert(id, value); add(&mut completed, 1 + child_count)?; if completed % 256 == 0 { control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, completed, total)?; }
        }
        if visited.len() != values.len() || !links.is_empty() { return Err("JSON relationships are disconnected or cyclic".into()); }
        let value = reconstructed.remove(&root).ok_or("JSON root was not reconstructed")?;
        control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, total, total)?; Ok(Self { schema: document.text(1)?.into(), value })
    }
}

//! 🧬️ JsonSnapshot schema (rfc8259/🛜️i-json) — reuses the ✳️any subset's `JsonSnapshot` verbatim
//! (the SAME Rust type, same `s.stdio.json` schema id). RFC 7493 I-JSON is a validation-gated
//! dialect STAMP on top of that existing schema, not a new one -- see D4's Tier-1 "same snapshot
//! type, subset moves" semantics (`ArtifactCommand::MigrateDialect`). This leaf exists so
//! `🪆️subsets/🛜️i-json/🧬️schema/` is present per `🔣️taxonomy.json`'s `subsetChildDirs`, without
//! duplicating the schema definition. The underlying `JsonValue::Object(Vec<JsonMember>)` shape
//! (see the ✳️any schema) is what makes duplicate member names genuinely representable/checkable
//! here -- a `serde_json::Value`-style `Map` would have silently collapsed them on parse.

pub use crate::standards::v_rfc8259::subsets::base::schema::*;
//#region 🏗️DerivedConstruction
pub mod derived_construction {
    use crate::standards::v_rfc8259::subsets::base::schema::diff::JsonDiff;
    use crate::standards::v_rfc8259::subsets::base::schema::snapshot::JsonSnapshot;
    use crate::standards::v_rfc8259::subsets::i_json::schema::check_i_json_conformance;
    use crate::standards::v_rfc8259::subsets::i_json::schema::mutations::{apply_json_i_json_mutation, JsonIJsonMutation};
    use dsl::{Diagnostic, Severity};
    use semio_framework_plugin::ArtifactBuilder;

    //#region 🔖️Builder
    /// 🏗️ Holds the snapshot directly rather than wrapping the ✳️any builder, because this subset's
    /// `Mutation` is its OWN `JsonIJsonMutation` (see `mutations/🦀️.rs`) and not the ✳️any
    /// sibling's -- the same shape `ZipIso21320BuilderConstruction` already uses for the same reason.
    /// `from_text`/`from_binary` stay exactly the ✳️any codec (`ArtifactDsl`/`ArtifactPack` on the
    /// SHARED `JsonSnapshot`); only the mutation vocabulary and the RFC 7493 build gate are this
    /// subset's own.
    #[derive(Clone, Debug, Default)]
    pub struct JsonIJsonBuilderConstruction {
        snapshot: JsonSnapshot,
    }

    impl ArtifactBuilder for JsonIJsonBuilderConstruction {
        type Snapshot = JsonSnapshot;
        type Mutation = JsonIJsonMutation;
        type Diff = JsonDiff;

        fn empty() -> Self {
            Self { snapshot: JsonSnapshot::default() }
        }

        fn from_snapshot(snapshot: Self::Snapshot) -> Self {
            Self { snapshot }
        }

        fn from_text(text: &str) -> Result<Self, store::TextError> {
            Ok(Self { snapshot: <JsonSnapshot as store::ArtifactDsl>::parse_dsl(text)? })
        }

        fn from_binary(bytes: &[u8]) -> Result<Self, store::PackError> {
            Ok(Self { snapshot: <JsonSnapshot as store::ArtifactPack>::decode_pack(bytes)? })
        }

        fn mutate(mut self, mutation: Self::Mutation) -> (Self, protocol::MutationOutcome<Self::Diff>) {
            let outcome = apply_json_i_json_mutation(&mut self.snapshot, &mutation);
            (self, outcome)
        }

        fn absorb(mut self, diff: Self::Diff) -> protocol::MutationApplyResult<Self> {
            self.snapshot = <JsonDiff as protocol::MutationDiff<JsonSnapshot>>::apply(&diff, &self.snapshot)?;
            Ok(self)
        }

        /// 🛡️ The real construction gate: however the inner snapshot got here, a hard RFC 7493
        /// violation fails `build()` -- soft/advisory diagnostics pass through as `Ok`. Two doors now
        /// lead to the same clauses: this gate rejects a violating STATE, and `JsonIJsonMutation`'s
        /// own `diff()` rejects a violating EDIT before it can produce one.
        fn build(self) -> Result<Self::Snapshot, Vec<Diagnostic>> {
            let hard: Vec<Diagnostic> = check_i_json_conformance(&self.snapshot).into_iter().filter(|d| matches!(d.severity, Severity::Error | Severity::Fatal)).collect();
            if hard.is_empty() {
                Ok(self.snapshot)
            } else {
                Err(hard)
            }
        }
    }
    //#endregion 🔖️Builder

    #[cfg(test)]
    include!("🧪️tests/🔬️derived-construction-unit/🦀️.rs");
}
pub use derived_construction::*;
//#endregion 🏗️DerivedConstruction

//#region 🧐️DerivedAnalysis
pub mod derived_analysis {
    use crate::standards::v_rfc8259::subsets::base::schema::snapshot::{JsonSnapshot, JsonValue};
    use crate::standards::v_rfc8259::subsets::base::schema::JsonAnalyzer as JsonAnyAnalyzer;
    pub use crate::standards::v_rfc8259::subsets::base::schema::JsonParts;
    use dsl::{Diagnostic, FaultCode, FaultScope, Severity, TextSpan};
    use semio_framework_plugin::{Analysis, AnalyzeSource, ArtifactAnalysis, Dialect, IoConfidence, StandardId, SubsetId};

    /// 🎯️ This subset's dialect coordinate.
    pub const DIALECT: Dialect = Dialect { artifact_kind: "s.stdio.json", standard: StandardId("rfc8259"), subset: SubsetId("i-json") };

    //#region 🔖️Conformance
    pub const CODE_DUPLICATE_MEMBER: &str = "stdio.json.i-json.duplicate-member-name";
    pub const CODE_UNSAFE_INTEGER: &str = "stdio.json.i-json.unsafe-integer";
    pub const CODE_INVALID_NUMBER_LEXEME: &str = "stdio.json.i-json.invalid-number-lexeme";
    pub const CODE_NUMBER_NOT_BINARY64: &str = "stdio.json.i-json.number-not-binary64";
    pub const CODE_TOP_LEVEL_SCALAR: &str = "stdio.json.i-json.top-level-scalar";
    pub const CODE_STRING_NONCHARACTER: &str = "stdio.json.i-json.string-noncharacter";

    /// ± the largest integer magnitude exactly representable as an IEEE-754 double (2^53 - 1).
    const MAX_SAFE_INTEGER_MAGNITUDE: i128 = 9_007_199_254_740_991;

    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    fn hard(code: &'static str, message: String) -> Diagnostic {
        Diagnostic { code: FaultCode::new(code), severity: Severity::Error, span: TextSpan::at(1, 1), message, expected: None, scope: FaultScope::default() }
    }

    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    fn soft(code: &'static str, message: String) -> Diagnostic {
        Diagnostic { code: FaultCode::new(code), severity: Severity::Warning, span: TextSpan::at(1, 1), message, expected: None, scope: FaultScope::default() }
    }

    /// 🔢️ Is this number lexeme an integer (no fractional part, no exponent)? Per RFC8259's grammar,
    /// `.`/`e`/`E` only ever appear in the fraction/exponent parts.
    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    fn is_integer_lexeme(lexeme: &str) -> bool {
        !lexeme.contains('.') && !lexeme.contains('e') && !lexeme.contains('E')
    }

    /// 🔁️ Recursive scan: every integer number's magnitude against RFC 7493 §2.2's ±(2^53-1) safe
    /// bound, using the ORIGINAL LEXEME (never a lossy `f64` parse) so arbitrary-precision integers
    /// are checked exactly.
    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    fn scan_unsafe_integers(value: &JsonValue, out: &mut Vec<Diagnostic>) {
        match value {
            JsonValue::Number { lexeme } if is_integer_lexeme(lexeme) => match lexeme.parse::<i128>() {
                Ok(n) if n.unsigned_abs() > MAX_SAFE_INTEGER_MAGNITUDE as u128 => {
                    out.push(hard(CODE_UNSAFE_INTEGER, format!("integer {lexeme} exceeds ±(2^53-1) = ±{MAX_SAFE_INTEGER_MAGNITUDE} and is not exactly representable as an IEEE-754 double -- RFC 7493 §2.2 forbids this for I-JSON")));
                }
                Ok(_) => {}
                Err(_) => {
                    // Too large even for i128 -- definitely exceeds the much smaller 2^53-1 bound.
                    out.push(hard(CODE_UNSAFE_INTEGER, format!("integer {lexeme} is far larger than ±(2^53-1) and is not exactly representable as an IEEE-754 double -- RFC 7493 §2.2 forbids this for I-JSON")));
                }
            },
            JsonValue::Number { .. } => {}
            _ => {}
        }
    }

    /// 🚫️ A Unicode noncharacter per the Unicode Standard: the last two code points of every plane
    /// (`cp & 0xFFFE == 0xFFFE` covers U+FFFE/U+FFFF, U+1FFFE/U+1FFFF, ..., U+10FFFE/U+10FFFF) plus
    /// the reserved BMP range U+FDD0-U+FDEF.
    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    fn is_unicode_noncharacter(c: char) -> bool {
        let cp = c as u32;
        (cp & 0xFFFE) == 0xFFFE || (0xFDD0..=0xFDEF).contains(&cp)
    }

    /// 🛡️ Real RFC 7493 I-JSON conformance checks against one already-decoded `JsonSnapshot`. Shared
    /// single source of truth: `JsonIJsonComposer::compose` hard-gates on this (pre-serialization,
    /// authoritative), `JsonIJsonBuilder::build` hard-gates on this too, and the registered
    /// `SubsetValidator` re-runs it post-hoc against the wire payload for the D5 validate-on-build hook.
    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    /// 🛡️ Applies the same I-JSON rules with bounded typed traversal and transfer cancellation.
    pub fn check_i_json_conformance_controlled(snapshot:&JsonSnapshot,control:&mut semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotControl<'_>)->Result<Vec<Diagnostic>,String>{
        use semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotPhase;
        enum Work<'a>{Value(&'a JsonValue),Object(std::slice::Iter<'a,crate::schema::snapshot::JsonMember>,std::collections::HashSet<&'a str>),Array(std::slice::Iter<'a,JsonValue>)}
        let mut out=Vec::new();let mut count=0usize;control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;
        if !matches!(snapshot.value,JsonValue::Object{..}|JsonValue::Array{..}){out.push(soft(CODE_TOP_LEVEL_SCALAR,"top-level value is neither an object nor an array -- RFC 7493 §2.1 recommends against a bare top-level scalar for interop".into()));}
        for pass in 0..3{let mut rows=0usize;let mut pending=vec![Work::Value(&snapshot.value)];while let Some(work)=pending.pop(){if matches!(&work,Work::Value(_)){rows=rows.checked_add(1).ok_or("I-JSON conformance row count overflow")?;control.check_rows(rows)?;}count=count.checked_add(1).ok_or("I-JSON validation unit count overflow")?;if count%256==0{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,count,0)?;}
            match work{
                Work::Value(JsonValue::Object{members})=>pending.push(Work::Object(members.iter(),std::collections::HashSet::new())),
                Work::Value(JsonValue::Array{items})=>pending.push(Work::Array(items.iter())),
                Work::Object(mut members,mut seen)=>{if let Some(member)=members.next(){if pass==0&&!seen.insert(member.key.as_str()){if member.key.len()>65536{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,count,0)?;}out.push(hard(CODE_DUPLICATE_MEMBER,format!("object member name '{}' appears more than once -- RFC 7493 §2.3 forbids duplicate member names within one object",member.key)));}pending.push(Work::Object(members,seen));pending.push(Work::Value(&member.value));}},
                Work::Array(mut items)=>{if let Some(value)=items.next(){pending.push(Work::Array(items));pending.push(Work::Value(value));}},
                Work::Value(value@JsonValue::Number{lexeme}) if pass==1=>{let meaning=crate::schema::snapshot::number::meaning(lexeme,control,SqliteSnapshotPhase::ProjectSnapshot,count,0)?;if !meaning.valid{out.push(hard(CODE_INVALID_NUMBER_LEXEME,"a number requires an RFC8259 lexeme".into()));}else if meaning.numeric.is_none(){out.push(hard(CODE_NUMBER_NOT_BINARY64,"a number exceeds finite IEEE754 binary64 representation -- RFC7493 §2.2".into()));}else{scan_unsafe_integers(value,&mut out);}},
                Work::Value(JsonValue::String{value}) if pass==2=>{let mut noncharacter=false;for c in value.chars(){count=count.checked_add(1).ok_or("I-JSON validation unit count overflow")?;noncharacter|=is_unicode_noncharacter(c);if count%256==0{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,count,0)?;}}if noncharacter{out.push(soft(CODE_STRING_NONCHARACTER,format!("string {value:?} contains a Unicode noncharacter (U+FFFE/U+FFFF, U+FDD0-U+FDEF, or a per-plane equivalent) -- RFC 7493 §2.3 advises against these in I-JSON text")));}},
                _=>{}
            }
        }}control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,count,count)?;Ok(out)
    }

    pub fn check_i_json_conformance(snapshot: &JsonSnapshot) -> Vec<Diagnostic> {
        let mut proceed=|_|true;
        let mut control=semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotControl::new(&mut proceed,semio_framework_os_kernel::sqlite_snapshot::SqliteDatabaseLimits{max_rows:usize::MAX,..semio_framework_os_kernel::sqlite_snapshot::SqliteDatabaseLimits::default()});
        check_i_json_conformance_controlled(snapshot,&mut control).expect("borrowed I-JSON conformance without cancellation")
    }
    //#endregion 🔖️Conformance

    //#region 🔖️Analyzer
    /// 🧐️ Analyzes `stdio.json` (rfc8259/🛜️i-json): delegates the real parse to the ✳️any subset's
    /// analyzer (same `JsonSnapshot`), then folds real I-JSON conformance diagnostics on top.
    pub struct JsonIJsonAnalyzerAnalysis;

    impl ArtifactAnalysis for JsonIJsonAnalyzerAnalysis {
        type Parts = JsonParts;
        const DIALECT: Dialect = DIALECT;

        fn sniff(source: &AnalyzeSource<'_>) -> IoConfidence {
            JsonAnyAnalyzer::sniff(source)
        }

        fn analyze(sources: &[AnalyzeSource<'_>]) -> Analysis<Self::Parts> {
            let inner = JsonAnyAnalyzer::analyze(sources);
            let mut diagnostics = inner.diagnostics.clone();
            let mut confidence = inner.confidence;
            if let Some(snapshot) = &inner.parts.snapshot {
                let checks = check_i_json_conformance(snapshot);
                if checks.iter().any(|d| matches!(d.severity, Severity::Error | Severity::Fatal)) {
                    confidence = IoConfidence::Low;
                }
                diagnostics.extend(checks);
            }
            Analysis { parts: inner.parts, dialect: DIALECT, confidence, diagnostics }
        }
    }
    //#endregion 🔖️Analyzer

    #[cfg(test)]
    include!("🧪️tests/🔬️derived-analysis-unit/🦀️.rs");
}
