/// 🌉️ Hand-written — see `FaultOrigin` above.
impl ToValue for Fault {
    fn to_value(&self) -> DslValue {
        let mut entries = vec![
            ("origin".to_string(), self.origin.to_value()),
            ("code".to_string(), self.code.to_value()),
