  "nodes": [
    { "id": "a", "nodeKind": "computation", "text": "A", "userData": { "tags": ["x", "y", "z"], "matrix": [[1, 2], [3, 4]], "empty": [] } },
    { "id": "b", "nodeKind": "slider", "text": "B" }
  ],
  "edges": []
}"#
}
