        views: Vec::new(),
        ui: None,
        tool_run: None,
        principal_kind: None, active_tool: None, history_edit: None,
        typing: Vec::new(),
    };
    stamp_session(&mut peer, Some(7), Some("s.space.home@1/*#editor")).await;
