pub struct ArtifactEphemeralOneItemPublication<P, Mutation> {
    operation: semio_framework_job::OperationId,
    expected_generation: u64,
    footprint: ArtifactStoreOneItemFootprint,
    preparation: Option<Box<dyn ArtifactEphemeralOneItemPreparation<P, Mutation>>>,
    displaced_root_retirement: Option<Box<dyn ErasedSnapshotRetirement>>,
    root_retirement_factory: Option<Arc<dyn SnapshotRetirementFactory<P>>>,
    returned_read_registry: Option<Arc<SnapshotReadLeaseRegistry>>,
    returned_read_retirement: Option<Box<dyn ErasedSnapshotRetirement>>,
    owned_retirement_factory: Option<Arc<dyn ArtifactOwnedValueRetirementFactory<P>>>,
    receipt: Option<LaneItemReceipt>,
    /// 📍️ Last checkpoint the preparation owner reported, kept so progress survives the turn the
    /// owner is released on: a host polling `progress()` must never see a gesture walk backwards.
    retained_checkpoint: ArtifactStoreOneItemCheckpoint,
    attempts: u8,
    published: bool,
    cancel_requested: bool,
    close_started: bool,
    fault: Option<String>,
    phase: ArtifactStoreOneItemPublicationPhase,
}

impl<P, Mutation> ArtifactEphemeralOneItemPublication<P, Mutation> {
    pub fn operation(&self) -> semio_framework_job::OperationId {
        self.operation
    }

    pub fn phase(&self) -> ArtifactStoreOneItemPublicationPhase {
        self.phase
    }

    /// 📍️ Monotone gesture progress: the live preparation's own checkpoint while it owns one, and the
    /// last checkpoint it reported once it has been released. Answering `default()` (all zeros) the
    /// moment the owner goes away made a batch's progress snap back to 0 between items — measured on
    /// `🌊️flow` as `preparation progress changed from 22013 to 0` (ticket 26/09/19 `📓️flow.md` §5.4).
    pub fn progress(&self) -> ArtifactStoreOneItemCheckpoint {
        self.preparation.as_ref().map_or(self.retained_checkpoint, |owner| owner.checkpoint())
    }

    pub fn fault(&self) -> Option<&str> {
        self.fault.as_deref()
    }

    fn advance_preparation(&mut self, grant: ArtifactStoreOneItemGrant) -> Result<ArtifactStoreOneItemPreparationStep, String> {
        let result = self.preparation.as_mut().ok_or_else(|| "ephemeral publication lost its preparation owner".to_string()).and_then(|owner| {
            let step = owner.advance(ArtifactStoreOneItemGrant { maximum_items: grant.maximum_items.min(1), maximum_bytes: grant.maximum_bytes })?;
            if matches!(step, ArtifactStoreOneItemPreparationStep::Prepared(_)) && owner.prepared().is_none() {
                return Err("ephemeral preparation reported Prepared without its root".into());
            }
            Ok(step)
        });
        if let Err(reason) = &result {
            self.fault = Some(reason.clone());
            self.begin_close();
        }
        result
    }

    pub fn retry(&mut self) -> bool {
        if self.phase != ArtifactStoreOneItemPublicationPhase::AwaitingAck || self.attempts >= ARTIFACT_STORE_ONE_ITEM_MAXIMUM_RETRIES {
            return false;
        }
        self.attempts += 1;
        true
    }

    pub fn acknowledge(&mut self) -> bool {
        if self.phase != ArtifactStoreOneItemPublicationPhase::AwaitingAck {
            return false;
        }
        self.phase = ArtifactStoreOneItemPublicationPhase::Closing;
        self.begin_close();
        true
    }

    pub fn begin_close(&mut self) {
        if self.close_started {
            return;
        }
        self.close_started = true;
        self.phase = if self.phase == ArtifactStoreOneItemPublicationPhase::Complete { ArtifactStoreOneItemPublicationPhase::Complete } else { ArtifactStoreOneItemPublicationPhase::Closing };
        if let Some(owner) = self.preparation.as_mut() {
            if !self.published {
                self.cancel_requested = true;
                owner.cancel();
            }
            owner.begin_close();
        }
    }

    pub fn close_step(&mut self, grant: ArtifactStoreOneItemGrant) -> Result<SnapshotRetirementStep, String>
    where
        P: Send + Sync + 'static,
    {
        self.begin_close();
        if let Some(owner) = self.preparation.as_mut() {
            let step = owner.close_step(ArtifactStoreOneItemGrant { maximum_items: grant.maximum_items.min(1), maximum_bytes: grant.maximum_bytes })?;
            if step != SnapshotRetirementStep::Complete {
                return Ok(step);
            }
            if !owner.terminal_is_empty() {
                return Err("ephemeral one-item preparation reported complete without terminal emptiness".into());
            }
            self.retained_checkpoint = self.progress();
            self.preparation = None;
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let (Some(registry), Some(factory)) = (self.returned_read_registry.as_ref(), self.owned_retirement_factory.as_ref()) {
            let step = advance_returned_snapshot_read(registry, &mut self.returned_read_retirement, factory, grant.maximum_items.min(1), grant.maximum_bytes)?;
            if step != SnapshotRetirementStep::Complete {
                return Ok(step);
            }
        }
        if let Some(owner) = self.displaced_root_retirement.as_mut() {
            let step = owner.close_step(grant.maximum_items.min(1), grant.maximum_bytes)?;
            if step != SnapshotRetirementStep::Complete {
                return Ok(step);
            }
            if !owner.terminal_is_empty() {
                return Err("ephemeral displaced-root retirement reported complete without terminal emptiness".into());
            }
            self.displaced_root_retirement = None;
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        self.root_retirement_factory = None;
        self.returned_read_registry = None;
        self.owned_retirement_factory = None;
        if grant.maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if self.receipt.take().is_some() {
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let Some(fault) = self.fault.as_mut().filter(|fault| !fault.is_empty()) {
            let scalar = fault.chars().next_back().expect("nonempty ephemeral publication fault");
            if scalar.len_utf8() > grant.maximum_bytes {
                return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
            }
            fault.pop();
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: scalar.len_utf8() });
        }
        self.fault = None;
        self.phase = ArtifactStoreOneItemPublicationPhase::Complete;
        Ok(SnapshotRetirementStep::Complete)
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.phase == ArtifactStoreOneItemPublicationPhase::Complete
            && self.preparation.is_none()
            && self.displaced_root_retirement.is_none()
            && self.root_retirement_factory.is_none()
            && self.returned_read_registry.is_none()
            && self.returned_read_retirement.is_none()
            && self.owned_retirement_factory.is_none()
            && self.receipt.is_none()
            && self.fault.is_none()
    }
}

impl<P, Mutation> Drop for ArtifactEphemeralOneItemPublication<P, Mutation> {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.terminal_is_empty()), "ephemeral one-item publication reached Drop without its terminal-empty witness");
    }
}
//#endregion 📬️EphemeralOneItemPublication

/// 👥️ The PRESENCE lane's store: ephemeral SHARED state — a last-writer-wins roster, NOT an
/// event log.
///
/// 🎯️ Why not `ArtifactStore` (which `ConfigStore`/`DraftStore` both alias): presence has no
/// history, no undo, no checkpoints and no merge. Each peer is the sole author of its own presence
/// value, and the wire already carries whole encoded snapshots per peer
/// (`ClientFrame::Presence { peer }` / `ServerFrame::Presence { peers }`), so a later frame from a
/// peer simply SUPERSEDES its earlier one. Modelling that as an op log would mint an unbounded
/// history of cursor positions nobody can ever undo.
///
/// `generation` bumps on every local change so the host can tell "something to broadcast" from
/// "nothing changed" without diffing snapshots — the signal a heartbeat coalescer throttles on.
pub struct PresenceStore<P, Mutation> {
    local: std::mem::ManuallyDrop<Arc<P>>,
    peers: std::mem::ManuallyDrop<Arc<PresencePeersRoot<P>>>,
    peer_retirement_factory: Option<Arc<dyn SnapshotRetirementFactory<P>>>,
    local_retirement_factory: Option<Arc<dyn SnapshotRetirementFactory<P>>>,
    local_reads: std::mem::ManuallyDrop<Arc<SnapshotReadLeaseRegistry>>,
    active_returned_local: std::mem::ManuallyDrop<Option<Box<dyn ErasedSnapshotRetirement>>>,
    generation: u64,
    close_started: bool,
    _mutation: PhantomData<fn() -> Mutation>,
}

pub const PRESENCE_PEER_SLOTS: usize = 64;
pub const PRESENCE_PEER_ID_BYTES: usize = 256;

#[derive(Debug)]
struct PresencePeerEntry<P> {
    actor: std::mem::ManuallyDrop<String>,
    presence: std::mem::ManuallyDrop<Option<Arc<P>>>,
    received_at_ms: i64,
}

impl<P> PresencePeerEntry<P> {
    fn new(actor: String, presence: Arc<P>, received_at_ms: i64) -> Self {
        Self { actor: std::mem::ManuallyDrop::new(actor), presence: std::mem::ManuallyDrop::new(Some(presence)), received_at_ms }
    }
}

impl<P> Drop for PresencePeerEntry<P> {
    fn drop(&mut self) {
        let terminal = self.actor.is_empty() && self.presence.is_none();
        if !std::thread::panicking() {
            assert!(std::thread::panicking() || (terminal), "presence peer entry requires exact final-owner retirement");
        }
        if terminal {
            unsafe {
                drop(std::mem::ManuallyDrop::take(&mut self.actor));
                drop(std::mem::ManuallyDrop::take(&mut self.presence));
            }
        }
    }
}

#[derive(Debug)]
pub struct PresencePeersRoot<P> {
    entries: [Option<Arc<PresencePeerEntry<P>>>; PRESENCE_PEER_SLOTS],
    len: usize,
}

impl<P> PresencePeersRoot<P> {
    fn clone_aliases(&self) -> Self {
        Self { entries: self.entries.clone(), len: self.len }
    }
}

impl<P> PresencePeersRoot<P> {
    pub fn empty() -> Self {
        Self { entries: std::array::from_fn(|_| None), len: 0 }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn peers(&self) -> impl Iterator<Item = (&str, &P)> {
        self.entries[..self.len].iter().filter_map(|entry| entry.as_deref().and_then(|entry| entry.presence.as_deref().map(|presence| (entry.actor.as_str(), presence))))
    }

    fn upsert(&self, actor: String, presence: P, received_at_ms: i64) -> Result<(Self, Option<Arc<PresencePeerEntry<P>>>), String> {
        if actor.is_empty() || actor.len() > PRESENCE_PEER_ID_BYTES {
            return Err("presence peer actor is empty or exceeds its fixed byte authority".into());
        }
        let mut next = self.clone_aliases();
        let mut index = 0usize;
        while index < next.len && next.entries[index].as_ref().is_some_and(|entry| entry.actor.as_str() < actor.as_str()) {
            index += 1;
        }
        if next.entries.get(index).and_then(Option::as_ref).is_some_and(|entry| entry.actor.as_str() == actor.as_str()) {
            let retired = next.entries[index].replace(Arc::new(PresencePeerEntry::new(actor, Arc::new(presence), received_at_ms)));
            return Ok((next, retired));
        }
        if next.len == PRESENCE_PEER_SLOTS {
            return Err("presence peer root exceeds its fixed item authority".into());
        }
        for cursor in (index..next.len).rev() {
            next.entries[cursor + 1] = next.entries[cursor].take();
        }
        next.entries[index] = Some(Arc::new(PresencePeerEntry::new(actor, Arc::new(presence), received_at_ms)));
        next.len += 1;
        Ok((next, None))
    }

    fn remove(&self, actor: &str) -> (Self, Option<Arc<PresencePeerEntry<P>>>) {
        let mut next = self.clone_aliases();
        let Some(index) = next.entries[..next.len].iter().position(|entry| entry.as_ref().is_some_and(|entry| entry.actor.as_str() == actor)) else {
            return (next, None);
        };
        let retired = next.entries[index].take();
        for cursor in index..next.len.saturating_sub(1) {
            next.entries[cursor] = next.entries[cursor + 1].take();
        }
        next.len = next.len.saturating_sub(1);
        next.entries[next.len] = None;
        (next, retired)
    }

    fn remove_at(&self, index: usize) -> (Self, Option<Arc<PresencePeerEntry<P>>>) {
        if index >= self.len {
            return (self.clone_aliases(), None);
        }
        let mut next = self.clone_aliases();
        let retired = next.entries[index].take();
        for cursor in index..next.len.saturating_sub(1) {
            next.entries[cursor] = next.entries[cursor + 1].take();
        }
        next.len = next.len.saturating_sub(1);
        next.entries[next.len] = None;
        (next, retired)
    }

    fn retain_received(&self, oldest_allowed_ms: i64) -> (Self, PresencePeersRetiredEntries<P>) {
        let mut next = Self::empty();
        let mut retired = PresencePeersRetiredEntries::empty();
        for entry in self.entries[..self.len].iter().filter_map(Option::as_ref) {
            if entry.received_at_ms >= oldest_allowed_ms {
                next.entries[next.len] = Some(entry.clone());
                next.len += 1;
            } else {
                retired.entries[retired.len] = Some(entry.clone());
                retired.len += 1;
            }
        }
        (next, retired)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PresencePeersCapacityError;

pub struct PresencePeersRetiredEntries<P> {
    entries: std::mem::ManuallyDrop<[Option<Arc<PresencePeerEntry<P>>>; PRESENCE_PEER_SLOTS]>,
    len: usize,
}

impl<P> PresencePeersRetiredEntries<P> {
    pub fn empty() -> Self {
        Self { entries: std::mem::ManuallyDrop::new(std::array::from_fn(|_| None)), len: 0 }
    }

    fn one(entry: Option<Arc<PresencePeerEntry<P>>>) -> Self {
        let mut retired = Self::empty();
        if let Some(entry) = entry {
            retired.entries[0] = Some(entry);
            retired.len = 1;
        }
        retired
    }

    pub fn append(&mut self, other: &mut Self) -> Result<(), PresencePeersCapacityError> {
        if self.len.saturating_add(other.len) > PRESENCE_PEER_SLOTS {
            return Err(PresencePeersCapacityError);
        }
        for index in 0..other.len {
            if let Some(entry) = other.entries[index].take() {
                self.entries[self.len] = Some(entry);
                self.len += 1;
            }
        }
        other.len = 0;
        Ok(())
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }
}

impl<P> Drop for PresencePeersRetiredEntries<P> {
    fn drop(&mut self) {
        debug_assert!(self.is_empty(), "nonterminal app-typed presence retirement entries reached Drop");
    }
}

pub struct PresencePeersRetirement<P> {
    root: std::mem::ManuallyDrop<Option<Arc<PresencePeersRoot<P>>>>,
    owned_root: std::mem::ManuallyDrop<Option<PresencePeersRoot<P>>>,
    retired: std::mem::ManuallyDrop<PresencePeersRetiredEntries<P>>,
    waiting: std::mem::ManuallyDrop<Option<Arc<PresencePeerEntry<P>>>>,
    entry: std::mem::ManuallyDrop<Option<PresencePeerEntry<P>>>,
    active: std::mem::ManuallyDrop<Option<Box<dyn ErasedSnapshotRetirement>>>,
    factory: Arc<dyn SnapshotRetirementFactory<P>>,
    cursor: usize,
}

pub struct PresencePeersPublication<P> {
    base_root: std::mem::ManuallyDrop<Option<Arc<PresencePeersRoot<P>>>>,
    candidate: std::mem::ManuallyDrop<Option<PresencePeersRoot<P>>>,
    created: std::mem::ManuallyDrop<PresencePeersRetiredEntries<P>>,
    retired: std::mem::ManuallyDrop<PresencePeersRetiredEntries<P>>,
    active: std::mem::ManuallyDrop<Option<PresencePeersRetirement<P>>>,
    factory: Arc<dyn SnapshotRetirementFactory<P>>,
    prune_cursor: usize,
    pruning_complete: bool,
}

pub struct PresencePeersCommit<P> {
    base_root: Arc<PresencePeersRoot<P>>,
    root: Arc<PresencePeersRoot<P>>,
    retirement: Option<PresencePeersRetirement<P>>,
    factory: Arc<dyn SnapshotRetirementFactory<P>>,
}

