            Ok(DurableOwnedThreeStoreCommitAdvanceV1::Complete) => DurableOwnedMapRecoveryAdvanceV1::Complete,
            Err(error) => DurableOwnedMapRecoveryAdvanceV1::Fault(error),
        }
    }

