        .begin_apply_batch(semio_framework_job::OperationId(22), store.generation_now(), store.content_revision_now(), "retained-test".into(), vec![DemoMutation::SetN(SetN { n: 4 })], None, HistoryLane::Document, Some(&behind), None)
