    assert!(matches!(remote.try_pop_front().expect("second bounded pop"), Some(BackboneMessage::Ack { op_ids }) if op_ids == vec!["second"]));
    assert!(remote.try_pop_front().expect("terminal bounded pop").is_none());
}

