pub const PLAYBOOK_BUILTIN_KINDS: &[&str] = &["text", "longText", "number", "slider", "boolean", "single", "multi", "date", "color", "vector", "note", "image", "file"];

pub fn is_extension_block_kind(kind: &str) -> bool {
    !PLAYBOOK_BUILTIN_KINDS.contains(&kind)
}

