            id: def.id,
            label: def.label,
            body_key: def.body_key,
            surface_kind: contract_surface_kind(def.surface_kind),
            icon_id: def.icon_id,
            measures: def.options.measures,
            engagement: def.options.engagement.as_option().cloned(),
            actions: def.actions,
