        /// 🚫️async: E1 pure filter — see `capabilities_of`'s own comment above.
        pub fn standards(&self) -> impl Iterator<Item = &ArtifactCapability> {
            self.capabilities().filter(|capability| capability.kind().as_str() == "standard")
        }

