            for spec in specs {
                require_declared_capability_or_record(&self.definition, &mut self.definition_error, &ArtifactCapabilityKind::grammar(), ArtifactIdentityClaim::new(ArtifactIdentityNamespace::grammar(), spec.id).map(|claim| vec![claim]));
            }
