    }

    impl FlowExtensionContribution {
        /// 🏗️ Creates one non-empty typed flow-extension contribution identity.
        pub fn new(kind: FlowExtensionContributionKind, id: impl Into<String>) -> Result<Self, PluginAssemblyError> {
            let id = id.into();
