    /// factory handle and therefore cannot grant execution authority by itself.
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub struct ArtifactToolPublicContract {
        pub(crate) owner: ToolOwnerWitness,
        pub(crate) controller_id: String,
        pub(crate) tool_id: String,
        pub(crate) schema_id: String,
        pub(crate) max_raw_wire_bytes: usize,
        pub(crate) publication_lanes: &'static [ArtifactToolPublicationLane],
    }

    /// 🧰️ Compiler-bound registration context passed only to `ArtifactApp`'s explicit hook.
    pub struct ArtifactToolFactoryRegistry<'a, A: ArtifactApp> {
        bus: &'a semio_framework::ActionBus,
        controller_id: &'a str,
        registrations: BTreeMap<String, ArtifactToolRegistration>,
        marker: std::marker::PhantomData<A>,
    }

    impl<'a, A: ArtifactApp> ArtifactToolFactoryRegistry<'a, A> {
        fn new(bus: &'a semio_framework::ActionBus, controller_id: &'a str) -> Self {
            Self { bus, controller_id, registrations: BTreeMap::new(), marker: std::marker::PhantomData }
        }

        pub fn controller_id(&self) -> &str {
            self.controller_id
        }

        pub fn register<F>(&mut self, factory: F) -> Result<(), Fault>
        where
            F: ArtifactOwnedToolJobFactory<Owner = A>,
        {
            if F::DOCUMENT_SCHEMA != A::DOCUMENT_SCHEMA || factory.payload_schema_id().trim().is_empty() {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.owner-schema"), "app-owned factory schema does not match its concrete ArtifactApp owner"));
            }
            let expected = F::TOOL_IDS.iter().copied().collect::<BTreeSet<_>>();
            let actual = factory.keys().iter().map(|key| key.tool_id.as_str()).collect::<BTreeSet<_>>();
            if expected.is_empty() || expected != actual || factory.keys().iter().any(|key| key.controller_id != self.controller_id) {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.owner-key"), "app-owned factory keys are not an exact live-controller/tool bijection"));
            }
            let publication = F::PUBLICATION_CONTRACTS.iter().map(|contract| (contract.tool_id, contract.lanes)).collect::<BTreeMap<_, _>>();
            if publication.len() != F::PUBLICATION_CONTRACTS.len()
                || publication.keys().copied().collect::<BTreeSet<_>>() != expected
                || publication.values().any(|lanes| lanes.is_empty() || (lanes.contains(&ArtifactToolPublicationLane::HostOnly) && lanes.len() != 1))
            {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.publication-contract"), "app-owned factory lacks an exact nonempty per-tool publication-lane contract"));
            }
            if factory.classification() != semio_framework::InteractiveJobClassification::Migrated {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.owner-classification"), "app-owned factory must be explicitly Migrated"));
            }
            let owner = ToolOwnerWitness::of::<A>();
            let schema_id = factory.payload_schema_id().to_string();
            let contract = factory.execution_contract();
            let factory_type_id = std::any::TypeId::of::<F>();
            let factory_type_name = std::any::type_name::<F>();
            let keys = factory.keys().to_vec();
            self.bus.register_once(factory).map_err(|error| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.owner-registration"), error.to_string()))?;
            for key in keys {
                if self.registrations.contains_key(&key.tool_id) {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.owner-duplicate"), format!("duplicate app-owned tool {}", key.tool_id)));
                }
                let publication_lanes = publication.get(key.tool_id.as_str()).copied().expect("validated exact tool publication contract");
                self.registrations.insert(
                    key.tool_id.clone(),
                    ArtifactToolRegistration {
                        owner,
                        key,
                        schema_id: schema_id.clone(),
                        contract,
                        factory_type_id,
                        factory_type_name,
                        publication_lanes,
                        latest_wins_target: |command| command.downcast_ref::<<F::Owner as ArtifactApp>::Command>().and_then(F::latest_wins_target),
                        latest_wins_command_disposer: || F::build_latest_wins_command_disposer().map(|owner| Box::new(owner) as Box<dyn std::any::Any + Send>),
                    },
                );
            }
            Ok(())
        }

        fn finish(self) -> BTreeMap<String, ArtifactToolRegistration> {
            self.registrations
        }
    }

    /// 📤️ Per-chunk byte cap of the segmented-download lane. Mirror of the ONE schema-owned chunk
    /// contract — `🎭️actor/📮️shard-client/📤️segmented-download/🧬️schema/🔣️.json` +
    /// `🧫️fixtures/🔣️.json`'s `contract.chunkBytes`, mirrored on the host side by
    /// `SEGMENTED_DOWNLOAD_CONTRACT` and interpolated into the generated shard worker as
    /// `SEGMENTED_DOWNLOAD_CHUNK_BYTES` — held equal to that fixture by this crate's own law
    /// [`segmented_download_constants_mirror_the_schema_owned_contract`], so a literal edited in one
    /// hop alone fails closed instead of turning a correct producer into a runtime fault.
    pub(crate) const ARTIFACT_OUTPUT_CHUNK_BYTES: usize = 4_096;
    /// 📤️ Largest payload ONE segmented download may carry, end to end. Same contract, same law:
    /// `contract.maximumTotalBytes`, which the host drain enforces as its own default total cap.
    /// A producer that declares more than this is refused at construction
    /// ([`ArtifactOutputChunks::admit_maximum`]) rather than mid-drain, so an over-cap export becomes
    /// a notice in the app that asked for it and never a shard-worker fault.
    pub(crate) const ARTIFACT_SEGMENTED_DOWNLOAD_TOTAL_BYTES: usize = 33_554_432;
    const ARTIFACT_OUTPUT_METADATA_BYTES: usize = 4_096;
    const ARTIFACT_SEGMENTED_HANDLE_ENCODING: &str = "semio-segmented-handle-v1";

    #[derive(Debug)]
    struct ArtifactFixedQueue<T> {
        items: std::collections::VecDeque<T>,
        capacity: usize,
        allocation_admitted: bool,
    }

    impl<T> ArtifactFixedQueue<T> {
        fn new(capacity: usize) -> Self {
            let mut items = std::collections::VecDeque::new();
            let allocation_admitted = items.try_reserve_exact(capacity).is_ok();
            Self { items, capacity, allocation_admitted }
        }

        fn push(&mut self, value: T) -> Result<(), T> {
            if !self.allocation_admitted || self.items.len() >= self.capacity {
                return Err(value);
            }
            self.items.push_back(value);
            Ok(())
        }

        fn pop(&mut self) -> Option<T> {
            self.items.pop_front()
        }

        fn len(&self) -> usize {
            self.items.len()
        }
    }

    #[derive(Debug)]
    struct ArtifactOutputChunksState {
        chunks: ArtifactFixedQueue<Vec<u8>>,
    }

    #[derive(Debug)]
    struct ArtifactOutputChunksInner {
        state: std::sync::Mutex<ArtifactOutputChunksState>,
        bytes: std::sync::atomic::AtomicUsize,
        bytes_remaining: std::sync::atomic::AtomicUsize,
        remaining: std::sync::atomic::AtomicUsize,
        slots: usize,
        maximum: usize,
        sealed: std::sync::atomic::AtomicBool,
    }

    /// 🧵️ Operation-owned segmented output. Every producer move is bounded to one 4 KiB chunk;
    /// terminal completion transfers the queue without flattening, rescanning, or copying it.
    #[derive(Clone, Debug)]
    pub struct ArtifactOutputChunks {
        inner: std::sync::Arc<ArtifactOutputChunksInner>,
    }

    impl ArtifactOutputChunks {
        /// 📏️ The exact byte cap [`Self::push`] enforces on ONE chunk — the wire constant an app must slice its
        /// payload by. Exported because every app that fills a segmented output re-declared it as its own
        /// literal, and a literal that drifts from `push`'s check turns a correct producer into a
        /// `segmented-output-limit` fault at runtime.
        pub const CHUNK_BYTES: usize = ARTIFACT_OUTPUT_CHUNK_BYTES;

        /// 📏️ Largest payload ONE segmented download may carry — the same
        /// `contract.maximumTotalBytes` the host drain defaults its total cap to. An app must refuse a
        /// payload above this with a NOTICE of its own; publishing it would be refused mid-drain, where
        /// the user sees a dead download instead of an answer.
        pub const MAXIMUM_TOTAL_BYTES: usize = ARTIFACT_SEGMENTED_DOWNLOAD_TOTAL_BYTES;

        /// 📏️ The declared output budget one segmented download may be built with, or the bound it
        /// violated. Checked HERE, at construction, so an over-cap producer is refused before it opens a
        /// download handle the host would then drain into a fault.
        pub fn admit_maximum(maximum: usize) -> Result<usize, Fault> {
            if maximum == 0 || maximum > ARTIFACT_SEGMENTED_DOWNLOAD_TOTAL_BYTES {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.segmented-download-total-over-cap"), "segmented download declares an empty or over-cap total byte budget"));
            }
            Ok(maximum)
        }

        pub fn new(maximum: usize) -> Self {
            let slots = maximum / ARTIFACT_OUTPUT_CHUNK_BYTES + usize::from(!maximum.is_multiple_of(ARTIFACT_OUTPUT_CHUNK_BYTES));
            Self {
                inner: std::sync::Arc::new(ArtifactOutputChunksInner {
                    state: std::sync::Mutex::new(ArtifactOutputChunksState { chunks: ArtifactFixedQueue::new(slots) }),
                    bytes: std::sync::atomic::AtomicUsize::new(0),
                    bytes_remaining: std::sync::atomic::AtomicUsize::new(0),
                    remaining: std::sync::atomic::AtomicUsize::new(0),
                    slots,
                    maximum,
                    sealed: std::sync::atomic::AtomicBool::new(false),
                }),
            }
        }

        pub fn push(&self, chunk: Vec<u8>) -> Result<usize, Fault> {
            if self.inner.sealed.load(std::sync::atomic::Ordering::Acquire) || chunk.is_empty() || chunk.len() > ARTIFACT_OUTPUT_CHUNK_BYTES {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.segmented-output-limit"), "segmented output is sealed, empty, oversized, or exceeds its exact byte cap"));
            }
            let mut state = self.inner.state.try_lock().map_err(|_| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.segmented-output-busy"), "segmented output slot authority is busy or poisoned"))?;
            let bytes = self.inner.bytes.load(std::sync::atomic::Ordering::Acquire);
            let next = bytes.checked_add(chunk.len()).filter(|next| *next <= self.inner.maximum);
            if self.inner.sealed.load(std::sync::atomic::Ordering::Acquire) || state.chunks.len() >= self.inner.slots || next.is_none() {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.segmented-output-limit"), "segmented output is sealed, empty, oversized, has no pre-admitted slot, or exceeds its exact byte cap"));
            }
            state.chunks.push(chunk).map_err(|_| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.segmented-output-capacity"), "segmented output fixed slot allocation was not admitted"))?;
            self.inner.remaining.store(state.chunks.len(), std::sync::atomic::Ordering::Release);
            let next = next.expect("validated segmented byte total");
            self.inner.bytes.store(next, std::sync::atomic::Ordering::Release);
            self.inner.bytes_remaining.store(next, std::sync::atomic::Ordering::Release);
            Ok(next)
        }

        pub fn seal(&self) -> Result<usize, Fault> {
            let _state = self.inner.state.try_lock().map_err(|_| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.segmented-output-busy"), "segmented output slot authority is busy or poisoned"))?;
            if self.inner.sealed.compare_exchange(false, true, std::sync::atomic::Ordering::AcqRel, std::sync::atomic::Ordering::Acquire).is_err() {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.segmented-output-duplicate-seal"), "segmented output was sealed more than once"));
            }
            Ok(self.inner.bytes.load(std::sync::atomic::Ordering::Acquire))
        }

        pub fn bytes(&self) -> usize {
            self.inner.bytes.load(std::sync::atomic::Ordering::Acquire)
        }

        pub fn chunks_remaining(&self) -> usize {
            self.inner.remaining.load(std::sync::atomic::Ordering::Acquire)
        }

        pub fn bytes_remaining(&self) -> usize {
            self.inner.bytes_remaining.load(std::sync::atomic::Ordering::Acquire)
        }

        pub fn slot_capacity(&self) -> usize {
            self.inner.slots
        }

        pub fn take_chunk(&self) -> Result<Option<Vec<u8>>, Fault> {
            if !self.inner.sealed.load(std::sync::atomic::Ordering::Acquire) {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.segmented-output-unsealed"), "segmented output cannot be consumed before it is sealed"));
            }
            let mut state = self.inner.state.try_lock().map_err(|_| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.segmented-output-busy"), "segmented output slot authority is busy or poisoned"))?;
            let chunk = state.chunks.pop();
            self.inner.remaining.store(state.chunks.len(), std::sync::atomic::Ordering::Release);
            if let Some(chunk) = chunk.as_ref() {
                let remaining = self.inner.bytes_remaining.load(std::sync::atomic::Ordering::Acquire);
                self.inner.bytes_remaining.store(remaining.checked_sub(chunk.len()).expect("queued output byte census"), std::sync::atomic::Ordering::Release);
            }
            Ok(chunk)
        }

        pub fn close_take_chunk(&self) -> Result<Option<Vec<u8>>, Fault> {
            let mut state = self.inner.state.try_lock().map_err(|_| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.segmented-output-busy"), "segmented output disposal authority is busy or poisoned"))?;
            let chunk = state.chunks.pop();
            self.inner.remaining.store(state.chunks.len(), std::sync::atomic::Ordering::Release);
            if let Some(chunk) = chunk.as_ref() {
                let remaining = self.inner.bytes_remaining.load(std::sync::atomic::Ordering::Acquire);
                self.inner.bytes_remaining.store(remaining.checked_sub(chunk.len()).expect("queued output byte census"), std::sync::atomic::Ordering::Release);
            }
            Ok(chunk)
        }

        fn is_sealed(&self) -> bool {
            self.inner.sealed.load(std::sync::atomic::Ordering::Acquire)
        }

        fn same_operation(&self, other: &Self) -> bool {
            std::sync::Arc::ptr_eq(&self.inner, &other.inner)
        }
    }

    /// 🎞️ Segmented structured media returned by an interactive export without a terminal String.
    #[derive(Clone, Debug)]
    pub struct ArtifactMediaExportResult {
        pub media_type: MediaType,
        pub schema: String,
        pub mime_type: String,
        pub chunks: ArtifactOutputChunks,
    }

    impl ArtifactMediaExportResult {
        pub fn structured(media_type: MediaType, schema: impl Into<String>, mime_type: impl Into<String>, chunks: ArtifactOutputChunks) -> Result<Self, Fault> {
            let schema = schema.into();
            let mime_type = mime_type.into();
            if schema.len() > ARTIFACT_OUTPUT_METADATA_BYTES || mime_type.is_empty() || mime_type.len() > 128 || !chunks.is_sealed() {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.segmented-media-metadata"), "segmented media schema or MIME type is invalid, or its chunks are unsealed"));
            }
            Ok(Self { media_type, schema, mime_type, chunks })
        }

        fn into_batch_media(self) -> Result<Media, MediaError> {
            let mut bytes = Vec::with_capacity(self.chunks.bytes());
            while let Some(chunk) = self.chunks.take_chunk().map_err(|error| MediaError::Payload(self.schema.clone(), error.message))? {
                bytes.extend_from_slice(&chunk);
            }
            let json = String::from_utf8(bytes).map_err(|error| MediaError::Payload(self.schema.clone(), error.to_string()))?;
            Ok(Media { media_type: self.media_type, payload: MediaPayload::Structured { schema: self.schema, json } })
        }
    }

    /// ⬇️ Segmented action output retained by the live app until the host takes every chunk.
    pub struct ArtifactDownloadOutput {
        pub filename: String,
        pub mime_type: String,
        pub encoding: Option<String>,
        pub chunks: ArtifactOutputChunks,
        media_export_handle: Option<ArtifactMediaExportHandle>,
    }

    impl ArtifactDownloadOutput {
        pub fn new(filename: impl Into<String>, mime_type: impl Into<String>, encoding: Option<String>, chunks: ArtifactOutputChunks) -> Result<Self, Fault> {
            let filename = filename.into();
            let mime_type = mime_type.into();
            let encoding_bytes = encoding.as_ref().map_or(0, String::len);
            let marker_bytes = ARTIFACT_SEGMENTED_HANDLE_ENCODING.len().checked_add(1).and_then(|bytes| bytes.checked_add(encoding_bytes.max("identity".len())));
            if filename.len() > ARTIFACT_OUTPUT_METADATA_BYTES || mime_type.len() > ARTIFACT_OUTPUT_METADATA_BYTES || marker_bytes.is_none_or(|bytes| bytes > ARTIFACT_OUTPUT_METADATA_BYTES) || !chunks.is_sealed() {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.segmented-download-metadata"), "segmented download metadata is oversized or its chunks are unsealed"));
            }
            Ok(Self { filename, mime_type, encoding, chunks, media_export_handle: None })
        }

        fn from_media_export(handle: ArtifactMediaExportHandle, mime_type: impl Into<String>, chunks: ArtifactOutputChunks) -> Result<Self, Fault> {
            let mut output = Self::new(String::new(), mime_type, None, chunks)?;
            output.media_export_handle = Some(handle);
            Ok(output)
        }

        fn owns_media_export(&self, handle: &ArtifactMediaExportHandle) -> bool {
            self.media_export_handle.as_ref() == Some(handle)
        }

        /// 🧪️ Test-only door to the media-export constructor the SDK keeps private.
        #[cfg(test)]
        pub(crate) fn test_from_media_export(handle: ArtifactMediaExportHandle, mime_type: impl Into<String>, chunks: ArtifactOutputChunks) -> Result<Self, Fault> {
            Self::from_media_export(handle, mime_type, chunks)
        }

        #[cfg(test)]
        fn handle_encoding(&self) -> String {
            format!("{ARTIFACT_SEGMENTED_HANDLE_ENCODING}:{}", self.encoding.as_deref().unwrap_or("identity"))
        }

        fn terminal_is_empty(&self) -> bool {
            self.chunks.chunks_remaining() == 0 && self.chunks.bytes_remaining() == 0
        }
    }

    pub const TYPED_OPERATION_RESULT_PAGE_BYTES: usize = 4_096;
    pub const TYPED_OPERATION_MAXIMUM_RETRIES: u8 = 2;

    //#region 📊️PublicationUnitCensus
    /// 📊️ What the typed-operation publication ladder spends its units on, process-wide. One unit is one
    /// step of the publication state machine; a HOST TURN is one or more units
    /// ([`TYPED_OPERATION_PUBLICATION_PUMPS`]), so "how many turns does one mutation cost" is only
    /// answerable by splitting the units by the ladder that ran them.
    ///
    /// 🧾️ Before wave B54 every unit was its own host round trip, and one `deleteSelection` on a
    /// one-object document spent 104–235 of them (wave B44 §2.3) with no way to say which ladder owned
    /// them. This census is that instrument: `store` is the artifact/config/draft apply-batch phase
    /// machine, `page` a unit that produced a result page the host must acknowledge (the only unit that
    /// is INHERENTLY one round trip), `retirement` the slot-release ladder, `worker` a mounted job step,
    /// `latest_wins` the coalesced-command lane, and `idle` a unit that found nothing advanceable.
    /// Ticket 26/09/02/PUZZLE-3D-END-TO-END wave B54.
    #[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
    pub struct TypedOperationUnitCensus {
        pub units: u64,
        pub store: u64,
        pub page: u64,
        pub retirement: u64,
        pub worker: u64,
        pub latest_wins: u64,
        pub idle: u64,
    }

    impl std::fmt::Display for TypedOperationUnitCensus {
        fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(formatter, "units={} store={} page={} retirement={} worker={} latestWins={} idle={}", self.units, self.store, self.page, self.retirement, self.worker, self.latest_wins, self.idle)
        }
    }

    impl std::ops::Sub for TypedOperationUnitCensus {
        type Output = Self;

        fn sub(self, base: Self) -> Self {
            Self {
                units: self.units.saturating_sub(base.units),
                store: self.store.saturating_sub(base.store),
                page: self.page.saturating_sub(base.page),
                retirement: self.retirement.saturating_sub(base.retirement),
                worker: self.worker.saturating_sub(base.worker),
                latest_wins: self.latest_wins.saturating_sub(base.latest_wins),
                idle: self.idle.saturating_sub(base.idle),
            }
        }
    }

    /// 📊️ One counted ladder of the publication census.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum TypedOperationUnitKind {
        Store,
        Page,
        Retirement,
        Worker,
        LatestWins,
        Idle,
    }

    static PUBLICATION_UNITS: [std::sync::atomic::AtomicU64; 7] = [
        std::sync::atomic::AtomicU64::new(0),
        std::sync::atomic::AtomicU64::new(0),
        std::sync::atomic::AtomicU64::new(0),
        std::sync::atomic::AtomicU64::new(0),
        std::sync::atomic::AtomicU64::new(0),
        std::sync::atomic::AtomicU64::new(0),
        std::sync::atomic::AtomicU64::new(0),
    ];

    /// 📊️ Counts one publication unit against its ladder. Relaxed ordering: the census is an attribution
    /// instrument read between dispatches, never a synchronization point.
    pub fn record_typed_operation_unit(kind: TypedOperationUnitKind) {
        let index = match kind {
            TypedOperationUnitKind::Store => 1,
            TypedOperationUnitKind::Page => 2,
            TypedOperationUnitKind::Retirement => 3,
            TypedOperationUnitKind::Worker => 4,
            TypedOperationUnitKind::LatestWins => 5,
            TypedOperationUnitKind::Idle => 6,
        };
        PUBLICATION_UNITS[0].fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        PUBLICATION_UNITS[index].fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }

    /// 📊️ The census as of now. Subtract two readings to attribute one dispatch.
    pub fn typed_operation_unit_census() -> TypedOperationUnitCensus {
        let read = |index: usize| PUBLICATION_UNITS[index].load(std::sync::atomic::Ordering::Relaxed);
        TypedOperationUnitCensus { units: read(0), store: read(1), page: read(2), retirement: read(3), worker: read(4), latest_wins: read(5), idle: read(6) }
    }
    //#endregion 📊️PublicationUnitCensus
    /// 🏃️ Upper bound on worker pump iterations one reactor turn spends on a single mounted worker
    /// session — a Worker-stage typed operation or a live artifact-envelope decode.
    pub const INTERACTIVE_TURN_WORKER_PUMPS: usize = 256;
    /// ⏱️ Wall-clock slice one reactor turn spends driving one mounted worker session (half the interactive lane ceiling).
    pub const INTERACTIVE_TURN_WORKER_WALL_US: u64 = 4_000;
    /// 🏃️ Publication units one continuation unit may run before it hands its turn back, the exact twin of
    /// [`INTERACTIVE_TURN_WORKER_PUMPS`] for the publication ladder.
    pub const TYPED_OPERATION_PUBLICATION_PUMPS: usize = 256;
    /// 🩺️ Consecutive unchanged publication units before one stalled typed operation is named on the
    /// diagnostic channel — far above any legitimate multi-unit ladder step, so a healthy operation
    /// never prints.
    const TYPED_OPERATION_STALL_WITNESS_FLOOR: u64 = 64;
    /// 🛑️ Unchanged `Publishing`-stage units before the operation is terminated with
    /// `interactive-job.publication-stalled` rather than left spinning. A power of two so the stall
    /// trace's own streak rule names it on the way past.
    const TYPED_OPERATION_STALL_FAULT_CEILING: u64 = 4_096;
    /// 🧮️ Folds the publication ladder's monotone progress term into the one-`u64` witness key the
    /// streak counter remembers between turns, so two witnesses that differ ONLY in how far the
    /// publication has advanced are never mistaken for the same one.
    const TYPED_OPERATION_STALL_PROGRESS_MIX: u64 = 0x9E37_79B9_7F4A_7C15;
    /// 🩺️ The stage code [`ArtifactApp::typed_operation_stall_witness`] gives a `Publishing` operation.
    const TYPED_OPERATION_STALL_PUBLISHING_STAGE: u8 = 1;
    const TYPED_OPERATION_HOST_OUTBOX_SLOTS: usize = 64;
    const TYPED_OPERATION_FAULT_BYTES: usize = 256;
    /// 🧾️ Frames a bounded publication fault as `<code>\u{1f}<message>`. The `FaultCode` values the
    /// contract freezes (`transaction.instance-busy`, `toolRun.busy`, `app.read-only`, …) are the whole
    /// point of a refusal: erasing them at the publication boundary — which is what happened until this
    /// framing landed — left every migrated dispatch answering `app.message` and no caller able to
    /// branch on why it was refused. `0x1f` is the one byte a `FaultCode` can never contain.
    const TYPED_OPERATION_FAULT_SEPARATOR: u8 = 0x1f;
    const TYPED_OPERATION_FAULT_CODE_BYTES: usize = 64;
    const TYPED_OPERATION_FAULT_PAGE_BYTES: usize = TYPED_OPERATION_FAULT_CODE_BYTES + 1 + TYPED_OPERATION_FAULT_BYTES;

    /// 🧾️ Splits a Fault-lane page back into its exact frozen code and its detail. A page with no
    /// separator predates the framing's producer and keeps the generic app-owned-output code.
    pub(crate) fn decode_typed_operation_fault_page(bytes: &[u8]) -> (FaultCode, String) {
        match bytes.iter().position(|byte| *byte == TYPED_OPERATION_FAULT_SEPARATOR) {
            Some(index) if index != 0 => (FaultCode::new(String::from_utf8_lossy(&bytes[..index]).into_owned()), String::from_utf8_lossy(&bytes[index + 1..]).into_owned()),
            Some(index) => (FaultCode::new("interactive-job.app-owned-output"), String::from_utf8_lossy(&bytes[index + 1..]).into_owned()),
            None => (FaultCode::new("interactive-job.app-owned-output"), String::from_utf8_lossy(bytes).into_owned()),
        }
    }

    struct ArtifactBoundedToolFault {
        bytes: [u8; TYPED_OPERATION_FAULT_BYTES],
        len: usize,
        code: [u8; TYPED_OPERATION_FAULT_CODE_BYTES],
        code_len: usize,
    }

    impl ArtifactBoundedToolFault {
        /// 🧾️ Retains a terminal job fault's detail bytes (bounded) so the publication that follows
        /// a cancelled lease reports the real cause instead of a generic cancellation.
        fn from_payload(detail: &semio_framework_job::RetainedJobPayload) -> Self {
            let mut bounded = Self { bytes: [0; TYPED_OPERATION_FAULT_BYTES], len: 0, code: [0; TYPED_OPERATION_FAULT_CODE_BYTES], code_len: 0 };
            for page in 0..detail.page_count() {
                let Some(bytes) = detail.page(page) else { break };
                for byte in bytes {
                    if bounded.len == bounded.bytes.len() {
                        return bounded;
                    }
                    bounded.bytes[bounded.len] = *byte;
                    bounded.len += 1;
                }
            }
            bounded
        }

        /// 🧾️ Recovers the canonical reducer refusal before retaining its bounded publication frame.
        fn from_retained_fault(detail: &semio_framework_job::RetainedJobPayload) -> Self {
            let payload = Self::from_payload(detail);
            let (code, message) = decode_typed_operation_fault_page(payload.as_bytes());
            let fault = crate::retained_command::reducer_fault_of_detail(&message).unwrap_or_else(|| Fault::new(FaultOrigin::Framework, code, message));
            Self::from_fault(&fault)
        }

        fn from_fault(fault: &Fault) -> Self {
            let mut bounded = Self { bytes: [0; TYPED_OPERATION_FAULT_BYTES], len: 0, code: [0; TYPED_OPERATION_FAULT_CODE_BYTES], code_len: 0 };
            for scalar in fault.message.chars() {
                let width = scalar.len_utf8();
                if bounded.len.saturating_add(width) > bounded.bytes.len() {
                    break;
                }
                scalar.encode_utf8(&mut bounded.bytes[bounded.len..bounded.len + width]);
                bounded.len += width;
            }
            for scalar in fault.code.0.chars() {
                let width = scalar.len_utf8();
                if scalar == TYPED_OPERATION_FAULT_SEPARATOR as char || bounded.code_len.saturating_add(width) > bounded.code.len() {
                    bounded.code_len = 0;
                    break;
                }
                scalar.encode_utf8(&mut bounded.code[bounded.code_len..bounded.code_len + width]);
                bounded.code_len += width;
            }
            bounded
        }

        fn into_fault(self) -> Fault {
            let detail = String::from_utf8_lossy(&self.bytes[..self.len]).into_owned();
            let code = (self.code_len != 0).then(|| FaultCode::new(String::from_utf8_lossy(&self.code[..self.code_len]).into_owned())).unwrap_or_else(|| FaultCode::new("interactive-job.app-owned-output"));
            Fault::new(FaultOrigin::Framework, code, detail)
        }

        /// 🧾️ The Fault-lane page's own framing, `<code>\u{1f}<message>` — see
        /// [`TYPED_OPERATION_FAULT_SEPARATOR`]. `as_bytes` stays the message alone, because it is the
        /// bounded retained detail the language-neutral fault-bound oracle prices.
        fn framed_page_bytes(&self, buffer: &mut [u8; TYPED_OPERATION_FAULT_PAGE_BYTES]) -> usize {
            if self.code_len == 0 {
                buffer[..self.len].copy_from_slice(&self.bytes[..self.len]);
                return self.len;
            }
            buffer[..self.code_len].copy_from_slice(&self.code[..self.code_len]);
            buffer[self.code_len] = TYPED_OPERATION_FAULT_SEPARATOR;
            buffer[self.code_len + 1..self.code_len + 1 + self.len].copy_from_slice(&self.bytes[..self.len]);
            self.code_len + 1 + self.len
        }

        fn as_bytes(&self) -> &[u8] {
            &self.bytes[..self.len]
        }
    }

    enum ArtifactToolCompletionValue<A: ArtifactApp> {
        Emit(ArtifactMutationOutcome<<A as ArtifactApp>::Mutation, <A as ArtifactApp>::ConfigMutation, <A as ArtifactApp>::DraftMutation, ArtifactBoundedToolFault>, EphemeralEmit<A>),
        Download(Result<ArtifactDownloadOutput, ArtifactBoundedToolFault>, EphemeralEmit<A>),
    }

