            Ok((job, completion))
        }

        async fn submit_owned_media_export(&mut self, port: &str, app_instance_id: u32) -> Result<ArtifactMediaExportHandle, MediaError> {
            let tool_id = format!("export-media:{port}");
            let fault = |message: String| MediaError::Payload(port.to_string(), message);
            if !self.media_exports.has_capacity() || !self.media_closures.has_capacity() || !self.snapshot_retirements.has_capacity() {
                return Err(fault("fixed media export authority is saturated".into()));
            }
            self.refresh_cache().await.map_err(|error| fault(error.message))?;
            let proof = self.qualified_tool_proof(&tool_id).map_err(|error| fault(error.message))?;
            if !matches!(proof, QualifiedToolProof::AppOwned(_)) {
                return Err(fault("media export did not resolve an app-owned exact factory".into()));
            }
            let raw_wire = protocol::json::to_json_string(&(tool_id.as_str(), port)).into_bytes();
            let key = proof.key();
            let admission = self.tool_jobs.admit_exact_wire(key.controller_id.clone(), key.tool_id.clone(), proof.schema_id(), &raw_wire).map_err(|error| fault(error.to_string()))?;
            if !proof.admits::<A>(&admission) {
                return Err(fault("media export failed exact owner/factory/schema/contract admission".into()));
            }
            let canonical_base_revision = self.store.content_revision();
            let base_revision = semio_framework_job::RevisionId(u64::from_be_bytes(canonical_base_revision[..8].try_into().expect("revision lane width")));
            let generation = semio_framework_job::Generation(self.store.generation());
            let Some(slot) = (0..ARTIFACT_LIVE_OUTPUT_SLOTS).find(|slot| self.media_exports.slot_is_vacant(*slot) && self.media_closures.slot_is_vacant(*slot) && self.snapshot_retirements.slot_is_vacant(*slot)) else {
                return Err(fault("every fixed media export slot already owns a live operation".into()));
            };
            let operation_id = semio_framework_job::allocate_operation_id_in_slot(ARTIFACT_LIVE_OUTPUT_SLOTS as u64, slot as u64);
            let parent_document_id = self.store.envelope().id.clone();
            let seed_handle = artifact_handle_of(&format!("{app_instance_id}/{}/{tool_id}/{}", self.tool_job_controller_id, base_revision.0)).await;
            let operation = semio_framework_job::Operation::new(operation_id, base_revision, generation, (seed_handle.0 as u64) ^ ((seed_handle.0 >> 64) as u64));
            let snapshot_disposer = A::build_snapshot_disposer().ok_or_else(|| fault("media export owner lacks an exact bounded snapshot disposer".into()))?;
            let operation_key = ToolOperationKey { app_instance_id, document: ArtifactDocumentAuthority(app_instance_id), operation_id, base_revision, generation };
            let lease = self.tool_cancellations.begin(operation_key).map_err(|error| fault(error.message))?;
            let (snapshot, config, history) = self.command_cache_inputs();
            let (snapshot_close, snapshot_retention) = ArtifactSnapshotCloseLease::new(&snapshot, snapshot_disposer);
            self.snapshot_retirements.insert_admitted(operation_id.0, snapshot_retention);
            let completion = ArtifactMediaExportCompletion::new();
            let output_credit = ArtifactMediaExportCredit::new(proof.contract().max_output_bytes);
            let output_chunks = ArtifactOutputChunks::new(proof.contract().max_output_bytes);
            let handle = ArtifactMediaExportHandle { app_instance_id, parent_document_id: parent_document_id.clone(), operation_id, base_revision, generation };
            self.media_closures.insert_admitted(
                operation_id.0,
                ActiveMediaExport {
                    handle: handle.clone(),
                    port: port.to_string(),
                    operation,
                    contract: proof.contract(),
                    session: None,
                    session_rejected: None,
                    closing_job: None,
                    retained_outcome: None,
                    output_credit: output_credit.clone(),
                    output_chunks: output_chunks.clone(),
                    completion: completion.clone(),
                    lease,
                    checkpoint_available: false,
                    applied_progress: 0,
                    close_stage: ActiveMediaExportCloseStage::Live,
                },
            );
            let request = ArtifactMediaExportJobRequest {
                operation,
                controller_id: self.tool_job_controller_id.clone(),
                tool_id: tool_id.clone(),
                payload_schema_id: proof.schema_id(),
                contract: proof.contract(),
                app_instance_id,
                parent_document_id,
                canonical_base_revision,
                snapshot,
                snapshot_close,
                config,
                history,
                port: port.to_string(),
                raw_wire: raw_wire.clone(),
                output_credit,
                output_chunks,
                completion,
            };
            let job = A::build_media_export_job(request).map_err(|error| fault(error.message))?.ok_or_else(|| fault(format!("media output port '{port}' is registered but has no concrete resumable producer")))?;
            self.media_closures.get_mut(operation_id.0).expect("pre-admitted media construction owner").closing_job = Some(job.clone());
            let dispatch = self.tool_jobs.dispatch(semio_framework::ToolOperationSpec::new(key.controller_id, key.tool_id, proof.schema_id(), job, operation)).map_err(|error| fault(error.to_string()))?;
            let cancel = self.media_closures.get(operation_id.0).expect("pre-admitted media construction owner").lease.cancel_token();
            let params = semio_framework_job::BatchJobParams {
                operation: operation_id,
                generation,
                cancel,
                config: semio_framework_job::BatchDriveConfig {
                    site: "plugin_media_export_submission",
                    stage: semio_framework_job::InteractiveStage::InteractiveStep,
                    fuel_per_step: proof.contract().max_work_units_per_step,
                    step_budget_us: semio_framework_job::INTERACTIVE_LANE_WALL_US,
                },
                now_us: semio_framework_job::default_now_us,
            };
            let (session, session_rejected) = match semio_framework_job::MountedWorkerJobSession::try_new(dispatch.job, params) {
                Ok(session) => (Some(session), None),
                Err(rejected) => (None, Some(rejected)),
            };
            {
                let active = self.media_closures.get_mut(operation_id.0).expect("pre-admitted media construction owner");
                active.session = session;
                active.session_rejected = session_rejected;
            }
            let active = self.media_closures.remove(operation_id.0).expect("constructed media owner remains exact through submission");
            self.media_exports.insert_admitted(operation_id.0, active);
            self.current_media_export = Some(operation_id.0);
            Ok(handle)
        }

        fn quarantine_media_snapshot(&self, operation_id: u64, active: &ActiveMediaExport) -> Result<(), MediaError> {
            self.snapshot_retirements.get(operation_id).map(|_| ()).ok_or_else(|| MediaError::Payload(active.port.clone(), "media export lost its pre-admitted app-owned snapshot retirement authority".into()))
        }

        fn finish_media_poll(&mut self, operation_id: u64, active: ActiveMediaExport, poll: ArtifactMediaExportPoll) -> Result<ArtifactMediaExportPoll, MediaError> {
            if let Err(error) = self.quarantine_media_snapshot(operation_id, &active) {
                debug_assert!(self.media_exports.can_insert(operation_id));
                self.media_exports.insert_admitted(operation_id, active);
                return Err(error);
            }
            debug_assert!(self.media_closures.can_insert(operation_id));
            self.media_closures.insert_admitted(operation_id, active);
            Ok(poll)
        }

        async fn poll_owned_media_export(&mut self, handle: &ArtifactMediaExportHandle) -> Result<ArtifactMediaExportPoll, MediaError> {
            if !self.media_closures.can_insert(handle.operation_id.0) {
                return Err(MediaError::Payload(handle.parent_document_id.clone(), "media close authority is saturated or already owns this operation".into()));
            }
            if self.media_exports.get(handle.operation_id.0).is_none_or(|active| active.handle != *handle) {
                return Err(MediaError::Payload(handle.parent_document_id.clone(), "unknown or superseded media export handle".into()));
            }
            let mut active = self.media_exports.remove(handle.operation_id.0).expect("checked exact media export owner");
            let pool = semio_framework_async::process_worker_pool(semio_framework_async::WorkerPoolConfig::new(semio_framework_async::ProcessKind::InteractiveNative, std::thread::available_parallelism().map_or(1, std::num::NonZeroUsize::get)));
            #[cfg(target_arch = "wasm32")]
            if let Some(now_ms) = semio_framework_job::default_now_ms() {
                pool.pump(now_ms);
            }
            if active.retained_outcome.is_none() {
                if let Some(rejected) = active.session_rejected.as_mut() {
                    let _ = rejected.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
                    if rejected.terminal_is_empty() {
                        active.session_rejected = None;
                        return self.finish_media_poll(handle.operation_id.0, active, ArtifactMediaExportPoll::Failed("media export mounted session capacity is exhausted".into()));
                    }
                    let poll = active.running_poll();
                    self.media_exports.insert_admitted(handle.operation_id.0, active);
                    return Ok(poll);
                }
                let pump = active.session.as_mut().map(|session| session.pump_one(&pool, semio_framework_async::Lane::Interactive));
                match pump {
                    Some(Ok(semio_framework_job::WorkerJobPoll::Outcome | semio_framework_job::WorkerJobPoll::Terminal)) => {
                        active.retained_outcome = active.session.as_mut().and_then(semio_framework_job::MountedWorkerJobSession::take_checked_out_outcome);
                    }
                    Some(Ok(_)) | Some(Err(_)) => {
                        let poll = active.running_poll();
                        self.media_exports.insert_admitted(handle.operation_id.0, active);
                        return Ok(poll);
                    }
                    None => return self.finish_media_poll(handle.operation_id.0, active, ArtifactMediaExportPoll::Failed("media export lost its mounted session".into())),
                }
            }
            let Some(outcome) = active.retained_outcome.take() else {
                return self.finish_media_poll(handle.operation_id.0, active, ArtifactMediaExportPoll::Failed("media export mounted outcome changed during one host turn".into()));
            };
            match outcome {
                outcome @ (semio_framework_job::StepOutcome::Yield | semio_framework_job::StepOutcome::PreviewReady(_)) => {
                    active.retained_outcome = Some(outcome);
                    if let Err(error) = active.retire_nonterminal_outcome() {
                        return self.finish_media_poll(handle.operation_id.0, active, ArtifactMediaExportPoll::Failed(error.message));
                    }
                    let poll = active.running_poll();
                    self.media_exports.insert_admitted(handle.operation_id.0, active);
                    Ok(poll)
                }
                semio_framework_job::StepOutcome::CheckpointReady(checkpoint) => {
                    if checkpoint.applied_progress < active.applied_progress || checkpoint.state.len() > active.contract.max_output_bytes {
                        return self.finish_media_poll(handle.operation_id.0, active, ArtifactMediaExportPoll::Failed("media export checkpoint is non-monotone or oversized".into()));
                    }
                    active.applied_progress = checkpoint.applied_progress;
                    active.checkpoint_available = true;
                    active.retained_outcome = Some(semio_framework_job::StepOutcome::CheckpointReady(checkpoint));
                    if let Err(error) = active.retire_nonterminal_outcome() {
                        return self.finish_media_poll(handle.operation_id.0, active, ArtifactMediaExportPoll::Failed(error.message));
                    }
                    let poll = active.running_poll();
                    self.media_exports.insert_admitted(handle.operation_id.0, active);
                    Ok(poll)
                }
                semio_framework_job::StepOutcome::Complete(candidate) => {
                    if candidate.output.len() > active.contract.max_output_bytes || active.lease.is_cancelled().await {
                        return self.finish_media_poll(handle.operation_id.0, active, ArtifactMediaExportPoll::Failed("media export was cancelled or its commit candidate exceeded the output cap".into()));
                    }
                    let live_revision_bytes = self.store.content_revision();
                    let live_revision = semio_framework_job::RevisionId(u64::from_be_bytes(live_revision_bytes[..8].try_into().expect("revision lane width")));
                    let live_generation = semio_framework_job::Generation(self.store.generation());
                    if !matches!(semio_framework_job::validate_commit(&active.operation, live_revision, live_generation), semio_framework_job::CommitValidation::Accepted) {
                        return self.finish_media_poll(handle.operation_id.0, active, ArtifactMediaExportPoll::Failed("media export completed against a stale revision or generation".into()));
                    }
                    let result = match active.completion.take() {
                        Ok(Some(Ok(result))) => result,
                        Ok(Some(Err(error))) => return self.finish_media_poll(handle.operation_id.0, active, ArtifactMediaExportPoll::Failed(error.to_string())),
                        Ok(None) => return self.finish_media_poll(handle.operation_id.0, active, ArtifactMediaExportPoll::Failed("media export completed without producer output".into())),
                        Err(error) => return self.finish_media_poll(handle.operation_id.0, active, ArtifactMediaExportPoll::Failed(error.message)),
                    };
                    let output_bytes = match active.output_credit.validate_terminal() {
                        Ok(output_bytes) => output_bytes,
                        Err(error) => return self.finish_media_poll(handle.operation_id.0, active, ArtifactMediaExportPoll::Failed(error.message)),
                    };
                    if let Err(error) = validate_media_export_structure(&result, &active.output_chunks, output_bytes, active.contract.max_output_bytes) {
                        return self.finish_media_poll(handle.operation_id.0, active, ArtifactMediaExportPoll::Failed(error.message));
                    }
                    active.lease.finish_in_place();
                    active.retained_outcome = Some(semio_framework_job::StepOutcome::Complete(candidate));
                    if self.current_media_export == Some(handle.operation_id.0) {
                        self.current_media_export = None;
                    }
                    self.finish_media_poll(handle.operation_id.0, active, ArtifactMediaExportPoll::Complete(result))
                }
                semio_framework_job::StepOutcome::Cancelled => self.finish_media_poll(handle.operation_id.0, active, ArtifactMediaExportPoll::Cancelled),
                semio_framework_job::StepOutcome::Fault(fault) => {
                    active.retained_outcome = Some(semio_framework_job::StepOutcome::Fault(fault));
                    self.finish_media_poll(handle.operation_id.0, active, ArtifactMediaExportPoll::Failed("media export job faulted".into()))
                }
            }
        }

        async fn cancel_owned_media_export(&mut self, handle: &ArtifactMediaExportHandle) -> Result<(), MediaError> {
            let operation_id = handle.operation_id.0;
            if let Some(output) = self.segmented_downloads.get(operation_id) {
                if !output.owns_media_export(handle) {
                    return Err(MediaError::Payload(handle.parent_document_id.clone(), "media export download handle authority mismatch".into()));
                }
                if !self.segmented_closures.can_insert(operation_id) {
                    return Err(MediaError::Payload(handle.parent_document_id.clone(), "media export download cleanup authority is saturated".into()));
                }
                let output = self.segmented_downloads.remove(operation_id).ok_or_else(|| MediaError::Payload(handle.parent_document_id.clone(), "media export download changed before cancellation".into()))?;
                self.segmented_closures.insert_admitted(operation_id, output);
                return Ok(());
            }
            if !self.media_closures.can_insert(operation_id) {
                return Err(MediaError::Payload(handle.parent_document_id.clone(), "media close authority is saturated or already owns this operation".into()));
            }
            let Some(active) = self.media_exports.get(operation_id) else {
                return Err(MediaError::Payload(handle.parent_document_id.clone(), "unknown or completed media export handle".into()));
            };
            if active.handle != *handle {
                return Err(MediaError::Payload(handle.parent_document_id.clone(), "media export handle authority mismatch".into()));
            }
            self.quarantine_media_snapshot(operation_id, active)?;
            let active = self.media_exports.remove(operation_id).expect("checked exact media export owner");
            self.media_closures.insert_admitted(operation_id, active);
            if self.current_media_export == Some(operation_id) {
                self.current_media_export = None;
            }
            Ok(())
        }

        /// 🧮️ One reserved gesture's work, in the STAGED EDIT ROWS every other capacity in the
        /// runtime is counted in — never the bare item count the route used to hand its job, which
        /// no longer matched the two-row footprint its own config preflight declares.
        async fn framework_reserved_work_items(&mut self, action: &str, args: Option<&DslValue>) -> Result<usize, Fault> {
            let items = self.framework_reserved_route_items(action, args).await?;
            FRAMEWORK_RESERVED_ROUTE_CAPACITY.rows_for_items(items).ok_or_else(|| plugin_sdk_fault(format!("framework reserved route '{action}' declares {items} items beyond its exact work capacity")))
        }

        async fn framework_reserved_route_items(&mut self, action: &str, args: Option<&DslValue>) -> Result<usize, Fault> {
            match action {
                "commitCheckpoint" | "checkoutCheckpoint" => Ok(self.children.len().saturating_add(1)),
                REVERT_TO_COMMAND_ACTION_ID => {
                    self.refresh_cache().await?;
                    let entry_seq = args.and_then(|value| value.get("entrySeq")).and_then(DslValue::as_f64).map(|seq| seq as u64);
                    let target =
                        entry_seq.and_then(|seq| self.cache.as_ref().and_then(|(_, _, _, history)| history.commands.iter().find(|entry| entry.seq == seq && entry.revertible)).map(|entry| (entry.edit_id.clone(), entry.config_edit_id.clone())));
                    match target {
                        Some((Some(edit_id), _)) => {
                            let applied = self.store.applied_edit_ids();
                            Ok(applied.iter().position(|id| *id == edit_id).map_or(1, |position| applied.len().saturating_sub(position + 1).max(1)))
                        }
                        Some((None, Some(config_edit_id))) => {
                            let applied = self.config_store.applied_edit_ids();
                            Ok(applied.iter().position(|id| *id == config_edit_id).map_or(1, |position| applied.len().saturating_sub(position + 1).max(1)))
                        }
                        _ => Ok(1),
                    }
                }
                "copy" | "cut" => {
                    let interaction = self.interaction_selection_snapshot();
                    Ok(interaction.selection.values().map(|selection| selection.ids.len()).sum::<usize>().max(1))
                }
                "paste" => {
                    let fragment_bytes = args
                        .and_then(|value| value.get("fragment"))
                        .and_then(|value| <ClipboardFragment as protocol::FromValue>::from_value(value.clone()).ok())
                        .map(|fragment| fragment.pack_bytes.map_or(fragment.dsl_text.len(), |bytes| bytes.len()))
                        .unwrap_or_default();
                    Ok(fragment_bytes.div_ceil(4_096).max(1))
                }
                _ => Ok(1),
            }
        }

        /// 🖱️ Vortex pointermove is a storm of `interactionHover` (then a click `interactionSelect`)
        /// before the host finishes any Isolated reserved job. Exclusive `job % 64` slots made that
        /// storm `interactive-job.reserved-spawn-capacity`. Latest-wins: retire the same verb, and
        /// any other interaction occupying this hash slot, so hover preview and place can commit.
        fn retire_pending_reserved_latest_wins(&mut self, action: &str, job: u64) {
            if !INTERACTION_ACTION_IDS.contains(&action) {
                return;
            }
            let slot = job as usize % ARTIFACT_LIVE_OUTPUT_SLOTS;
            let mut ids = Vec::new();
            self.pending_reserved.each_id(|id| ids.push(id));
            let retire: Vec<u64> =
                ids.into_iter().filter(|&id| self.pending_reserved.get(id).is_some_and(|pending| pending.action == action || (id as usize % ARTIFACT_LIVE_OUTPUT_SLOTS == slot && INTERACTION_ACTION_IDS.contains(&pending.action.as_str())))).collect();
            for id in retire {
                if let Some(pending) = self.pending_reserved.remove(id) {
                    pending.permit.finish();
                }
            }
        }

        /// 🎰️ `pending_reserved` is DIRECT-MAPPED on `job % ARTIFACT_LIVE_OUTPUT_SLOTS`, and this caller
        /// MINTS the id — so a residue class already held by an unrelated reserved verb (a
        /// `noteShellCommand` the shell records for every user command, an in-flight `undo`) must be
        /// answered by minting into a vacant class, never by faulting the whole route. It used to fault:
        /// a canvas pick landed as `interactive-job.reserved-spawn-capacity` with 63 slots standing empty
        /// (ticket 26/09/02/PUZZLE-3D-END-TO-END battery #44-pre: `framework route 'interactionSelect'
        /// has no exact pending spawn slot`). `retire_pending_reserved_latest_wins` still runs first, so
        /// an interaction storm keeps its latest-wins retirement rather than filling the table.
        async fn dispatch_framework_reserved_action(&mut self, action: &str, args: Option<&DslValue>, meta: &ActionMeta) -> Result<InvocationResult, Fault> {
            if self.time_travel.freezes_local_emits() && time_travel_freezes_reserved_action(action) {
                return Err(time_travel_frozen_fault(action));
            }
            let contract = self.qualified_tool_proof(action)?.contract();
            let decoded_items = bounded_json_items(args, contract.max_decoded_items)?;
            let wire_args = args.cloned();
            let raw = protocol::json::to_json_string(&(action, wire_args)).into_bytes();
            let work_items = self.framework_reserved_work_items(action, args).await?;
            if CLIPBOARD_ACTION_IDS.contains(&action) {
                let mut app_completion = None;
                let job = match self.build_artifact_reserved_action_job(action, args, raw.clone(), meta).await? {
                    Some((job, completion)) => {
                        app_completion = Some(completion);
                        job
                    }
                    None => framework_reserved_route_job(action, raw.clone(), work_items)?,
                };
                let permit = self.run_framework_reserved_job(action, &raw, decoded_items, job, meta, None).await?;
                self.validate_framework_reserved_commit(action, &permit).await?;
                let result = self.commit_framework_clipboard_completion(action, app_completion, meta, &permit).await;
                permit.finish();
                return result;
            }
            initialize_framework_reserved_jobs();
            let mut permit = self.admit_framework_reserved_spawn(action, &raw, decoded_items, meta).await?;
            let mut job = permit.operation.operation.0;
            self.retire_pending_reserved_latest_wins(action, job);
            for _ in 0..ARTIFACT_LIVE_OUTPUT_SLOTS {
                if self.pending_reserved.can_insert(job) {
                    break;
                }
                permit.finish();
                permit = self.admit_framework_reserved_spawn(action, &raw, decoded_items, meta).await?;
                job = permit.operation.operation.0;
                self.retire_pending_reserved_latest_wins(action, job);
            }
            if !self.pending_reserved.can_insert(job) {
                permit.finish();
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.reserved-spawn-capacity"), format!("framework route '{action}' found no vacant pending spawn slot in {ARTIFACT_LIVE_OUTPUT_SLOTS} residue classes")));
            }
            self.pending_reserved.insert_admitted(job, PendingFrameworkReserved { action: action.to_string(), args: args.cloned(), meta: meta.clone(), permit });
            let mut admitted = Self::empty_result(
                action,
                meta,
                vec![Effect::SpawnJob { job, kind: FRAMEWORK_RESERVED_JOB_KIND.into(), input: encode_framework_reserved_job_input(work_items as u64, &raw), placement: semio_framework::kernel::JobPlacement::Isolated }],
                Vec::new(),
                UiDirtyScope::None,
            )
            .await;
            admitted.output = DslValue::Object(vec![("operationId".into(), DslValue::String(job.to_string())), ("generation".into(), DslValue::String(self.store.generation().to_string()))]);
            Ok(admitted)
        }

        async fn admit_framework_reserved_spawn(&mut self, verb: &str, raw: &[u8], decoded_items: usize, meta: &ActionMeta) -> Result<FrameworkReservedCommitPermit, Fault> {
            let proof = self.qualified_tool_proof(verb)?;
            if !matches!(proof, QualifiedToolProof::FrameworkOwned(_) | QualifiedToolProof::AppOwned(_)) {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.reserved-proof"), format!("framework route '{verb}' did not resolve its route-specific factory")));
            }
            let key = proof.key();
            let admission = self.tool_jobs.admit_exact_wire(key.controller_id.clone(), key.tool_id.clone(), proof.schema_id(), raw).map_err(|error| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.dispatch"), error.to_string()))?;
            if decoded_items > proof.contract().max_decoded_items || !proof.admits::<A>(&admission) {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.reserved-admission"), format!("framework route '{verb}' failed its exact owner/factory/schema/contract admission")));
            }
            let canonical_base_revision = self.store.content_revision();
            let base_revision = semio_framework_job::RevisionId(u64::from_be_bytes(canonical_base_revision[..8].try_into().expect("revision lane width")));
            let generation = semio_framework_job::Generation(self.store.generation());
            let seed_handle = artifact_handle_of(&format!("{}/{}/{verb}/{}", meta.instance_id, self.tool_job_controller_id, base_revision.0)).await;
            let operation = semio_framework_job::Operation::new(semio_framework_job::allocate_operation_id(), base_revision, generation, (seed_handle.0 as u64) ^ ((seed_handle.0 >> 64) as u64));
            let operation_id = operation.operation;
            let operation_key = ToolOperationKey { app_instance_id: meta.instance_id, document: ArtifactDocumentAuthority(meta.instance_id), operation_id, base_revision, generation };
            let lease = self.tool_cancellations.begin(operation_key)?;
            Ok(FrameworkReservedCommitPermit { operation, lease })
        }

        /// 🕰️ Hands one finished framework-reserved spawn-job to the app's commit queue. Nothing here
        /// suspends: the commit itself runs unit by unit in [`Self::step_framework_reserved_commit`].
        /// Answers `false` for a job this app never admitted.
        fn admit_framework_reserved_commit(&mut self, job: u64, output: Result<Vec<u8>, Fault>) -> Result<bool, Fault> {
            let Some(pending) = self.pending_reserved.remove(job) else {
                return Ok(false);
            };
            if let Err(fault) = output {
                pending.permit.finish();
                return Err(fault);
            }
            if self.reserved_commits.len() >= ARTIFACT_LIVE_OUTPUT_SLOTS {
                pending.permit.finish();
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.reserved-commit-capacity"), format!("framework route '{}' found the reserved commit queue full", pending.action)));
            }
            let PendingFrameworkReserved { action, args, meta, permit } = pending;
            self.reserved_commits.push_back(FrameworkReservedCommit { action, args, meta, permit, log_generation_before: self.log_generation, stage: FrameworkReservedCommitStage::Validate, applied: 0, total: 1 });
            Ok(true)
        }

        /// 📊️ Progress of the commit at the head of the reserved-commit queue.
        pub fn framework_reserved_commit_progress(&self) -> Option<FrameworkReservedCommitProgress> {
            self.reserved_commits.front().map(|commit| FrameworkReservedCommitProgress { operation: commit.permit.operation.operation.0, applied: commit.applied, total: commit.total })
        }

        /// 🪜️ Runs ONE bounded unit of the commit at the head of the queue. Commits are strictly FIFO,
        /// and the head waits while a finished outcome is still untaken, so at most one outcome is ever
        /// owed to the host. A finished commit leaves its result in `reserved_commit_outcome`.
        async fn step_framework_reserved_commit(&mut self) -> Result<(), Fault> {
            if self.reserved_commit_outcome.is_some() {
                return Ok(());
            }
            let Some(mut commit) = self.reserved_commits.pop_front() else {
                return Ok(());
            };
            match self.run_framework_reserved_commit_unit(&mut commit).await {
                Ok(Some(result)) => {
                    let result = self.finish_recorded(commit.log_generation_before, &commit.action, result).await;
                    let _ = self.typed_completion_outbox.push(TypedOperationCompletionWitness { operation: commit.permit.operation.operation.0, ui_scope: result.ui_scope.clone() });
                    commit.permit.finish();
                    self.reserved_commit_outcome = Some(Ok(result));
                }
                Ok(None) => {
                    commit.applied = commit.applied.saturating_add(1);
                    self.reserved_commits.push_front(commit);
                }
                Err(fault) => {
                    commit.permit.finish();
                    self.reserved_commit_outcome = Some(Err(fault));
                }
            }
            Ok(())
        }

        /// 🧾️ Takes the result of the last finished reserved commit.
        fn take_framework_reserved_commit_outcome(&mut self) -> Option<Result<InvocationResult, Fault>> {
            self.reserved_commit_outcome.take()
        }

        async fn run_framework_reserved_commit_unit(&mut self, commit: &mut FrameworkReservedCommit) -> Result<Option<InvocationResult>, Fault> {
            if commit.permit.is_cancelled().await {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.cancelled"), format!("framework route '{}' was cancelled between commit units", commit.action)));
            }
            if matches!(commit.stage, FrameworkReservedCommitStage::Validate) {
                self.validate_framework_reserved_commit(&commit.action, &commit.permit).await?;
                commit.stage = match Self::history_command(&commit.action, commit.args.as_ref()).await {
                    Some(ArtifactCommand::CommitCheckpoint { message, authors }) if !self.children.is_empty() => {
                        let keys: Vec<(String, String)> = self.children.entries().map(|entry| (entry.owner.slot.clone(), entry.reference.artifact_id.clone())).collect();
                        self.admit_child_content_publication_span(keys.len())?;
                        commit.total = keys.len() as u64 + 1;
                        FrameworkReservedCommitStage::CheckpointChildren { message: message.unwrap_or_else(|| "checkpoint".to_string()), authors, keys, next: 0, pins: Vec::new() }
                    }
                    _ => {
                        commit.total = 1;
                        FrameworkReservedCommitStage::Route { pins: Vec::new() }
                    }
                };
            }
            match std::mem::replace(&mut commit.stage, FrameworkReservedCommitStage::Validate) {
                FrameworkReservedCommitStage::Validate => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.reserved-commit-stage"), format!("framework route '{}' re-entered its validation unit", commit.action))),
                FrameworkReservedCommitStage::CheckpointChildren { message, authors, keys, next, mut pins } => {
                    if let Some((slot, child_id)) = keys.get(next) {
                        if let Some(pin) = self.checkpoint_child_unit(&message, &authors, slot, child_id).await? {
                            pins.push(pin);
                        }
                    }
                    commit.stage = if next + 1 < keys.len() {
                        FrameworkReservedCommitStage::CheckpointChildren { message, authors, keys, next: next + 1, pins }
                    } else {
                        pins.sort_by(|left, right| left.child_ref.artifact_id.cmp(&right.child_ref.artifact_id));
                        FrameworkReservedCommitStage::Route { pins }
                    };
                    Ok(None)
                }
                FrameworkReservedCommitStage::Route { pins } => {
                    let action = commit.action.clone();
                    if HISTORY_ACTION_IDS.contains(&action.as_str()) {
                        let result = self.commit_framework_history_route(&action, commit.args.as_ref(), &commit.meta, &commit.permit, pins).await?;
                        if action == "checkoutCheckpoint" && result.ui_scope != UiDirtyScope::None {
                            let pins = self.checkout_cascade_pins()?;
                            if !pins.is_empty() {
                                commit.total = commit.total.saturating_add(pins.len() as u64);
                                commit.stage = FrameworkReservedCommitStage::CheckoutChildren { pins, next: 0, result };
                                return Ok(None);
                            }
                        }
                        Ok(Some(result))
                    } else if action == REVERT_TO_COMMAND_ACTION_ID {
                        match self.begin_framework_revert_route(commit.args.as_ref(), &commit.meta).await? {
                            Ok(result) => Ok(Some(result)),
                            Err((lane, edit_id)) => {
                                commit.stage = FrameworkReservedCommitStage::Revert { lane, edit_id };
                                Ok(None)
                            }
                        }
                    } else {
                        self.commit_framework_shared_host_route(&action, commit.args.as_ref(), &commit.meta, &commit.permit).await.map(Some)
                    }
                }
                FrameworkReservedCommitStage::CheckoutChildren { pins, next, result } => {
                    let Some(pin) = pins.get(next) else { return Ok(Some(result)) };
                    self.checkout_child_unit(pin).await?;
                    commit.stage = FrameworkReservedCommitStage::CheckoutChildren { pins, next: next + 1, result };
                    Ok(None)
                }
                FrameworkReservedCommitStage::Revert { lane, edit_id } => {
                    if self.framework_revert_unit(lane, &edit_id).await? {
                        commit.total = commit.total.saturating_add(1);
                        commit.stage = FrameworkReservedCommitStage::Revert { lane, edit_id };
                        return Ok(None);
                    }
                    self.cache = None;
                    self.record_command(REVERT_TO_COMMAND_ACTION_ID, ActionKind::History, None, None, None, None);
                    Ok(Some(Self::empty_result(REVERT_TO_COMMAND_ACTION_ID, &commit.meta, Vec::new(), vec![history_changed_event().await], UiDirtyScope::Full).await))
                }
            }
        }

        /// 🧩️ A pending CHILD redo outranks a chrome replay for the same reason a parent one
        /// does: the document stack is reapplied before the shell rows stacked above it.
        ///
        /// 🧩️ A `Child`-lane row is a real undo target too, so chrome undo never jumps OVER
        /// the user's own composed-document edit to replay a panel toggle behind it.
        async fn dispatch_chrome_history_action(&mut self, action: &str, meta: &ActionMeta) -> Result<Option<InvocationResult>, Fault> {
            if action == "redo" {
                if !self.store.redo_edit_ids().is_empty() || self.child_history_tails().await.1 {
                    return Ok(None);
                }
                let Some(replay) = self.shell_redo.pop() else {
                    return Ok(None);
                };
                crate::plugin_runtime::debug_runtime_line(format_args!("[TRACE] chrome history action=redo seq={}", replay.seq));
                self.shell_undone.remove(&replay.seq);
                self.history_dirty_sequences.insert(replay.seq);
                self.record_command(action, ActionKind::History, None, None, None, None);
                return Ok(Some(Self::empty_result(action, meta, vec![Effect::ReplayShellCommand { action_id: replay.redo.action_id, args: replay.redo.args }], vec![history_changed_event().await], UiDirtyScope::Full).await));
            }
            if action != "undo" {
                return Ok(None);
            }
            let (child_applied_tails, _) = self.child_history_tails().await;
            let applied: HashSet<&str> = self.store.applied_edit_ids().iter().map(String::as_str).collect();
            let config_applied: HashSet<&str> = self.config_store.applied_edit_ids().iter().map(String::as_str).collect();
            let target = self.command_log.iter().rev().find(|entry| {
                let shell = entry.inverse.is_some() && entry.edit_id.is_none() && entry.config_edit_ids.is_empty() && !self.shell_undone.contains(&entry.seq);
                let document = entry.edit_id.as_deref().is_some_and(|id| applied.contains(id));
                let config = entry.config_edit_ids.iter().any(|id| config_applied.contains(id.as_str()));
                let child = entry.child_edit_ids.iter().any(|id| child_applied_tails.contains(id));
                shell || document || config || child
            });
            let Some(entry) = target else {
                return Ok(None);
            };
            if entry.edit_id.is_some() || !entry.config_edit_ids.is_empty() || entry.inverse.is_none() {
                return Ok(None);
            }
            let seq = entry.seq;
            let inverse = entry.inverse.clone().expect("chrome undo target has inverse");
            let redo = InverseAction { action_id: entry.action_id.clone(), args: None };
            crate::plugin_runtime::debug_runtime_line(format_args!("[TRACE] chrome history action=undo seq={seq} inverse={}", inverse.action_id));
            self.shell_undone.insert(seq);
            self.shell_redo.push(ShellHistoryReplay { seq, redo });
            self.history_dirty_sequences.insert(seq);
            self.record_command(action, ActionKind::History, None, None, None, None);
            Ok(Some(Self::empty_result(action, meta, vec![Effect::ReplayShellCommand { action_id: inverse.action_id, args: inverse.args }], vec![history_changed_event().await], UiDirtyScope::Full).await))
        }

        async fn commit_framework_history_route(&mut self, action: &str, args: Option<&DslValue>, meta: &ActionMeta, permit: &FrameworkReservedCommitPermit, pins: Vec<vcs::CompositionPin>) -> Result<InvocationResult, Fault> {
            crate::plugin_runtime::debug_runtime_line(format_args!("[TRACE] history route action={action}"));
            if permit.lease.is_cancelled().await {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.cancelled"), format!("framework route '{action}' was cancelled at commit")));
            }
            if action == "undo" || action == "redo" {
                if let Some(result) = self.dispatch_supersede_history_action(action, meta).await? {
                    return Ok(result);
                }
                if let Some(result) = self.dispatch_chrome_history_action(action, meta).await? {
                    return Ok(result);
                }
                let parent_group_id = if action == "undo" { self.store.tail_group_id().await } else { self.store.redo_tail().await.and_then(|(_, group_id)| group_id) };
                let group_id = match parent_group_id {
                    Some(group_id) => Some(group_id),
                    None => self.child_group_history_target(action).await,
                };
                if let Some(group_id) = group_id {
                    let grouped = self.dispatch_group_history_action(action, &group_id, meta).await?;
                    if grouped.ui_scope != UiDirtyScope::None {
                        return Ok(grouped);
                    }
                }
            }
            let command = Self::history_command(action, args).await.ok_or_else(|| format!("history action {action} missing required argument"))?;
            match self.store.dispatch(command).await {
                Ok(_) => {
                    self.stamp_checkpoint_composition_pins(pins).await?;
                    self.cache = None;
                    self.record_command(action, ActionKind::History, None, None, None, None);
                    Ok(Self::empty_result(action, meta, Vec::new(), vec![history_changed_event().await], UiDirtyScope::Full).await)
                }
                Err(vcs::VcsError::NothingToUndo) | Err(vcs::VcsError::NothingToRedo) | Err(vcs::VcsError::ForeignEdit(_)) => Ok(Self::empty_result(action, meta, Vec::new(), Vec::new(), UiDirtyScope::None).await),
                Err(vcs::VcsError::ValidationFailed(ref message)) if message.as_str() == vcs::EMPTY_CHECKPOINT_MESSAGE => Ok(Self::empty_result(action, meta, Vec::new(), Vec::new(), UiDirtyScope::None).await),
                Err(error) => Err(error.into_fault()),
            }
        }

        /// ⏪️ Resolves a `revertToCommand` target. A document or configuration edit answers the lane and
        /// edit id [`Self::framework_revert_unit`] walks back one undo per commit unit; every other target
        /// answers its complete result.
        async fn begin_framework_revert_route(&mut self, args: Option<&DslValue>, meta: &ActionMeta) -> Result<Result<InvocationResult, (FrameworkRevertLane, String)>, Fault> {
            let action = REVERT_TO_COMMAND_ACTION_ID;
            self.refresh_cache().await?;
            let entry_seq = args.and_then(|value| value.get("entrySeq")).and_then(DslValue::as_f64).map(|seq| seq as u64);
            let transition_id = entry_seq.and_then(|seq| self.command_log.iter().find(|entry| entry.seq == seq)).and_then(|entry| entry.transition_id.clone());
            if let Some(transition_id) = transition_id {
                return Ok(Ok(self.revert_history_edit_row(&transition_id, meta).await?));
            }
            let target = entry_seq.and_then(|seq| {
                self.cache.as_ref().and_then(|(_, _, _, history)| history.commands.iter().find(|entry| entry.seq == seq && entry.revertible)).map(|entry| (entry.edit_id.clone(), entry.config_edit_id.clone(), entry.kind, entry.inverse.clone()))
            });
            let (lane, edit_id) = match target {
                Some((Some(edit_id), _, _, _)) => (FrameworkRevertLane::Document, edit_id),
                Some((None, Some(config_edit_id), _, _)) => (FrameworkRevertLane::Configuration, config_edit_id),
                Some((None, None, ActionKind::Shell, Some(inverse))) => return Ok(Ok(Self::empty_result(action, meta, vec![Effect::ReplayShellCommand { action_id: inverse.action_id, args: inverse.args }], Vec::new(), UiDirtyScope::None).await)),
                _ => return Ok(Ok(Self::empty_result(action, meta, Vec::new(), Vec::new(), UiDirtyScope::None).await)),
            };
            let applied = match lane {
                FrameworkRevertLane::Document => self.store.applied_edit_ids(),
                FrameworkRevertLane::Configuration => self.config_store.applied_edit_ids(),
            };
            if !applied.iter().any(|id| *id == edit_id) {
                return Ok(Ok(Self::empty_result(action, meta, Vec::new(), Vec::new(), UiDirtyScope::None).await));
            }
            Ok(Err((lane, edit_id)))
        }

        /// ⏪️ One revert unit: undoes the newest edit of `lane` while `edit_id` is not yet its tail.
        /// Answers whether an undo was applied (`false` once the target is the tail or the lane refuses).
        async fn framework_revert_unit(&mut self, lane: FrameworkRevertLane, edit_id: &str) -> Result<bool, Fault> {
            let pending = match lane {
                FrameworkRevertLane::Document => {
                    let applied = self.store.applied_edit_ids();
                    applied.iter().any(|id| id.as_str() == edit_id) && applied.last().is_some_and(|tail| tail.as_str() != edit_id)
                }
                FrameworkRevertLane::Configuration => {
                    let applied = self.config_store.applied_edit_ids();
                    applied.iter().any(|id| id.as_str() == edit_id) && applied.last().is_some_and(|tail| tail.as_str() != edit_id)
                }
            };
            if !pending {
                return Ok(false);
            }
            let undone = match lane {
                FrameworkRevertLane::Document => self.store.dispatch(ArtifactCommand::Undo).await.map(|_| ()),
                FrameworkRevertLane::Configuration => self.config_store.dispatch(ArtifactCommand::Undo).await.map(|_| ()),
            };
            match undone {
                Ok(()) => Ok(true),
                Err(vcs::VcsError::NothingToUndo) | Err(vcs::VcsError::ForeignEdit(_)) => Ok(false),
                Err(error) => Err(error.into_fault()),
            }
        }

        async fn ensure_reserved_emit_bounded(action: &str, emit: &Emit<A::Mutation, A::ConfigMutation, A::DraftMutation>, contract: semio_framework::ToolExecutionContract) -> Result<(), Fault> {
            let item_count = emit.artifact_mutations.len().saturating_add(emit.config_mutations.len()).saturating_add(emit.draft_mutations.len()).saturating_add(emit.effects.len()).saturating_add(emit.extension_invocations.len());
            if item_count > contract.max_decoded_items {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.clipboard-items"), format!("clipboard route '{action}' emitted too many operations")));
            }
            let mut bytes = 0usize;
            for chunk in emit.artifact_mutations.chunks(32) {
                for operation in chunk {
                    bytes = bytes.saturating_add(::protocol::OpBinary::encode_op(operation).map_err(|error| error.into_fault())?.len());
                }
                if bytes > contract.max_output_bytes {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.clipboard-output"), format!("clipboard route '{action}' exceeded its output cap")));
                }
                semio_framework_async::yield_once().await;
            }
            for chunk in emit.config_mutations.chunks(32) {
                for operation in chunk {
                    bytes = bytes.saturating_add(::protocol::OpBinary::encode_op(operation).map_err(|error| error.into_fault())?.len());
                }
                if bytes > contract.max_output_bytes {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.clipboard-output"), format!("clipboard route '{action}' exceeded its output cap")));
                }
                semio_framework_async::yield_once().await;
            }
            for chunk in emit.draft_mutations.chunks(32) {
                for operation in chunk {
                    bytes = bytes.saturating_add(::protocol::OpBinary::encode_op(operation).map_err(|error| error.into_fault())?.len());
                }
                if bytes > contract.max_output_bytes {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.clipboard-output"), format!("clipboard route '{action}' exceeded its output cap")));
                }
                semio_framework_async::yield_once().await;
            }
            for chunk in emit.effects.chunks(32) {
                for effect in chunk {
                    bytes = bytes.saturating_add(protocol::json::to_json_string(effect).len());
                }
                if bytes > contract.max_output_bytes {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.clipboard-output"), format!("clipboard route '{action}' exceeded its output cap")));
                }
                semio_framework_async::yield_once().await;
            }
            Ok(())
        }

        async fn commit_framework_clipboard_completion(&mut self, action: &str, completion: Option<ArtifactToolCompletion<A>>, meta: &ActionMeta, permit: &FrameworkReservedCommitPermit) -> Result<InvocationResult, Fault> {
            if permit.is_cancelled().await {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.cancelled"), format!("clipboard route '{action}' was cancelled before output commit")));
            }
            let Some(completion) = completion else {
                return Ok(Self::empty_result(action, meta, Vec::new(), Vec::new(), UiDirtyScope::None).await);
            };
            let (emit, ephemeral) = completion.take_emit()?.ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.missing-output"), format!("clipboard route '{action}' completed without producer output")))?;
            let emit = emit?;
            Self::ensure_reserved_emit_bounded(action, &emit, self.qualified_tool_proof(action)?.contract()).await?;
            self.presence_store.apply(&ephemeral.presence).await.map_err(|error| Fault::from(error.to_string()))?;
            self.transient_store.apply(&ephemeral.transient).await.map_err(|error| Fault::from(error.to_string()))?;
            self.dispatch_emit(action, emit, meta).await
        }

        async fn commit_framework_shared_host_route(&mut self, action: &str, args: Option<&DslValue>, meta: &ActionMeta, permit: &FrameworkReservedCommitPermit) -> Result<InvocationResult, Fault> {
            self.validate_framework_reserved_commit(action, permit).await?;
            if INTERACTION_ACTION_IDS.contains(&action) {
                return self.dispatch_interaction_action(action, args, meta, permit).await;
            }
            if action == SET_HISTORY_COMMAND_FILTER_ACTION_ID {
                let filter = args.and_then(|value| value.get("value")).and_then(DslValue::as_str).unwrap_or("all");
                self.history_filter = match filter {
                    "withoutMutations" => HistoryCommandFilter::WithoutMutations,
                    "onlyMutations" => HistoryCommandFilter::OnlyMutations,
                    _ => HistoryCommandFilter::All,
                };
                self.log_generation += 1;
                self.history_dirty_sequences.extend(self.command_log.iter().map(|entry| entry.seq));
                return Ok(Self::empty_result(
                    action,
                    meta,
                    Vec::new(),
                    Vec::new(),
                    UiDirtyScope::Partial { window_bodies: Vec::new(), panel_bodies: vec![FRAMEWORK_HISTORY_BODY_KEY.to_string()], utilities: false, tools: false, engagements: false, measures: false, labels: false },
                )
                .await);
            }
            if action == NOTE_SHELL_COMMAND_ACTION_ID {
                let command_id = args.and_then(|value| value.get("commandId")).and_then(DslValue::as_str).ok_or_else(|| "noteShellCommand missing required commandId".to_string())?;
                let detail = args.and_then(|value| value.get("detail")).cloned();
                let label = note_shell_command_label(args.and_then(|value| value.get("label")), command_id, detail.as_ref());
                let inverse = args
                    .and_then(|value| value.get("inverseCommandId"))
                    .and_then(DslValue::as_str)
                    .map(|inverse_command_id| InverseAction { action_id: inverse_command_id.to_string(), args: args.and_then(|value| value.get("inverseArgs")).cloned().or(detail) });
                self.validate_framework_reserved_commit(action, permit).await?;
                self.record_command(command_id, ActionKind::Shell, Some(label), None, None, inverse);
                return Ok(Self::empty_result(action, meta, Vec::new(), Vec::new(), UiDirtyScope::None).await);
            }
            if action == RECORD_TUTORIAL_ACTION_ID {
                return Ok(Self::empty_result(action, meta, Vec::new(), Vec::new(), UiDirtyScope::None).await);
            }
            Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.unknown-shared-host-route"), format!("unknown shared host route '{action}'")))
        }

        /// 🕰️ The actual body of `PluginApp::handle_action` — renamed to an inherent method so
        /// `handle_action` itself can stay a thin `finish_recorded` wrapper (see `🔖️CommandLog`). B1:
        /// FRAMEWORK-reserved verbs only (history/revert/filter/noteShellCommand/clipboard/interaction) —
        /// an app's own behavior is dispatched exclusively through `dispatch_typed_command` now.
        async fn dispatch_catalogue_example(&mut self, action: &str, body: &str, meta: &ActionMeta) -> Result<InvocationResult, Fault> {
            let snapshot = catalogue_snapshot_from_document::<A::Snapshot>(body)?;
            let pack = snapshot.encode_pack();
            let spr = store::empty_document_spr("", A::DOCUMENT_SCHEMA).await;
            self.dispatch_emit(
                action,
                Emit {
                    effects: vec![Effect::LoadDocument { pack, spr }],
                    ui_scope: UiDirtyScope::Full,
                    ..Emit::default()
                },
                meta,
            )
            .await
        }

        pub(crate) async fn dispatch_action(&mut self, action: &str, args: Option<&DslValue>, meta: &ActionMeta) -> Result<InvocationResult, Fault> {
            if A::ROLE == AppRole::Viewer && viewer_rejects_action(action) {
                return Err(viewer_read_only_fault(action));
            }
            if action==CANCEL_TYPED_OPERATION_ACTION_ID {return self.dispatch_operation_cancellation(args,meta).await;}
            Box::pin(self.deliver_utility_host_events(meta)).await?;
            if action == semio_framework::HOST_EVENT_ACTION_ID {
                return Box::pin(self.dispatch_host_event_action(args, meta)).await;
            }
            Box::pin(self.commit_typing_before(action, args, meta)).await?;
            if matches!(action, semio_framework::EXPORT_ARTIFACT_DOCUMENT_ACTION_ID | semio_framework::IMPORT_ARTIFACT_DOCUMENT_ACTION_ID) {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("framework.document-transfer.shell-owned"), format!("{action} is performed by the shell, never by the program")));
            }
            if is_tool_run_action_id(action) {
                return self.dispatch_tool_run_action(action, args, meta).await;
            }
            if is_time_travel_action_id(action) {
                self.freeze_tool_machines();
                return Box::pin(self.dispatch_time_travel_action(action, args, meta)).await;
            }
            if is_framework_reserved_action_id(action) {
                return self.dispatch_framework_reserved_action(action, args, meta).await;
            }
            if action == CATALOGUE_EXAMPLE_ACTION_ID && self.registry.get(action).is_none() {
                let example_id = args.and_then(|value| value.get("exampleId")).and_then(DslValue::as_str).unwrap_or("");
                if let Some(document) = A::catalogue_example_document(example_id) {
                    let body = document?;
                    return self.dispatch_catalogue_example(action, &body, meta).await;
                }
            }
            let definition = self.registry.get(action).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.unknown-key"), format!("UI dispatch rejected unknown action key '{action}' before command construction")))?;
            validate_ui_dispatch_classification("action", action, definition.semantics.execution.interactive_job)?;
            let definition_kind = definition.kind;
            let tool = match Box::pin(self.admit_tool_dispatch(action, args, meta)).await {
                ToolDispatch::Plain => None,
                ToolDispatch::Tagged(tag) => Some(tag),
                ToolDispatch::Settled(result) => return result,
            };
            let whole_import = match self.import_staging.admit_args(args).map_err(|refusal| Fault::new(FaultOrigin::Framework, FaultCode::new(refusal.code()), refusal.message()))? {
                semio_framework::kernel::ImportArguments::Staged { .. } => return Ok(Self::empty_result(action, meta, Vec::new(), Vec::new(), UiDirtyScope::None).await),
                semio_framework::kernel::ImportArguments::Whole(whole) => Some(whole),
                semio_framework::kernel::ImportArguments::NotAnImport => None,
            };
            let args = whole_import.as_ref().or(args);
            if let Some(config_mutation) = A::host_configuration_mutation(action, args)? {
                let admission = self.admit_host_configuration_json(action, args).await?;
                self.require_tool_operation_authority(&admission)?;
                let encoded = ::protocol::OpBinary::encode_op(&config_mutation).map_err(|error| error.into_fault())?;
                if encoded.len() > admission.proof.contract().max_output_bytes {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.host-configuration-output"), format!("host configuration action '{action}' exceeds its exact output cap")));
                }
                let mut emit = Emit::config(vec![config_mutation]);
                if let Some(ToolTag::Scrub(tag)) = &tool {
                    if !self.settle_press_config(tag, &mut emit) {
                        self.follow_tool_machines(true);
                        return Ok(Self::empty_result(action, meta, Vec::new(), Vec::new(), UiDirtyScope::Full).await);
                    }
                }
                let previous_kind = self.invocation_kind.replace(definition_kind);
                let result = self.dispatch_emit(action, emit, meta).await;
                self.invocation_kind = previous_kind;
                result
            } else if matches!(action, SET_ACTIVE_TOOL_ACTION_ID | SET_ACTIVE_UTILITY_ACTION_ID) {
                let previous_kind = self.invocation_kind.replace(definition_kind);
                let result = self.dispatch_emit(action, Emit::default(), meta).await;
                self.invocation_kind = previous_kind;
                result
            } else {
                let command = Box::new(A::command_from_action(action, args).await?);
                let wire = <A::Command as ::protocol::OpBinary>::encode_op(&command).map_err(|error| error.into_fault())?;
                let admission = self.admit_command_wire(action, &wire, 1).await?;
                self.require_complete_tool_operation_pipeline(&admission)?;
                self.tool_machines.ingress = tool;
                let result = self.dispatch_typed_command_inner(command, admission, meta).await;
                self.tool_machines.ingress = None;
                result
            }
        }

        /// 🎯️ Validates manifest structural app/mode ownership, converts the addressed
        /// invocation arguments once into the app's typed command, and enters the typed dispatch channel.
        async fn dispatch_command(&mut self, invocation: &ManifestCommandInvocation, active_mode_id: Option<&str>, meta: &ActionMeta) -> Result<InvocationResult, Fault> {
            let command_id = invocation.address.command_id.as_str();
            let owner_app_id = self.app.instance_id().await.to_string();
            let (owner, definition) = match &invocation.address.owner {
                ManifestCommandOwnerAddress::App { app_id, .. } => {
                    if app_id != &owner_app_id {
                        return Err(Fault::from(format!("command '{command_id}' is not owned by app {owner_app_id}")));
                    }
                    (format!("app {owner_app_id}"), self.registry.app_command(command_id).await.ok_or_else(|| Fault::from(format!("command '{command_id}' is not owned by app {owner_app_id}")))?)
                }
                ManifestCommandOwnerAddress::Mode { app_id, mode_id, .. } => {
                    if app_id != &owner_app_id || active_mode_id != Some(mode_id.as_str()) {
                        return Err(Fault::from(format!("command '{command_id}' is not owned by active mode {mode_id} of app {owner_app_id}")));
                    }
                    (format!("mode {mode_id}"), self.registry.mode_command(mode_id, command_id).await.ok_or_else(|| Fault::from(format!("command '{command_id}' is not owned by active mode {mode_id} of app {owner_app_id}")))?)
                }
                _ => return Err(Fault::from(format!("command '{command_id}' is not app- or mode-owned"))),
            };
            validate_ui_dispatch_classification(&owner, command_id, definition.semantics.execution.interactive_job)?;
            let kind = definition.kind;
            let args = DslValue::Object(invocation.arguments.iter().map(|(key, value)| (key.clone(), value.clone())).collect());
            let args = match self.import_staging.admit_args(Some(&args)).map_err(|refusal| Fault::new(FaultOrigin::Framework, FaultCode::new(refusal.code()), refusal.message()))? {
                semio_framework::kernel::ImportArguments::Staged { .. } => return Ok(Self::empty_result(command_id, meta, Vec::new(), Vec::new(), UiDirtyScope::None).await),
                semio_framework::kernel::ImportArguments::Whole(whole) => whole,
                semio_framework::kernel::ImportArguments::NotAnImport => args,
            };
            if let Some(config_mutation) = A::host_configuration_mutation(command_id, Some(&args))? {
                let admission = self.admit_host_configuration_json(command_id, Some(&args)).await?;
                self.require_tool_operation_authority(&admission)?;
                let encoded = ::protocol::OpBinary::encode_op(&config_mutation).map_err(|error| error.into_fault())?;
                if encoded.len() > admission.proof.contract().max_output_bytes {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.host-configuration-output"), format!("host configuration command '{command_id}' exceeds its exact output cap")));
                }
                let previous_kind = self.invocation_kind.replace(kind);
                let result = self.dispatch_emit(command_id, Emit::config(vec![config_mutation]), meta).await;
                self.invocation_kind = previous_kind;
                return result;
            }
            let command = A::command_from_action(command_id, Some(&args)).await?;
            let wire = <A::Command as ::protocol::OpBinary>::encode_op(&command).map_err(|error| error.into_fault())?;
            let admission = self.admit_command_wire(command_id, &wire, 1).await?;
            self.require_complete_tool_operation_pipeline(&admission)?;
            let previous_kind = self.invocation_kind.replace(kind);
            let result = self.dispatch_typed_command_inner(Box::new(command), admission, meta).await;
            self.invocation_kind = previous_kind;
            result
        }

        /// 🔐️ The agent lane's revision fill (ticket 26/09/23, G12 session 14c): a declared
        /// [`ActionArgDef::document_revision`] / [`ActionArgDef::target_revision`] argument the agent omitted is admitted against
        /// the token its rendered binding carries right now — the document's canonical revision (what every document-scoped
        /// verb compares against on this lane), or the app's own [`ArtifactApp::agent_target_revision`]; a target the app cannot
        /// resolve is refused by name. Only this lane fills: the shell lanes pass the binding's token and the app's parser
        /// refuses its absence there; the gateway admits an omission only behind a passed MCP `expectedRevision` (the
        /// document-level stale-write guard), and its prepare→invoke pair refuses a document that moved in between.
        async fn fill_agent_revisions(&mut self, address: &semio_framework::manifest::ActionAddress, arguments: &mut std::collections::BTreeMap<String, DslValue>) -> Result<(), Fault> {
            let declared = match address.window_kind_id.as_str() {
                "*" => self.registry.get(&address.action_id).map(|action| action.args.clone()),
                kind => self.registry.window_action(kind, &address.action_id).await.map(|action| action.args.clone()),
            }
            .unwrap_or_default();
            let omitted: Vec<_> = declared.into_iter().filter(|arg| !arguments.contains_key(&arg.id)).collect();
            for arg in omitted.iter() {
                let semio_framework::manifest::ArgSchema::String { format: Some(format), .. } = &arg.schema else { continue };
                let token = match format {
                    semio_framework::manifest::ArgFormat::DocumentRevision => self.store.content_revision().iter().map(|byte| format!("{byte:02x}")).collect::<String>(),
                    semio_framework::manifest::ArgFormat::TargetRevision => {
                        self.refresh_cache().await?;
                        let render_operation = self.live_render_operation();
                        let parent_document_id = self.store.envelope().id.clone();
                        let staged = DslValue::Object(arguments.iter().map(|(key, value)| (key.clone(), value.clone())).collect());
                        let (_, snapshot, _, history) = self.cache.as_ref().expect("cache refreshed above");
                        let doc = ArtifactView::with_render_context(snapshot.as_ref(), history.as_ref(), ChildContentView::clone(&self.child_content_root), render_operation, parent_document_id, None).await;
                        A::agent_target_revision(&address.action_id, &staged, &doc).await?.ok_or_else(|| {
                            Fault::new(
                                FaultOrigin::Framework,
                                FaultCode::new("agent.target-revision-unresolved"),
                                format!("action '{}' binds its `{}` to one addressed target and this app resolves no such target for an agent — pass the target's revision", address.action_id, arg.id),
                            )
                        })?
                    }
                    _ => continue,
                };
                arguments.insert(arg.id.clone(), DslValue::String(token));
            }
            Ok(())
        }

        /// 🧮️ PHASE ONE of the agent lane's two-phase contract: validate, price, and produce the ops
        /// **without applying any of them**.
        ///
        /// 🧭️ Why this cannot be `AppCommand::Command`. The shell's dispatch lane APPLIES: it runs
        /// `handle_action_invocation` → `dispatch_typed_command_inner`, which mounts a typed
        /// operation whose publication ladder commits into `self.store` and mints an undo group. An
        /// agent's `action_prepare` must not do that — its own protocol commits separately
        /// (`TransactionPrepare{ops}` → `TransactionCommit`), and `RoutingArtifactChannel` caches ONE
        /// guest instance per plugin, so a prepare that applied would leave the commit applying the
        /// same edit a second time. `history_undo` (which walks back exactly one application) would
        /// then leave half the edit standing — a GREEN gate that lies, which is worse than a red one.
        ///
        /// ✅️ What it shares with the shell lane, deliberately and by call rather than by copy:
        /// the owner-qualified `ManifestActionInvocation` address, `admit_addressed_action_view`'s
        /// window projection, the mode/window-kind ownership checks `handle_action_invocation` runs,
        /// the `windowId` argument it injects, `validate_ui_dispatch_classification`'s interactive-job
        /// discipline, `A::command_from_action`, the exact retained-wire admission `dispatch_action`
        /// begins (`admit_command_wire` + `require_complete_tool_operation_pipeline`) and the app's own
        /// job, built and dispatched through the same factory entry ([`Self::preview_typed_command_job`]).
        /// The one thing it does NOT share is the applying tail: the job runs to the completion it would
        /// publish, and nothing is published. It fails closed ([`agent_lane_carriage`]): a completion that publishes
        /// anything an agent transaction cannot carry is refused by name, never settled without it, and one that carries
        /// nothing but a notice or a selection is refused `app.command.no-effect`, its notices as structured causes.
        ///
        /// 🎟️ The admission it begins is consumed by the previewed job within this same call and retired
        /// through that job's own close protocol, so a prepared handle the caller never invokes leaves
        /// nothing behind.
        ///
        /// 🪟️ `"*"` is the catalog's own marker for an APP-scope verb — one that belongs to no
        /// particular window kind (`🗒️note` declares all 48 of its verbs this way). A concrete
        /// kind must own the verb; `"*"` addresses the app registry directly, exactly as
        /// `dispatch_action` does for every verb the shell sends.
        async fn preview_addressed_action(&mut self, invocation: &ManifestActionInvocation, meta: &ActionMeta) -> Result<InvocationResult, Fault> {
            let address = &invocation.address;
            let owner_app_id = self.app.instance_id().await;
            if address.app_id != owner_app_id {
                return Err(plugin_sdk_fault(format!("action app owner {} does not match {owner_app_id}", address.app_id)));
            }
            if address.window_instance_id.trim().is_empty() {
                return Err(plugin_sdk_fault("action window instance id must be non-empty"));
            }
            let reserved_kind = framework_reserved_action_kind(&address.action_id);
            if reserved_kind.is_none() && !self.registry.has_mode(&address.mode_id).await {
                return Err(plugin_sdk_fault(format!("unknown action mode owner {}", address.mode_id)));
            }
            if address.window_kind_id != "*" && reserved_kind.is_none() && self.registry.window_action(&address.window_kind_id, &address.action_id).await.is_none() {
                return Err(plugin_sdk_fault(format!("window kind {} does not own action {}", address.window_kind_id, address.action_id)));
            }
            let context = meta.view_state.as_ref().ok_or_else(|| plugin_sdk_fault("addressed action requires the caller's explicit language and terminology context"))?;
            let view = crate::plugin_runtime::admit_addressed_action_view(context, invocation)?;
            let definition = self
                .registry
                .get(&address.action_id)
                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.unknown-key"), format!("UI dispatch rejected unknown action key '{}' before command construction", address.action_id)))?;
            let kind = definition.kind;
            validate_ui_dispatch_classification("action", &address.action_id, definition.semantics.execution.interactive_job)?;
            let mut arguments = invocation.arguments.clone();
            arguments.insert("windowId".into(), DslValue::String(address.window_instance_id.clone()));
            self.fill_agent_revisions(address, &mut arguments).await?;
            let args = DslValue::Object(arguments.into_iter().collect());
            let command = A::command_from_action(&address.action_id, Some(&args)).await?;
            let wire = <A::Command as ::protocol::OpBinary>::encode_op(&command).map_err(|error| error.into_fault())?;
            let admission = self.admit_command_wire(&address.action_id, &wire, 1).await?;
            self.require_complete_tool_operation_pipeline(&admission)?;
            let contract = admission.proof.contract();
            let (emit, (presence, transient, window_transient), job_steps) = self.preview_typed_command_job(Box::new(command), admission, &ActionMeta { view_state: Some(view.clone()), ..meta.clone() }).await?;
            let carriage = agent_lane_carriage(&AgentLanePublication {
                carried_ops: emit.artifact_mutations.len() + emit.config_mutations.len() + emit.draft_mutations.len() + emit.child_emits.len(),
                effects: &emit.effects,
                window_config_ops: emit.window_config_mutations.len(),
                extension_calls: emit.extension_invocations.len(),
                events: emit.events.len(),
                selection_writes: emit.interaction_writes.len(),
                tasks: emit.tasks.len(),
                presence,
                transient,
                window_transient,
            });
            match carriage {
                AgentLaneCarriage::Carried => {}
                AgentLaneCarriage::NoEffect => return Err(agent_lane_no_effect_fault(&address.action_id, &emit.effects)),
                AgentLaneCarriage::Uncarried(lanes) => return Err(agent_lane_uncarried_fault(&address.action_id, &lanes.join(", "))),
            }
            if A::ROLE == AppRole::Viewer && (!emit.artifact_mutations.is_empty() || !emit.child_emits.is_empty()) {
                return Err(viewer_read_only_fault(&address.action_id));
            }
            let mut artifact_op_bytes = Vec::with_capacity(emit.artifact_mutations.len());
            for op in emit.artifact_mutations.iter() {
                artifact_op_bytes.push(::protocol::OpBinary::encode_op(op).map_err(|error| error.into_fault())?);
            }
            for child in emit.child_emits.iter() {
                if self.children.get(&(child.slot.clone(), child.child_id.clone())).is_none() {
                    return Err(Fault::new(
                        FaultOrigin::Framework,
                        FaultCode::new("interactive-job.agent-lane-child-missing"),
                        format!("action '{}' edits owned child {:?} in slot {:?}, which this instance does not hold", address.action_id, child.child_id, child.slot),
                    ));
                }
            }
            let child_op_bytes = ChildEmit::encode_groups(&emit.child_emits);
            let mut config_op_bytes = Vec::with_capacity(emit.config_mutations.len());
            for op in emit.config_mutations.iter() {
                config_op_bytes.push(::protocol::OpBinary::encode_op(op).map_err(|error| error.into_fault())?);
            }
            let mut draft_op_bytes = Vec::with_capacity(emit.draft_mutations.len());
            for op in emit.draft_mutations.iter() {
                draft_op_bytes.push(::protocol::OpBinary::encode_op(op).map_err(|error| error.into_fault())?);
            }
            let priced = artifact_op_bytes.iter().chain(config_op_bytes.iter()).chain(draft_op_bytes.iter()).map(Vec::len).sum::<usize>();
            if priced > contract.max_output_bytes {
                return Err(Fault::new(
                    FaultOrigin::Framework,
                    FaultCode::new("interactive-job.preview-output"),
                    format!("previewed action '{}' produced {priced} op byte(s); its exact output cap is {}", address.action_id, contract.max_output_bytes),
                ));
            }
            self.last_emit_wire = Some(EmitWire { document: protocol::encode_ops_vec(&artifact_op_bytes), config: protocol::encode_ops_vec(&config_op_bytes), draft: protocol::encode_ops_vec(&draft_op_bytes), children: child_op_bytes });
            let mut result = Self::empty_result(&address.action_id, meta, Vec::new(), Vec::new(), UiDirtyScope::None).await;
            result.output = DslValue::Object(vec![
                ("previewedAction".into(), DslValue::String(address.action_id.clone())),
                ("actionKind".into(), DslValue::String(format!("{kind:?}"))),
                ("documentOps".into(), DslValue::String(artifact_op_bytes.len().to_string())),
                ("configOps".into(), DslValue::String(config_op_bytes.len().to_string())),
                ("draftOps".into(), DslValue::String(draft_op_bytes.len().to_string())),
                ("childGroups".into(), DslValue::String(emit.child_emits.len().to_string())),
                ("opBytes".into(), DslValue::String(priced.to_string())),
                ("jobSteps".into(), DslValue::String(job_steps.to_string())),
            ]);
            Ok(result)
        }

        /// 🪪️ The identity every id one admitted command mints is scoped by ([`AppOperationContext::authoring_seed`]):
        /// content-addressed with [`store::content_id`] over the admitting actor and this document store's hybrid
        /// logical clock ticked for the admission — per author and moment, never a per-instance counter a fresh
        /// session restarts.
        fn authoring_seed(&self, actor: &str) -> String {
            let mut clock = self.store.clock_now();
            clock.tick(semio_framework_job::default_now_ms().unwrap_or(clock.physical_ms));
            store::content_id("authoring-seed", format!("{actor}\u{1f}{}:{}:{}", clock.actor, clock.physical_ms, clock.logical).as_bytes())
        }

        /// 👁️ Builds the SAME app-owned job the shell lane builds for this admitted command (`A::build_tool_job` over
        /// [`Self::capture_typed_command_roots`]), dispatches it through the SAME retained-wire factory entry
        /// `start_typed_command_operation` uses, and drives it through its own steps on this turn
        /// ([`drive_agent_lane_preview`]) to the completion it would publish — publishing nothing. Every job shape an
        /// app owns previews this way: the SDK's retained command, a plugin's own tool-command job (puzzle, writer, …)
        /// and a download job, whose file an agent transaction cannot carry and is refused by name. The run holds a
        /// keyed cancellation lease, so cancelling the document cancels the preview. Answers the emit, how many presence,
        /// transient and window-transient mutations the job's completion would publish (lanes an agent
        /// transaction cannot carry, see [`agent_lane_uncarried_lanes`]) and how many of the job's own steps ran.
        async fn preview_typed_command_job(&mut self, command: Box<A::Command>, admission: AdmittedToolCommand, meta: &ActionMeta) -> Result<(Emit<A::Mutation, A::ConfigMutation, A::DraftMutation>, (usize, usize, usize), u64), Fault> {
            let verb = admission.verb.clone();
            let roots = self.capture_typed_command_roots(command.as_ref(), meta).await?;
            let operation_id =
                self.admit_typed_operation_slot().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.typed-operation-capacity"), "every fixed typed-operation and segmented-output slot already owns a live operation"))?;
            let seed_handle = artifact_handle_of(&format!("{}/{}/{verb}/{}", meta.instance_id, self.tool_job_controller_id, roots.base_revision.0)).await;
            let operation = semio_framework_job::Operation::new(operation_id, roots.base_revision, roots.generation, (seed_handle.0 as u64) ^ ((seed_handle.0 >> 64) as u64));
            let lease =
                self.tool_cancellations.begin_keyed(ToolOperationKey { app_instance_id: meta.instance_id, document: ArtifactDocumentAuthority(meta.instance_id), operation_id, base_revision: roots.base_revision, generation: roots.generation })?;
            let completion = ArtifactToolCompletion::<A>::new();
            let context = std::sync::Arc::new(
                ArtifactOwnedToolJobContext::new(
                    meta.instance_id,
                    meta.view_state.clone(),
                    roots.canonical_base_revision,
                    roots.draft_generation,
                    roots.transient_generation,
                    ArtifactOwnedToolJobSnapshots {
                        children: std::sync::Arc::clone(&roots.children),
                        draft: std::sync::Arc::clone(&roots.draft_snapshot),
                        transient: std::sync::Arc::clone(&roots.transient),
                        window_config: roots.window_config_authority.as_ref().map(|authority| authority.snapshot.clone()),
                        window_transient: roots.window_transient_authority.as_ref().map(|authority| authority.snapshot.clone()),
                    },
                )
                .with_presence(self.presence_store.local_read().map_err(Fault::from)?, std::sync::Arc::clone(&roots.presence_peers))
                .with_tool_run(self.tool_runs.view_for(meta.view_state.as_ref().and_then(|view| view.window_id.as_deref())))
                .with_provisional(self.tool_machines.provisional_values(), self.tool_machines.provisional_generation()),
            );
            let key = admission.proof.key();
            let contract = admission.proof.contract();
            let spec = A::build_tool_job(ArtifactOwnedToolJobRequest {
                command,
                raw_wire: ArtifactToolRawInput::transferred_to_factory(),
                operation,
                controller_id: key.controller_id,
                tool_id: key.tool_id,
                payload_schema_id: admission.proof.schema_id(),
                contract,
                decoded_items: admission.decoded_items,
                app_instance_id: meta.instance_id,
                parent_document_id: self.store.envelope().id.clone(),
                canonical_base_revision: roots.canonical_base_revision,
                authoring_seed: self.authoring_seed(&meta.actor),
                snapshot: roots.snapshot,
                config: roots.config,
                window_config: roots.window_config_authority.as_ref().map(|authority| authority.snapshot.clone()),
                history: roots.history,
                interaction_state: roots.interaction_state,
                interaction_hover: std::sync::Arc::new(roots.interaction_hover),
                context,
                instance_operation_owner: self.instance_operation_owner.clone(),
                output_chunks: ArtifactOutputChunks::new(contract.max_output_bytes),
                completion: completion.clone(),
            })
            .await?
            .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.missing-owned-builder"), format!("app-owned tool '{verb}' registered a factory but supplied no exact payload builder")))?;
            let wire_admission = admission.wire_admission.clone();
            let dispatch =
                self.tool_jobs.dispatch_wire_retained_with_spec(&wire_admission, admission.raw_wire, None, spec).map_err(|rejected| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.dispatch"), rejected.error.to_string()))?;
            let params = semio_framework_job::BatchJobParams {
                operation: operation_id,
                generation: roots.generation,
                cancel: lease.cancel_token(),
                config: semio_framework_job::BatchDriveConfig {
                    site: "plugin_agent_lane_preview",
                    stage: semio_framework_job::InteractiveStage::InteractiveStep,
                    fuel_per_step: contract.max_work_units_per_step,
                    step_budget_us: u64::from(contract.max_step_micros),
                },
                now_us: semio_framework_job::default_now_us,
            };
            #[cfg(test)]
            let params = semio_framework_job::BatchJobParams { now_us: self.test_tool_clock.unwrap_or(params.now_us), ..params };
            let driven = drive_agent_lane_preview(dispatch.job, params, &verb);
            lease.finish();
            let steps = driven?;
            match completion.take()? {
                Some(ArtifactToolCompletionValue::Emit(emit, ephemeral)) => {
                    emit.map(|emit| (emit, (ephemeral.presence.len(), ephemeral.transient.len(), ephemeral.window_transient.len()), steps)).map_err(ArtifactBoundedToolFault::into_fault)
                }
                Some(ArtifactToolCompletionValue::Download(_, _)) => Err(agent_lane_uncarried_fault(&verb, "a file download")),
                None => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.missing-output"), format!("the previewed job of action '{verb}' completed without producer output"))),
            }
        }

        /// 🧩️ A typed frame IS an owner-qualified invocation — the exact wire `AppCommand::Command`
        /// carries. Decoding it here is what gives the agent lane the same dispatch the shell's UI
        /// lane has; running it through [`Self::preview_addressed_action`] rather than
        /// `handle_action_invocation` is what makes it a PREPARE (see that method's own doc).
        async fn dispatch_command_frame(&mut self, command_bytes: &[u8], meta: &ActionMeta) -> Result<InvocationResult, Fault> {
            let invocation: ManifestActionInvocation = crate::plugin_runtime::decode_wire_serialized(command_bytes).await.map_err(|_| {
                Fault::new(
                    FaultOrigin::Framework,
                    FaultCode::new("interactive-job.missing-exact-key"),
                    "a typed command frame carries one owner-qualified ManifestActionInvocation — the same wire AppCommand::Command carries; this frame decoded as neither, so no command-specific pre-serde envelope can be selected",
                )
            })?;
            self.preview_addressed_action(&invocation, meta).await
        }

        /// 📬️ Advances exactly one retained publication unit. Store lanes return one-item
        /// receipts; host lanes remain in the operation until their fixed result page is ACKed.
        /// 🏃️ Drives one Worker-stage typed operation for a bounded slice of this turn. The mounted
        /// worker session only submits a job step to the process pool; on wasm that pool has no threads
        /// and runs a step solely when it is pumped, and until now the only pump was the
        /// cooperative-maintenance cadence (`maintenance_step` stage 0 of 21, one call per ~8 reactor
        /// turns) — measured 2026-09-09: 3 interactive job steps in 4 096 reactor turns, every action
        /// exhausting the host's continuation budget with `more-work`. Bounded by
        /// [`INTERACTIVE_TURN_WORKER_PUMPS`] and [`INTERACTIVE_TURN_WORKER_WALL_US`].
        ///
        /// 🛑️ ONE operation's structural fault is that operation's fault, never the turn's:
        /// see [`Self::fault_typed_operation_worker`].
        fn drive_typed_operation_worker(&mut self, operation_id: u64) -> Result<(), Fault> {
            let pool = semio_framework_async::process_worker_pool(semio_framework_async::WorkerPoolConfig::new(semio_framework_async::ProcessKind::InteractiveNative, std::thread::available_parallelism().map_or(1, std::num::NonZeroUsize::get)));
            let started_us = semio_framework_job::default_now_us();
            for _ in 0..INTERACTIVE_TURN_WORKER_PUMPS {
                let stepped = {
                    let Some(operation) = self.tool_operations.get_mut(operation_id) else { return Ok(()) };
                    if operation.stage != MountedTypedCommandFullOperationStage::Worker {
                        return Ok(());
                    }
                    operation.drive_worker_step(&pool, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES)
                };
                let step = match stepped {
                    Ok(step) => step,
                    Err(fault) => return self.fault_typed_operation_worker(operation_id, &fault),
                };
                #[cfg(target_arch = "wasm32")]
                if let Some(now_ms) = semio_framework_job::default_now_ms() {
                    pool.pump(now_ms);
                }
                if matches!(step, PluginCloseStep::Blocked { .. }) {
                    return Ok(());
                }
                let Some(started_us) = started_us else { return Ok(()) };
                if semio_framework_job::default_now_us().is_some_and(|now_us| now_us.saturating_sub(started_us) >= INTERACTIVE_TURN_WORKER_WALL_US) {
                    return Ok(());
                }
            }
            Ok(())
        }

        /// 🏃️ Drives the live artifact-envelope decode workers for a bounded slice of this turn, the
        /// same reactor-turn pump [`Self::drive_typed_operation_worker`] gives a Worker-stage typed
        /// operation. `ActiveArtifactEnvelopeDecode::drive` only SUBMITS a step to the process pool;
        /// on wasm that pool has no threads and runs a step solely when it is pumped, and the only
        /// driver was the cooperative-maintenance cadence (`maintenance_step` stage 11 of
        /// [`MAINTENANCE_STAGES`], one visit per rotation), so opening or replacing a document never
        /// advanced inside an interactive turn (ticket 26/09/09/PROCEDURAL-3D-END-TO-END). Bounded by
        /// [`INTERACTIVE_TURN_WORKER_PUMPS`] and [`INTERACTIVE_TURN_WORKER_WALL_US`]. The two return
        /// pumps belong to the SAME ladder — a decode parks in release until its field-decoder lease
        /// and completed record are reclaimed — so pumping only the worker would stall every load.
        ///
        /// 📏️ A decode job's terminal outcome (its fault detail above all) is a `RetainedJobPayload`
        /// whose pages are `JOB_PAYLOAD_PAGE_BYTES` (16 KiB) — a close grant under one page
        /// releases nothing, so a faulted decode spun on its own close forever and the host poll
        /// never learnt of the fault (ticket 26/09/17/TRINITY-PLUGIN-END-TO-END). The envelope page
        /// grant stays for the field-decoder and completed-record returns, which page at 4 KiB.
        fn drive_artifact_envelope_decode_worker(&mut self) -> Result<(), Fault> {
            let started_us = semio_framework_job::default_now_us();
            const DECODE_JOB_CLOSE_BYTES: usize = if semio_framework_job::JOB_PAYLOAD_PAGE_BYTES > store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES { semio_framework_job::JOB_PAYLOAD_PAGE_BYTES } else { store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES };
            for _ in 0..INTERACTIVE_TURN_WORKER_PUMPS {
                if !self.has_runnable_artifact_envelope_decode() {
                    return Ok(());
                }
                self.drive_envelope_field_decoder_returns(1, store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES, false)?;
                self.drive_envelope_completed_record_returns(1, store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES, false)?;
                self.drive_envelope_decode_jobs(1, DECODE_JOB_CLOSE_BYTES, false)?;
                let Some(started_us) = started_us else { return Ok(()) };
                if semio_framework_job::default_now_us().is_some_and(|now_us| now_us.saturating_sub(started_us) >= INTERACTIVE_TURN_WORKER_WALL_US) {
                    return Ok(());
                }
            }
            Ok(())
        }

        /// 🔎️ Whether any live envelope decode still has worker close or step work this turn can run.
        fn has_runnable_artifact_envelope_decode(&self) -> bool {
            (0..ARTIFACT_LIVE_OUTPUT_SLOTS).any(|index| self.envelope_decode_jobs.entry(index).is_some_and(|(_, active)| active.has_runnable_work()))
        }

        fn has_runnable_artifact_envelope_decode_worker_step(&self) -> bool {
            self.has_runnable_artifact_envelope_decode()
        }

        /// 🎯️ The next mounted operation this turn's one publication unit can actually advance, taken from
        /// the rotating publication cursor. An `AwaitingAck` operation whose page is already out keeps the
        /// turn in `MoreWork` — the host owes it an acknowledgement event — but owns no step of its own
        /// until that event lands, so spending the turn's only unit on it starves every sibling that does
        /// have one (ticket 26/09/02/PUZZLE-3D-END-TO-END wave B16).
        /// 🚫️async: E1 pure census over an already-owned fixed table — see R9.
        fn next_advanceable_typed_operation(&self) -> Option<(usize, u64)> {
            (0..ARTIFACT_LIVE_OUTPUT_SLOTS).find_map(|offset| {
                let index = (self.typed_publication_cursor + offset) % ARTIFACT_LIVE_OUTPUT_SLOTS;
                self.tool_operations.entry(index).filter(|(_, operation)| operation.stage != MountedTypedCommandFullOperationStage::AwaitingAck).map(|(id, _)| (index, *id))
            })
        }

        /// 🩺️ What the publication cursor is about to advance, as the four facts that decide whether the
        /// ladder can move at all AND whether it did: the operation it selected, that operation's stage,
        /// the ownership flags the arms branch on, and the publication's own monotone progress.
        /// Compared before and after one unit by [`Self::typed_operation_stall_streak`].
        ///
        /// 🐛️ The progress term is the fourth fact because the first three are constant for a HEALTHY
        /// publication: an edit of 5 745 mutations (puzzle5d's `capsule-dream` example switch) folds one
        /// bounded mutation per unit for ~19 000 units with the same operation id, the same `Publishing`
        /// stage and the same ownership flags, so the streak counter could not tell it from an owner that
        /// can never advance and terminated it at [`TYPED_OPERATION_STALL_FAULT_CEILING`] — about a fifth
        /// of the way through — with `interactive-job.publication-stalled`. Measured by the
        /// "Semio-tech play" session on 2026-09-21. Raising the ceiling would only move the cliff to the
        /// next document size and re-open the silent spins the guard exists to catch.
        /// 🚫️async: E1 pure census over an already-owned fixed table — see R9.
        fn typed_operation_stall_witness(&self) -> Option<(u64, u8, u8, u64)> {
            let (_, operation_id) = self.next_advanceable_typed_operation()?;
            let operation = self.tool_operations.get(operation_id)?;
            let stage = match operation.stage {
                MountedTypedCommandFullOperationStage::Worker => 0,
                MountedTypedCommandFullOperationStage::Publishing => 1,
                MountedTypedCommandFullOperationStage::AwaitingAck => 2,
                MountedTypedCommandFullOperationStage::Retiring => 3,
            };
            let flags = u8::from(operation.session.is_some())
                | u8::from(operation.session_rejected.is_some()) << 1
                | u8::from(operation.completion.is_some()) << 2
                | u8::from(operation.publication.is_some()) << 3
                | u8::from(operation.pending_artifact_publication.is_some()) << 4
                | u8::from(operation.terminal_outcome.is_some()) << 5
                | u8::from(operation.terminal_seen) << 6
                | u8::from(operation.result_page.is_some()) << 7;
            Some((operation_id, stage, flags, operation.publication_progress))
        }

        /// 🩺️ How many consecutive publication units advanced the SAME operation without changing any of
        /// [`Self::typed_operation_stall_witness`]'s three facts — `Some(streak)` only on a power of two at
        /// or above [`TYPED_OPERATION_STALL_WITNESS_FLOOR`], so one stalled operation costs at most a
        /// handful of lines however long it spins.
        ///
        /// 🐛️ A mounted operation that never publishes its terminal keeps the actor in `MoreWork` with no
        /// effect, no patch and no fault, which every other instrument reads as silence: the host's own
        /// drain polls forever, the reactor's more-work streak names only `typed_operation` as its source,
        /// and nothing says WHICH arm of the publication ladder is not moving. Measured 2026-09-20 on the
        /// signed-in `s` Home, whose `applyDirectoryEventPage` operation spun for the whole session
        /// (ticket 26/09/18 S8).
        fn typed_operation_stall_streak(before: (u64, u8, u8, u64), after: (u64, u8, u8, u64)) -> Option<u64> {
            static WITNESS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(u64::MAX);
            static STREAK: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
            let key = (after.0.wrapping_shl(16) | u64::from(after.1).wrapping_shl(8) | u64::from(after.2)) ^ after.3.wrapping_mul(TYPED_OPERATION_STALL_PROGRESS_MIX);
            if before != after || WITNESS.swap(key, std::sync::atomic::Ordering::Relaxed) != key {
                STREAK.store(0, std::sync::atomic::Ordering::Relaxed);
                return None;
            }
            let streak = STREAK.fetch_add(1, std::sync::atomic::Ordering::Relaxed).saturating_add(1);
            (streak >= TYPED_OPERATION_STALL_WITNESS_FLOOR && streak.is_power_of_two()).then_some(streak)
        }

        async fn advance_typed_operation_publication_one(&mut self) -> Result<(), Fault> {
            let before = self.typed_operation_stall_witness();
            let advanced = self.advance_typed_operation_publication_unit().await;
            if let (Some(before), Some(after)) = (before, self.typed_operation_stall_witness()) {
                if let Some(streak) = Self::typed_operation_stall_streak(before, after) {
                    let verb = self.tool_operations.get(after.0).map_or("<released>", |operation| operation.verb.as_str());
                    crate::plugin_runtime::debug_runtime_line(format_args!("[TRACE] typed-operation {verb} advanced {streak} units with no change: operation={} stage={} flags={:#010b}", after.0, after.1, after.2));
                    if after.1 == TYPED_OPERATION_STALL_PUBLISHING_STAGE && streak >= TYPED_OPERATION_STALL_FAULT_CEILING {
                        self.fault_stalled_typed_operation_publication(after.0, streak)?;
                    }
                }
            }
            advanced
        }

        /// 🛑️ Terminates the ONE `Worker`-stage operation whose own step answered a structural
        /// `Err` — an operation that lost its persistent worker session, or whose mounted session
        /// reported a state its own ladder cannot continue from — with that operation's terminal
        /// fault page, and lets the turn carry on.
        ///
        /// 🎯️ Why it is not a `?`: `drive_typed_operation_worker` is called from
        /// [`Self::advance_typed_operation_publication_unit`], the actor's ONE publication unit per
        /// turn. Propagating the `Err` aborted that unit for the WHOLE actor, so a single
        /// structurally faulted operation stopped every other mounted operation from ever advancing
        /// again — with no fault page, no effect and no patch to say why. The `Publishing` lane has
        /// answered this correctly since wave B16 (`advance_typed_operation_publication_unit`'s
        /// retry ladder, and [`Self::fault_stalled_typed_operation_publication`]'s own doc: a
        /// per-operation failure becomes that operation's fault, never the turn's); the `Worker`
        /// lane was the one lane that did not honour it.
        ///
        /// 🔒️ The operation is terminal the moment its worker ladder refuses: the lease is
        /// cancelled so no publication claim can be taken again, the fault page is minted against
        /// the operation's own token, and the stage moves to `Publishing` so the ordinary
        /// cancelled-publication close (`reject_cancelled_publication`) retires everything it still
        /// owns. Nothing is dropped here — the retained owners leave through the close ladder they
        /// always did.
        fn fault_typed_operation_worker(&mut self, operation_id: u64, fault: &Fault) -> Result<(), Fault> {
            let Some(mounted) = self.tool_operations.get_mut(operation_id) else { return Ok(()) };
            if mounted.stage != MountedTypedCommandFullOperationStage::Worker || mounted.result_page.is_some() {
                return Ok(());
            }
            let bounded = ArtifactBoundedToolFault::from_fault(fault);
            if let Some(lease) = mounted.cancellation_lease.as_ref() {
                lease.cancel();
            }
            let mut framed = [0; TYPED_OPERATION_FAULT_PAGE_BYTES];
            let framed_len = bounded.framed_page_bytes(&mut framed);
            mounted.stage = MountedTypedCommandFullOperationStage::Publishing;
            let page = TypedOperationResultPage::try_new(mounted.next_token(), TypedOperationResultLane::Fault, &framed[..framed_len])?;
            mounted.terminal_fault = Some(bounded);
            mounted.queue_page(page)
        }

        /// 🛑️ Terminates a `Publishing`-stage operation whose ladder has not moved for
        /// [`TYPED_OPERATION_STALL_FAULT_CEILING`] units with a real fault page instead of leaving it to
        /// spin. The publication ladder's non-advancing answers are all `Ok(())` by design — a completion
        /// that is not ready yet, and `ArtifactStoreOneItemAdvance::Blocked` from a store owner that
        /// refuses the granted page — so an owner that can NEVER advance pins its actor in `MoreWork`
        /// with no effect, no patch and no fault, which no instrument reads as a failure.
        ///
        /// Only the `Publishing` stage is bounded this way: a `Worker`-stage operation's progress is its
        /// own job's business and a long tool run legitimately leaves this witness unchanged for as long
        /// as it runs. Measured first on the signed-in `s` Home, whose `applyDirectoryEventPage` config
        /// publication answered `Blocked` on every unit (ticket 26/09/18 S8).
        fn fault_stalled_typed_operation_publication(&mut self, operation_id: u64, streak: u64) -> Result<(), Fault> {
            let Some(mounted) = self.tool_operations.get_mut(operation_id) else { return Ok(()) };
            if mounted.stage != MountedTypedCommandFullOperationStage::Publishing || mounted.result_page.is_some() {
                return Ok(());
            }
            let fault = ArtifactBoundedToolFault::from_fault(&Fault::new(
                FaultOrigin::Framework,
                FaultCode::new("interactive-job.publication-stalled"),
                format!("typed operation '{}' advanced {streak} publication units without moving its ladder", mounted.verb),
            ));
            if let Some(lease) = mounted.cancellation_lease.as_ref() {
                lease.cancel();
            }
            let mut framed = [0; TYPED_OPERATION_FAULT_PAGE_BYTES];
            let framed_len = fault.framed_page_bytes(&mut framed);
            let page = TypedOperationResultPage::try_new(mounted.next_token(), TypedOperationResultLane::Fault, &framed[..framed_len])?;
            mounted.terminal_fault = Some(fault);
            mounted.queue_page(page)
        }

        /// ♻️ A retiring operation answers `has_runnable_typed_operations`, so the turn driver that reports it
        /// runnable must be the one that releases its slot — see [`Self::retire_typed_operation_run`].
        ///
        /// 🕹️ "After EVERY artifact (document) dispatch, re-derive fresh topology and prune any
        /// selection/hover id no longer present" — the clause `dispatch_emit_inner` carries, which
        /// the migrated publication ladder never reaches (see the emit backstops above it). A
        /// migrated dispatch's document change lands on the Artifact lane, so this is where the
        /// revalidation belongs; `mounted` is out of the registry here, so the async pass is free
        /// to borrow the app, and the flag makes it exactly one pass per operation.
        async fn advance_typed_operation_publication_unit(&mut self) -> Result<(), Fault> {
            if !self.latest_wins_commands.is_empty() && (self.latest_wins_turn || self.tool_operations.is_empty()) {
                self.latest_wins_turn = false;
                return self.advance_latest_wins_command_one().await;
            }
            self.latest_wins_turn = true;
            let Some((index, operation_id)) = self.next_advanceable_typed_operation() else {
                record_typed_operation_unit(TypedOperationUnitKind::Idle);
                return Ok(());
            };
            self.typed_publication_cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
            if self.tool_operations.get(operation_id).is_some_and(|operation| operation.stage == MountedTypedCommandFullOperationStage::Worker) {
                record_typed_operation_unit(TypedOperationUnitKind::Worker);
                return self.drive_typed_operation_worker(operation_id);
            }
            if self.tool_operations.get(operation_id).is_some_and(|operation| operation.stage == MountedTypedCommandFullOperationStage::Retiring) {
                record_typed_operation_unit(TypedOperationUnitKind::Retirement);
                return self.retire_typed_operation_run(operation_id);
            }
            if !self.tool_operations.get_mut(operation_id).is_some_and(|operation| operation.stage == MountedTypedCommandFullOperationStage::Publishing) {
                record_typed_operation_unit(TypedOperationUnitKind::Idle);
                return Ok(());
            }
            let mut mounted =
                self.tool_operations.remove(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.publication-authority"), "typed-operation publication owner changed before one-unit transfer"))?;
            let outcome = self.publish_mounted_typed_operation_run(&mut mounted).await;
            if let Err(fault) = outcome {
                mounted.publication_attempt = mounted.publication_attempt.saturating_add(1);
                crate::plugin_runtime::debug_runtime_line(format_args!("[TRACE] typed-operation {} publication attempt {} faulted: {}: {}", mounted.verb, mounted.publication_attempt, fault.code.0, fault.message));
                if mounted.publication_attempt > TYPED_OPERATION_MAXIMUM_RETRIES {
                    let bounded = ArtifactBoundedToolFault::from_fault(&fault);
                    let mut framed = [0; TYPED_OPERATION_FAULT_PAGE_BYTES];
                    let framed_len = bounded.framed_page_bytes(&mut framed);
                    let page = TypedOperationResultPage::try_new(mounted.next_token(), TypedOperationResultLane::Fault, &framed[..framed_len])?;
                    mounted.result_page = None;
                    mounted.stage = MountedTypedCommandFullOperationStage::Publishing;
                    mounted.terminal_fault = Some(bounded);
                    mounted.queue_page(page)?;
                } else {
                    mounted.stage = MountedTypedCommandFullOperationStage::Publishing;
                }
            } else {
                mounted.publication_attempt = 0;
            }
            if mounted.published_artifact && !mounted.interaction_revalidated {
                mounted.interaction_revalidated = true;
                let meta = mounted.meta.clone();
                self.revalidate_interaction_state_after_document_change(&meta).await?;
            }
            self.tool_operations.insert_admitted(operation_id, mounted);
            Ok(())
        }

        /// 🏃️ Drives ONE mounted operation's publication ladder for a bounded slice of this continuation
        /// unit — the exact twin of the slice [`Self::drive_typed_operation_worker`] gives a Worker-stage
        /// operation and [`Self::retire_typed_operation_run`] gives a retiring one, for the publication
        /// state machine that sits between them.
        ///
        /// 🧾️ Every ladder step — install the taken completion, stage the batch, prepare one item, fold
        /// it, retire its preparation owner, validate the cursor, preflight the commit, commit, mint the
        /// receipt — used to be its own host round trip, because the caller is driven once per reactor
        /// turn and the store's grant pages one item per call. One `deleteSelection` on a ONE-object
        /// document therefore cost 104–235 round trips (wave B44 §2.3): a document-INDEPENDENT constant
        /// that alone burns seconds of a 30-second interaction budget, and the reason a `setCamera` on a
        /// document it never reads cost 2.3 s.
        ///
        /// 🛑️ The run stops on exactly the protocol's own bounds and on nothing else: a queued result page
        /// the host must acknowledge before the operation may continue (`stage` leaves `Publishing`), a
        /// completion that is not ready yet so nothing is staged to advance, [`TYPED_OPERATION_PUBLICATION_PUMPS`],
        /// and [`INTERACTIVE_TURN_WORKER_WALL_US`]. Ticket 26/09/02/PUZZLE-3D-END-TO-END wave B54.
        async fn publish_mounted_typed_operation_run(&mut self, mounted: &mut MountedTypedCommandFullOperation<A>) -> Result<(), Fault> {
            let started_us = semio_framework_job::default_now_us();
            for _ in 0..TYPED_OPERATION_PUBLICATION_PUMPS {
                if mounted.pending_child_publication.is_some() {
                    record_typed_operation_unit(TypedOperationUnitKind::Store);
                    self.publish_mounted_typed_child_operation_unit(mounted).await?;
                } else if Self::mounted_typed_interaction_writes_are_next(mounted) {
                    record_typed_operation_unit(TypedOperationUnitKind::Store);
                    self.publish_mounted_typed_interaction_unit(mounted).await?;
                } else if self.mounted_typed_inline_interaction_verbs_are_next(mounted) {
                    record_typed_operation_unit(TypedOperationUnitKind::Store);
                    self.publish_mounted_typed_inline_interaction_unit(mounted).await?;
                } else {
                    self.publish_mounted_typed_operation_unit(mounted).await?;
                    if self.store.backbone_ref().is_some() {
                        self.store.flush_announcements().await.map_err(|error| plugin_sdk_fault(error.to_string()))?;
                        if let Some(PendingArtifactStorePublication::Artifact(publication)) = mounted.pending_artifact_publication.as_mut() {
                            self.store.flush_published_apply_batch(publication).await.map_err(|error| plugin_sdk_fault(error.to_string()))?;
                        }
                    }
                    record_typed_operation_unit(if mounted.result_page.is_some() { TypedOperationUnitKind::Page } else { TypedOperationUnitKind::Store });
                }
                if mounted.stage != MountedTypedCommandFullOperationStage::Publishing {
                    return Ok(());
                }
                if mounted.publication.is_none() && mounted.pending_artifact_publication.is_none() && mounted.pending_child_publication.is_none() {
                    return Ok(());
                }
                let Some(started_us) = started_us else { return Ok(()) };
                if semio_framework_job::default_now_us().is_some_and(|now_us| now_us.saturating_sub(started_us) >= INTERACTIVE_TURN_WORKER_WALL_US) {
                    return Ok(());
                }
            }
            Ok(())
        }

        /// 🕹️ Whether this operation's next publication unit is its [`InteractionWrite`] lane: every
        /// durable store lane of its emit is already drained (a selection may only name ids the
        /// document already holds), and there is at least one write left to apply. Sync and
        /// allocation-free so the async caller can branch on it before mounting anything.
        /// 🚫️async: E1 pure field census over an already-mounted publication owner — see R9.
        ///
        /// 🧺️ A batched durable lane empties its emit vector the moment it is admitted, so the
        /// in-flight publication itself — not the drained vector — is what still owes a turn.
        fn mounted_typed_interaction_writes_are_next(mounted: &MountedTypedCommandFullOperation<A>) -> bool {
            let Some(ArtifactToolCompletionValue::Emit(Ok(emit), ephemeral)) = mounted.publication.as_ref() else {
                return false;
            };
            !emit.interaction_writes.is_empty()
                && mounted.pending_artifact_publication.is_none()
                && emit.artifact_mutations.is_empty()
                && emit.config_mutations.is_empty()
                && emit.draft_mutations.is_empty()
                && emit.child_emits.is_empty()
                && ephemeral.presence.is_empty()
                && ephemeral.transient.is_empty()
        }

        /// 🕹️ Publishes this operation's whole [`InteractionWrite`] lane as ONE unit through the same
        /// `apply_interaction_writes` single-writer path `dispatch_emit` uses — the retained-tool twin
        /// of that call. It is one unit rather than one-write-per-turn because a selection is a single
        /// state-machine transition per domain: draining it write-by-write would publish intermediate
        /// selections no user ever asked for. `MountedTypedCommandFullOperation` needs no extra field:
        /// the writes live in the retained emit until taken here, and the lane is only entered once
        /// every durable lane is drained (`mounted_typed_interaction_writes_are_next`).
        async fn publish_mounted_typed_interaction_unit(&mut self, mounted: &mut MountedTypedCommandFullOperation<A>) -> Result<(), Fault> {
            let Some(ArtifactToolCompletionValue::Emit(Ok(emit), _)) = mounted.publication.as_mut() else {
                return Err(plugin_sdk_fault("typed-operation interaction publication lost its emit owner"));
            };
            let writes = std::mem::take(&mut emit.interaction_writes);
            let meta = mounted.meta.clone();
            if let Err(fault) = self.apply_interaction_writes(&writes, &meta).await {
                if let Some(ArtifactToolCompletionValue::Emit(Ok(emit), _)) = mounted.publication.as_mut() {
                    emit.interaction_writes = writes;
                }
                return Err(fault);
            }
            let token = mounted.next_token();
            let page = TypedOperationResultPage::try_serialize(token, TypedOperationResultLane::Interaction, &("accepted", writes.len()))?;
            mounted.queue_page(page)
        }

        /// 🔀️ Whether this operation's next publication unit is the inline fold of its emit's
        /// guest-emitted interaction verbs (`Effect::ReplayShellCommand { action_id ∈
        /// INTERACTION_ACTION_IDS }` or `Effect::DispatchAction { action ∈ INTERACTION_ACTION_IDS }`,
        /// see [`is_inline_interaction_verb`]): every durable store lane is drained (a pick may only name ids
        /// the document already holds), the `InteractionWrite` lane went first (it precedes the verb
        /// in the emit's own order, exactly as it did when the verb still took a host round trip),
        /// and at least one such verb is still in the effect list. Sync and allocation-free like its
        /// `mounted_typed_interaction_writes_are_next` twin.
        /// 🚫️async: E1 pure field census over an already-mounted publication owner — see R9.
        ///
        /// 🅿️ The verbs were parked at install (`typed_inline_interaction_verbs`, keyed by this
        /// operation); the effect-list scan stays as the belt to that brace, for an emit whose
        /// effects were (re)filled after install.
        fn mounted_typed_inline_interaction_verbs_are_next(&self, mounted: &MountedTypedCommandFullOperation<A>) -> bool {
            let Some(ArtifactToolCompletionValue::Emit(Ok(emit), ephemeral)) = mounted.publication.as_ref() else {
                return false;
            };
            let parked = self.typed_inline_interaction_verbs.iter().any(|(operation, verbs)| *operation == mounted.operation.operation.0 && !verbs.is_empty());
            (parked || emit.effects.iter().any(is_inline_interaction_verb))
                && emit.interaction_writes.is_empty()
                && mounted.pending_artifact_publication.is_none()
                && emit.artifact_mutations.is_empty()
                && emit.config_mutations.is_empty()
                && emit.window_config_mutations.is_empty()
                && emit.draft_mutations.is_empty()
                && emit.child_emits.is_empty()
                && ephemeral.presence.is_empty()
                && ephemeral.transient.is_empty()
                && ephemeral.window_transient.is_empty()
        }

        /// 🔀️ Ticket 26/09/16/INPUT-CAUSALITY-LEDGER §2 C — the typed-operation twin of
        /// `dispatch_emit`'s inline interaction fold, for the ladder every app command
        /// (`dispatch_typed_command_inner`) and retained tool publishes through and that never enters
        /// `dispatch_emit`. Peels every interaction verb out of the retained emit's effect list as ONE
        /// unit (the same one-transition-per-domain reasoning as the `InteractionWrite` unit above),
        /// applies each through `apply_interaction_verb`, and widens the emit's `ui_scope` with the
        /// verbs' app-declared refresh scopes so the `Ui` page and the completion witness — published
        /// later in this same ladder — already carry them. No result page is queued: the host has
        /// nothing to acknowledge, because the verb it used to be asked to replay never leaves the
        /// reactor, and the ladder simply continues with the remaining effects next pump.
        ///
        /// 🩹 A verb that could not be applied is reported on the runtime's `[TRACE]` diagnostics line
        /// and dropped — the typed ladder has no `InvocationResult.diagnostics` lane (its only fault
        /// lane is terminal), and failing the carrying command for a pick that already happened is
        /// exactly what `fold_inline_interaction_verbs` exists to prevent.
        async fn publish_mounted_typed_inline_interaction_unit(&mut self, mounted: &mut MountedTypedCommandFullOperation<A>) -> Result<(), Fault> {
            let Some(ArtifactToolCompletionValue::Emit(Ok(emit), _)) = mounted.publication.as_mut() else {
                return Err(plugin_sdk_fault("typed-operation inline interaction publication lost its emit owner"));
            };
            let mut folded: Vec<(String, Option<DslValue>)> = Vec::new();
            if let Some(index) = self.typed_inline_interaction_verbs.iter().position(|(operation, _)| *operation == mounted.operation.operation.0) {
                folded = self.typed_inline_interaction_verbs.swap_remove(index).1;
            }
            folded.extend(take_inline_interaction_verbs(&mut emit.effects));
            let scope = emit.ui_scope.clone();
            let meta = mounted.meta.clone();
            let fold = self.fold_inline_interaction_verbs(&mounted.verb, folded, &meta, scope).await;
            let Some(ArtifactToolCompletionValue::Emit(Ok(emit), _)) = mounted.publication.as_mut() else {
                return Err(plugin_sdk_fault("typed-operation inline interaction publication lost its emit owner after the fold"));
            };
            emit.ui_scope = fold.scope;
            if let Some(view) = fold.leftover {
                self.typed_inline_interaction_leftover = Some(TypedOperationLeftover { operation: mounted.operation.operation.0, view });
            }
            for diagnostic in fold.diagnostics {
                crate::plugin_runtime::debug_runtime_line(format_args!("[TRACE] {} {}", diagnostic.code.0, diagnostic.message));
            }
            Ok(())
        }

        async fn advance_latest_wins_command_one(&mut self) -> Result<(), Fault> {
            let Some(operation_id) = self.latest_wins_order.items.front().copied() else { return Ok(()) };
            let mut pending = self.latest_wins_commands.remove(operation_id).expect("exact pending keyed command");
            let ready = match self.advance_latest_wins_admission_unit(&mut pending) {
                Ok(ready) => ready,
                Err(_) => {
                    pending.closing = true;
                    if let Some(lease) = pending.lease.as_ref() {
                        lease.cancel();
                    }
                    false
                }
            };
            let reserved = self.typed_operation_reservations[operation_id as usize % ARTIFACT_LIVE_OUTPUT_SLOTS] == Some(operation_id);
            if !reserved || !self.tool_operations.can_insert(operation_id) {
                pending.closing = true;
                pending.lease.as_ref().expect("pending slot rejection retains its cancellation lease").cancel();
                if !self.tool_operations.can_insert(operation_id) || self.typed_operation_reservations[operation_id as usize % ARTIFACT_LIVE_OUTPUT_SLOTS].is_some_and(|owner| owner != operation_id) {
                    self.latest_wins_commands.insert_admitted(operation_id, pending);
                    return Ok(());
                }
            }
            if ready && !pending.closing {
                let command = pending.command.take().expect("accepted latest-wins command owner");
                let admission = pending.admission.take().expect("accepted latest-wins exact raw admission");
                let lease = pending.lease.take().expect("accepted latest-wins cancellation lease");
                assert_eq!(self.latest_wins_order.pop(), Some(operation_id));
                let started = self.start_typed_command_operation(command, admission, &pending.meta, pending.operation.operation, Some(lease)).await;
                if started.is_err() {
                    self.typed_operation_reservations[operation_id as usize % ARTIFACT_LIVE_OUTPUT_SLOTS] = None;
                }
                started?;
                return Ok(());
            }
            if pending.closing && pending.command_owners_are_empty() {
                let mut mounted = MountedTypedCommandFullOperation::<A> {
                    verb: "latest-wins-admission".into(),
                    meta: pending.meta.clone(),
                    operation: pending.operation,
                    canonical_revision: pending.revision,
                    artifact_generation: pending.operation.generation.0,
                    config_generation: 0,
                    draft_generation: 0,
                    presence_generation: 0,
                    transient_generation: 0,
                    window_config_authority: None,
                    window_transient_authority: None,
                    publication_lanes: &[],
                    session: None,
                    session_rejected: None,
                    completion: None,
                    raw_input: None,
                    output_chunks: None,
                    cancellation_lease: pending.lease.take(),
                    terminal_outcome: None,
                    terminal_seen: true,
                    publication: None,
                    pending_artifact_publication: None,
                    pending_child_publication: None,
                    captured_child_content: Some(std::sync::Arc::new(ChildContentView::EMPTY)),
                    captured_child_content_generation: 0,
                    result_page: None,
                    result_page_presented: false,
                    result_sequence: 0,
                    publication_progress: 0,
                    publication_checkpoint: None,
                    publication_attempt: 0,
                    ui_pending: false,
                    progress: None,
                    progress_pending: false,
                    user_cancel_requested: false,
                    published_artifact: false,
                    published_config: false,
                    published_window_config: false,
                    command_logged: false,
                    interaction_revalidated: false,
                    terminal_fault: None,
                    stage: MountedTypedCommandFullOperationStage::Publishing,
                };
                mounted.queue_page(TypedOperationResultPage::try_new(mounted.next_token(), TypedOperationResultLane::Fault, b"latest-wins command admission cancelled or rejected before worker publication")?)?;
                self.tool_operations.insert_admitted(operation_id, mounted);
                self.typed_operation_reservations[operation_id as usize % ARTIFACT_LIVE_OUTPUT_SLOTS] = None;
                assert_eq!(self.latest_wins_order.pop(), Some(operation_id));
            } else {
                self.latest_wins_commands.insert_admitted(operation_id, pending);
            }
            Ok(())
        }

        /// 🔁️ ticket 26/09/02/PUZZLE-3D-END-TO-END wave B21: a rebase re-bases the LEASE, it does not
        /// change the key. The key is `(instance, envelope id, controller id, tool id, target)` — not one
        /// of which depends on the document revision or generation — so retiring it here only made the
        /// restart throw away an in-flight `ToolLatestWinsKeyCopy` one character per host continuation and
        /// rebuild it from scratch, several hundred round trips per rebase. And the registry's in-flight
        /// unit is driven here for ANY owner, not only for this one: `active_operation` is cleared solely
        /// by `ToolLatestWinsRegistry::advance`, and a sibling that was accepted and started leaves its
        /// closing update behind, so gating the drive on `active_operation == Some(operation)` let a
        /// restarting front-of-FIFO command wait forever on a registry no one would advance.
        fn advance_latest_wins_admission_unit(&mut self, pending: &mut PendingLatestWinsCommand<A>) -> Result<bool, Fault> {
            let operation = pending.operation.operation.0;
            if pending.lease.as_ref().is_none_or(|lease| lease.token.is_cancelled_now()) {
                pending.closing = true;
            }
            if pending.closing {
                self.latest_wins_keys.cancel(operation);
                self.latest_wins_keys.take_outcome(operation);
                if self.latest_wins_keys.active_operation == Some(operation) {
                    self.latest_wins_keys.advance(1, TYPED_OPERATION_RESULT_PAGE_BYTES);
                } else {
                    pending.close_step(1, TYPED_OPERATION_RESULT_PAGE_BYTES)?;
                }
                return Ok(false);
            }
            let live_revision = self.store.content_revision_now();
            if live_revision != pending.revision || self.store.generation_now() != pending.operation.generation.0 {
                pending.restarting = true;
            }
            if pending.restarting {
                self.latest_wins_keys.cancel(operation);
                self.latest_wins_keys.take_outcome(operation);
                if !self.latest_wins_keys.can_begin() {
                    self.latest_wins_keys.advance(1, TYPED_OPERATION_RESULT_PAGE_BYTES);
                    return Ok(false);
                }
                let base_revision = semio_framework_job::RevisionId(u64::from_be_bytes(live_revision[..8].try_into().expect("revision lane width")));
                let generation = semio_framework_job::Generation(self.store.generation_now());
                if !pending.lease.as_mut().expect("keyed rebase retains its exact lease").rebind_keyed(base_revision, generation)? {
                    return Ok(false);
                }
                pending.lookup_started = false;
                pending.accepted = false;
                pending.restarting = false;
                pending.revision = live_revision;
                pending.operation.base_revision = base_revision;
                pending.operation.generation = generation;
                return Ok(false);
            }
            if pending.accepted {
                return Ok(pending.close_key_step(1, TYPED_OPERATION_RESULT_PAGE_BYTES) == PluginCloseStep::Complete);
            }
            if pending.lookup_started {
                if let Some(accepted) = self.latest_wins_keys.take_outcome(operation) {
                    pending.accepted = accepted;
                    pending.closing = !accepted;
                    if !accepted {
                        pending.lease.as_ref().expect("live pending lease").cancel();
                    }
                } else {
                    self.latest_wins_keys.advance(1, TYPED_OPERATION_RESULT_PAGE_BYTES);
                }
                return Ok(false);
            }
            if let Some(key) = pending.key.as_ref() {
                if self.latest_wins_keys.begin(operation, key.clone(), pending.lease.as_ref().expect("live pending lease")) {
                    pending.lookup_started = true;
                } else {
                    self.latest_wins_keys.advance(1, TYPED_OPERATION_RESULT_PAGE_BYTES);
                }
                return Ok(false);
            }
            let admission = pending.admission.as_ref().expect("pending exact admission");
            let QualifiedToolProof::AppOwned(registration) = &admission.proof else {
                return Err(plugin_sdk_fault("latest-wins admission lost its concrete factory"));
            };
            let command = pending.command.as_ref().expect("pending exact command");
            let target = (registration.latest_wins_target)(command.as_ref()).ok_or_else(|| plugin_sdk_fault("latest-wins command lost its exact borrowed target"))?;
            let parts = [&*self.store.envelope().id, &*registration.key.controller_id, &*registration.key.tool_id, target];
            if pending.key_copy.is_none() {
                pending.key_copy = Some(ToolLatestWinsKeyCopy::new(pending.meta.instance_id, parts)?);
                return Ok(false);
            }
            let copy = pending.key_copy.as_mut().expect("retained exact key byte cursor");
            if copy.advance(parts, 1, TYPED_OPERATION_RESULT_PAGE_BYTES) == PluginCloseStep::Complete {
                pending.key = copy.take_key();
            }
            Ok(false)
        }

        /// 🧩️ The composed lane is PUBLISHED, not discarded: `dispatch_emit_group` has just
        /// built the parent's mutations, one per touched child under the child's own
        /// content-addressed handle, and the single `UndoGroup` that names them all. The
        /// three scalars of `receipt` are what the host ACKs; this is what the host READS.
        async fn publish_mounted_typed_child_operation_unit(&mut self, mounted: &mut MountedTypedCommandFullOperation<A>) -> Result<(), Fault> {
            let Some(mut pending) = mounted.pending_child_publication.take() else {
                return Err(plugin_sdk_fault("typed-operation child publication lost its retained owner"));
            };
            match pending.phase {
                PendingChildGroupPublicationPhase::Acknowledged | PendingChildGroupPublicationPhase::Closing => {
                    pending.begin_close();
                    let step = pending.close_step(1, TYPED_OPERATION_RESULT_PAGE_BYTES);
                    if step == PluginCloseStep::Complete {
                        if !pending.terminal_is_empty() {
                            mounted.pending_child_publication = Some(pending);
                            return Err(plugin_sdk_fault("typed-operation child publication closed without terminal emptiness"));
                        }
                    } else {
                        mounted.pending_child_publication = Some(pending);
                    }
                    return Ok(());
                }
                PendingChildGroupPublicationPhase::Committed => {
                    let receipt = pending.receipt.clone().ok_or_else(|| plugin_sdk_fault("committed child publication lost its exact result receipt"))?;
                    mounted.published_artifact = true;
                    self.record_typed_operation_lane(mounted, true);
                    mounted.pending_child_publication = Some(pending);
                    return mounted.queue_page(TypedOperationResultPage::try_serialize(mounted.next_token(), TypedOperationResultLane::Child, &receipt)?);
                }
                PendingChildGroupPublicationPhase::Faulted => {
                    let fault = pending.fault().unwrap_or_else(|| plugin_sdk_fault("typed-operation child publication fault lost its bounded detail"));
                    mounted.pending_child_publication = Some(pending);
                    return Err(fault);
                }
                PendingChildGroupPublicationPhase::Ready => {}
                PendingChildGroupPublicationPhase::Dispatching => {
                    mounted.pending_child_publication = Some(pending);
                    return Err(plugin_sdk_fault("typed-operation child publication re-entered a non-dispatchable phase"));
                }
            }
            match self.reclaim_child_retirements(1, 0) {
                Ok(true) => {}
                Ok(false) => {
                    mounted.pending_child_publication = Some(pending);
                    return Ok(());
                }
                Err(error) => {
                    let fault = pending.reject_and_fault(&error);
                    mounted.pending_child_publication = Some(pending);
                    return Err(fault);
                }
            }
            let Some(_permit) = mounted.cancellation_lease.as_ref().and_then(ToolCancellationLease::try_claim_publication) else {
                let fault = pending.reject_and_fault(&plugin_sdk_fault("typed-operation child publication claim is cancelled or occupied"));
                mounted.pending_child_publication = Some(pending);
                return Err(fault);
            };
            let live_revision = self.store.content_revision_now();
            let live_generation = self.store.generation_now();
            let Some(captured) = mounted.captured_child_content.as_ref() else {
                let fault = pending.reject_and_fault(&plugin_sdk_fault("typed-operation child publication lost its captured immutable root"));
                mounted.pending_child_publication = Some(pending);
                return Err(fault);
            };
            let parent_fresh = typed_operation_document_is_fresh(&mounted.operation, mounted.canonical_revision, live_revision, live_generation);
            let child_root_fresh = mounted.captured_child_content_generation == self.child_content_generation && captured.identity_digest() == self.child_content_root.identity_digest();
            if !parent_fresh || !child_root_fresh {
                let fault = pending.reject_and_fault(&plugin_sdk_fault("typed-operation child publication rejected stale parent or child immutable roots"));
                mounted.pending_child_publication = Some(pending);
                return Err(fault);
            }
            let mut seen = HashSet::with_capacity(pending.child_emits.len());
            for child in &pending.child_emits {
                if !seen.insert((child.slot.clone(), child.child_id.clone())) {
                    let fault = pending.reject_and_fault(&plugin_sdk_fault("typed-operation child publication contains a duplicate exact target"));
                    mounted.pending_child_publication = Some(pending);
                    return Err(fault);
                }
                let expected_revision = match captured.revision(&child.slot, &child.child_id) {
                    Ok(revision) => revision,
                    Err(error) => {
                        let fault = pending.reject_and_fault(&error);
                        mounted.pending_child_publication = Some(pending);
                        return Err(fault);
                    }
                };
                let Some(expected_dialect) = captured.dialect(&child.slot, &child.child_id) else {
                    let fault = pending.reject_and_fault(&plugin_sdk_fault("typed-operation child publication target is absent from its captured root"));
                    mounted.pending_child_publication = Some(pending);
                    return Err(fault);
                };
                let Some(entry) = self.children.get(&(child.slot.clone(), child.child_id.clone())) else {
                    let fault = pending.reject_and_fault(&plugin_sdk_fault("typed-operation child publication target is absent from the live member registry"));
                    mounted.pending_child_publication = Some(pending);
                    return Err(fault);
                };
                if entry.reference.dialect != expected_dialect || entry.member.content_revision().await != expected_revision {
                    let fault = pending.reject_and_fault(&plugin_sdk_fault("typed-operation child publication rejected stale member identity, dialect, or revision"));
                    mounted.pending_child_publication = Some(pending);
                    return Err(fault);
                }
            }
            if mounted.cancellation_lease.as_ref().expect("claimed child publication retains its cancellation lease").is_cancelled().await {
                let fault = pending.reject_and_fault(&plugin_sdk_fault("typed-operation child publication was cancelled before group linearization"));
                mounted.pending_child_publication = Some(pending);
                return Err(fault);
            }
            if let Err(error) = pending.begin_dispatch() {
                let fault = pending.reject_and_fault(&error);
                mounted.pending_child_publication = Some(pending);
                return Err(fault);
            }
            let result = self.dispatch_emit_group(&mounted.verb, &pending.artifact_mutations, &pending.child_emits, &pending.description, Vec::new(), Vec::new(), UiDirtyScope::None, None, &mounted.meta, None, pending.transaction.clone()).await;
            match result {
                Ok(result) => {
                    mounted.artifact_generation = self.store.generation_now();
                    mounted.canonical_revision = self.store.content_revision_now();
                    mounted.operation.base_revision = semio_framework_job::RevisionId(u64::from_be_bytes(mounted.canonical_revision[..8].try_into().expect("revision lane width")));
                    mounted.operation.generation = semio_framework_job::Generation(mounted.artifact_generation);
                    let receipt = ChildPublicationResultV1 { invocation_id: result.inverse_group.invocation_id.0.clone(), committed_members: result.inverse_group.member_edits.len(), child_content_generation: self.child_content_generation };
                    if self.typed_composed_outbox.push(ComposedGestureResult { operation: mounted.operation.operation.0, mutations: result.mutations, inverse_group: result.inverse_group }).is_err() {
                        let fault = pending.reject_and_fault(&plugin_sdk_fault("typed-operation composed gesture receiver is saturated"));
                        mounted.pending_child_publication = Some(pending);
                        return Err(fault);
                    }
                    if let Err(error) = pending.commit(receipt.clone()) {
                        let fault = pending.reject_and_fault(&error);
                        mounted.pending_child_publication = Some(pending);
                        return Err(fault);
                    }
                    mounted.pending_child_publication = Some(pending);
                    mounted.queue_page(TypedOperationResultPage::try_serialize(mounted.next_token(), TypedOperationResultLane::Child, &receipt)?)
                }
                Err(fault) => {
                    let fault = pending.reject_and_fault(&fault);
                    mounted.pending_child_publication = Some(pending);
                    Err(fault)
                }
            }
        }

        /// 🔀️ Ticket 26/09/16/INPUT-CAUSALITY-LEDGER §2 C — THE point the reactor first owns a
        /// typed command's emit. The interaction verbs are peeled here, before this same call
        /// can reach the effect lane below: an emit with no durable lane (fem2d's
        /// `canvasPointerUp` is `effects: [interactionSelect], ui_scope: partial` and nothing
        /// else) used to fall straight through to `emit.effects.pop()` → `typed_effect_outbox`
        /// on the install pump, while `mounted_typed_inline_interaction_verbs_are_next` had
        /// never seen the emit (it gates on `mounted.publication`, which was still `None`
        /// when this pump's ladder branch was chosen). Per-turn law: no host-visible turn of a
        /// typed operation ever carries one of the six interaction verbs as an effect.
        ///
        /// 🪜️ Hand the pump back to the ladder so its own lane order picks the first unit: the
        /// `InteractionWrite` lane and the inline fold both precede the effect/`Ui`/terminal
        /// pages of this same emit, and the fold must land BEFORE the `Ui` page is minted so
        /// that page already carries the verbs' widened scope and their leftover view.
        ///
        /// 🔒️ The three emit-time backstops of contract §2.3 clause 2, §5.10 and the tool-run
        /// freeze live in `dispatch_emit_inner`, which the migrated publication ladder never
        /// calls for the single-store artifact lane (FP5 §3.4 measured the same thing for the
        /// kind guard above). A migrated dispatch answers with an admission receipt and its
        /// mutations only exist HERE, so this is the only point at which they can be refused.
        ///
        /// 🔀️ Composite-mutation proposal (contract §5.1): apply NOTHING and stash a
        /// `TransactionProposalDraft` instead, drained once by `plugin_exchange`.
        ///
        /// 🧺️ ONE gesture is ONE batched publication: the whole artifact lane is drained
        /// into a single staged `Edit` (one history ledger slot, one undo step), instead
        /// of one edit per mutation per turn — see `store::begin_apply_batch`.
        ///
        /// 🧵️ `Emit::amend_config` on a retained route: the key folds this config
        /// snapshot into the last uncommitted edit under the same key, exactly as
        /// the artifact lane above and the non-retained `config:{key}` path do.
        /// Dropping it here appended one ledger item per pointer move / keystroke
        /// and saturated the 64-item config ledger within a few interactions.
        ///
        /// 🎚️ The authority was captured when this command was DISPATCHED, and a window's
        /// config partition is its OWN exact-base document: any earlier command that
        /// settled against the same window has already moved that partition's generation
        /// and revision on, so a second window-config command dispatched in the same turn
        /// carries a stale base by the time its batch begins. `begin_apply_batch` then
        /// refuses it — and because the mutation was already POPPED out of `emit`, the
        /// retry `advance_typed_operation_publication_unit` grants on a publication fault
        /// found nothing left to publish and the operation completed clean: no page, no
        /// fault, the amend lost (measured on flow as one window-config page for two
        /// commands, ticket 26/09/19 `📓️flow.md` §5.2). Two repairs, both of which every
        /// sibling lane of this ladder already had: re-read the authority before beginning
        /// (the window-TRANSIENT arm below always did), and hand the mutation BACK to
        /// `emit` when admission refuses it, so a retry is a real retry and an exhausted
        /// one refuses by name on the Fault lane instead of vanishing.
        ///
        /// 🧵️ MICROKERNEL-POOLED-ACTOR-PLUGIN-RUNTIME (design-abi.md §4) — the
        /// task lane, ONE task per publication unit. The unit spends itself here
        /// and hands the pump straight back to the ladder without a host page of
        /// its own: a spawn is actor-local bookkeeping, and the task's eventual
        /// `TaskResolution` re-enters as its own follow-up dispatch
        /// (`drain_task_resumes`), never as this operation's result. `remove(0)`
        /// because spawn order is observable — a same-key respawn cancels the
        /// live task under that key, so the LAST declared task under a key must
        /// be the one that survives. A refused spawn (quota, key supersession,
        /// executor capacity) is this operation's own `Fault`: the ladder above
        /// gives the slot a chance to free and then mints its terminal fault page.
        async fn publish_mounted_typed_operation_unit(&mut self, mounted: &mut MountedTypedCommandFullOperation<A>) -> Result<(), Fault> {
            if mounted.reject_cancelled_publication()? {
                return Ok(());
            }
            let _permit = mounted.cancellation_lease.as_ref().and_then(ToolCancellationLease::try_claim_publication).ok_or_else(|| plugin_sdk_fault("typed-operation publication claim is cancelled or occupied"))?;
            if mounted.publication.is_none() {
                let Some(completion) = mounted.completion.as_ref() else { return Err(plugin_sdk_fault("typed-operation completion owner was retired before publication")) };
                let Some(mut publication) = completion.take()? else { return Ok(()) };
                mounted.ui_pending = matches!(publication, ArtifactToolCompletionValue::Emit(Ok(_), _));
                self.settle_tool_operation(mounted, &mut publication)?;
                if let ArtifactToolCompletionValue::Emit(Ok(emit), _) = &mut publication {
                    let verbs = take_inline_interaction_verbs(&mut emit.effects);
                    if !verbs.is_empty() {
                        self.typed_inline_interaction_verbs.retain(|(operation, _)| *operation != mounted.operation.operation.0);
                        self.typed_inline_interaction_verbs.push((mounted.operation.operation.0, verbs));
                    }
                }
                mounted.publication = Some(publication);
                if Self::mounted_typed_interaction_writes_are_next(mounted) || self.mounted_typed_inline_interaction_verbs_are_next(mounted) {
                    return Ok(());
                }
            }
            let live_revision = self.store.content_revision_now();
            let live_generation = self.store.generation_now();
            if !typed_operation_document_is_fresh(&mounted.operation, mounted.canonical_revision, live_revision, live_generation) {
                let closed = if let Some(pending) = mounted.pending_artifact_publication.as_mut() {
                    pending.begin_close();
                    matches!(pending.close_step(1, TYPED_OPERATION_RESULT_PAGE_BYTES)?, store::SnapshotRetirementStep::Complete) && pending.terminal_is_empty()
                } else {
                    false
                };
                if closed {
                    mounted.pending_artifact_publication = None;
                }
                return Err(plugin_sdk_fault("typed-operation pending publication rejected a stale immutable document root"));
            }
            if let Some(pending) = mounted.pending_artifact_publication.as_mut() {
                let grant = store::ArtifactStoreOneItemGrant { maximum_items: 1, maximum_bytes: TYPED_OPERATION_RESULT_PAGE_BYTES };
                let (pending_lane, _) = pending.lane();
                if pending.is_closing() {
                    return match pending.retirement_turn(grant.maximum_items, grant.maximum_bytes)? {
                        PendingArtifactStorePublicationRetirement::Retiring => Ok(()),
                        PendingArtifactStorePublicationRetirement::Retired => {
                            mounted.pending_artifact_publication = None;
                            Ok(())
                        }
                        PendingArtifactStorePublicationRetirement::Rejected(fault) => {
                            mounted.pending_artifact_publication = None;
                            Err(fault)
                        }
                    };
                }
                if matches!(pending, PendingArtifactStorePublication::Artifact(_)) && !self.reclaim_document_snapshot_read_returns(PUBLICATION_SNAPSHOT_READ_RECLAIM_STEPS)? {
                    return Ok(());
                }
                let pending = mounted.pending_artifact_publication.as_mut().expect("pending publication checked above");
                let advance = match pending {
                    PendingArtifactStorePublication::Artifact(publication) => self.store.advance_apply_batch(publication, grant).map_err(store_publication_fault)?,
                    PendingArtifactStorePublication::Config(publication) => self.config_store.advance_apply_batch(publication, grant).map_err(|error| plugin_sdk_fault(error.to_string()))?,
                    PendingArtifactStorePublication::Draft(publication) => self.draft_store.advance_apply_batch(publication, grant).map_err(|error| plugin_sdk_fault(error.to_string()))?,
                    PendingArtifactStorePublication::Presence(publication) => self.presence_store.advance_publish_one(publication, grant).map_err(|error| plugin_sdk_fault(error.to_string()))?,
                    PendingArtifactStorePublication::Transient(publication) => self.transient_store.advance_publish_one(publication, grant).map_err(|error| plugin_sdk_fault(error.to_string()))?,
                    PendingArtifactStorePublication::WindowConfig(publication) => self.window_config_store.advance(publication.as_mut(), grant)?,
                    PendingArtifactStorePublication::WindowTransient(publication) => self.window_transient_store.advance(publication.as_mut(), grant)?,
                };
                return match advance {
                    store::ArtifactStoreOneItemAdvance::Published(receipt) => {
                        match pending_lane {
                            TypedOperationResultLane::Artifact => {
                                mounted.published_artifact = true;
                                self.record_typed_operation_lane(mounted, true);
                                mounted.artifact_generation = receipt.generation_after;
                                mounted.canonical_revision = self.store.content_revision_now();
                                mounted.operation.base_revision = semio_framework_job::RevisionId(u64::from_be_bytes(mounted.canonical_revision[..8].try_into().expect("revision lane width")));
                                mounted.operation.generation = semio_framework_job::Generation(receipt.generation_after);
                            }
                            TypedOperationResultLane::Config => {
                                mounted.published_config = true;
                                self.record_typed_operation_lane(mounted, false);
                                mounted.config_generation = receipt.generation_after;
                            }
                            TypedOperationResultLane::Draft => mounted.draft_generation = receipt.generation_after,
                            TypedOperationResultLane::Presence => mounted.presence_generation = receipt.generation_after,
                            TypedOperationResultLane::Transient => mounted.transient_generation = receipt.generation_after,
                            TypedOperationResultLane::WindowConfig => {
                                mounted.published_window_config = true;
                                let authority = mounted.window_config_authority.as_mut().ok_or_else(|| plugin_sdk_fault("window config receipt lost its captured window authority"))?;
                                self.window_config_store.refresh(authority)?;
                                self.tool_runs.note_window_config_published();
                            }
                            TypedOperationResultLane::WindowTransient => {
                                let authority = mounted.window_transient_authority.as_mut().ok_or_else(|| plugin_sdk_fault("window transient receipt lost its captured window authority"))?;
                                authority.generation = receipt.generation_after;
                            }
                            _ => unreachable!("pending artifact publication has one durable store lane"),
                        }
                        let token = mounted.next_token();
                        mounted.queue_page(TypedOperationResultPage::try_serialize(token, pending_lane, &receipt)?)
                    }
                    store::ArtifactStoreOneItemAdvance::Progress(checkpoint) => {
                        mounted.note_publication_checkpoint(checkpoint);
                        Ok(())
                    }
                    store::ArtifactStoreOneItemAdvance::Blocked => Ok(()),
                    store::ArtifactStoreOneItemAdvance::AwaitingAck(_) => Err(plugin_sdk_fault("artifact-store publication awaits an ACK without its retained host page")),
                    store::ArtifactStoreOneItemAdvance::Complete => Err(plugin_sdk_fault("artifact-store publication completed before result ACK")),
                };
            }
            let token = mounted.next_token();
            let publication_lanes = mounted.publication_lanes;
            let page = match mounted.publication.as_mut().expect("publication owner was installed") {
                ArtifactToolCompletionValue::Emit(Err(fault), _) | ArtifactToolCompletionValue::Download(Err(fault), _) => {
                    let mut framed = [0; TYPED_OPERATION_FAULT_PAGE_BYTES];
                    let len = fault.framed_page_bytes(&mut framed);
                    TypedOperationResultPage::try_new(token, TypedOperationResultLane::Fault, &framed[..len])?
                },
                ArtifactToolCompletionValue::Download(Ok(download), ephemeral) => {
                    if (!ephemeral.presence.is_empty() && !publication_lanes.contains(&ArtifactToolPublicationLane::Presence))
                        || (!ephemeral.transient.is_empty() && !publication_lanes.contains(&ArtifactToolPublicationLane::Transient))
                        || (!ephemeral.window_transient.is_empty() && !publication_lanes.contains(&ArtifactToolPublicationLane::WindowTransient))
                    {
                        return Err(plugin_sdk_fault("typed-operation emitted an undeclared ephemeral publication lane"));
                    }
                    if let Some(mutation) = ephemeral.presence.pop() {
                        match self.presence_store.begin_publish_one(mounted.operation.operation, mounted.presence_generation, mutation, self.presence_one_item_factory.as_deref(), self.presence_local_root_retirement_factory.clone()) {
                            Ok(publication) => {
                                mounted.pending_artifact_publication = Some(PendingArtifactStorePublication::Presence(publication));
                                return Ok(());
                            }
                            Err(rejected) => {
                                let (reason, mutation) = rejected.into_owners();
                                ephemeral.presence.push(mutation);
                                return Err(plugin_sdk_fault(reason));
                            }
                        }
                    } else if let Some(mutation) = ephemeral.transient.pop() {
                        match self.transient_store.begin_publish_one(mounted.operation.operation, mounted.transient_generation, mutation, self.transient_one_item_factory.as_deref(), self.transient_local_root_retirement_factory.clone()) {
                            Ok(publication) => {
                                mounted.pending_artifact_publication = Some(PendingArtifactStorePublication::Transient(publication));
                                return Ok(());
                            }
                            Err(rejected) => {
                                let (reason, mutation) = rejected.into_owners();
                                ephemeral.transient.push(mutation);
                                return Err(plugin_sdk_fault(reason));
                            }
                        }
                    } else if let Some(mutation) = ephemeral.window_transient.pop() {
                        let authority = match mounted.window_transient_authority.as_mut() {
                            Some(authority) => authority,
                            None => {
                                ephemeral.window_transient.push(mutation);
                                return Err(plugin_sdk_fault("window transient emission requires one exact captured ViewModel window authority"));
                            }
                        };
                        if let Err(fault) = self.window_transient_store.refresh(authority) {
                            ephemeral.window_transient.push(mutation);
                            return Err(fault);
                        }
                        match self.window_transient_store.begin(mounted.operation.operation, authority, mutation) {
                            Ok(publication) => {
                                mounted.pending_artifact_publication = Some(PendingArtifactStorePublication::WindowTransient(publication));
                                return Ok(());
                            }
                            Err(super::window_transient::RejectedWindowTransientEmission { mutation, fault }) => {
                                ephemeral.window_transient.push(mutation);
                                return Err(fault);
                            }
                        }
                    } else {
                        TypedOperationResultPage::try_serialize(
                            token,
                            TypedOperationResultLane::Download,
                            &DownloadResultPayload { filename: download.filename.as_str(), mime_type: download.mime_type.as_str(), encoding: download.encoding.as_deref(), bytes: download.chunks.bytes() },
                        )?
                    }
                }
                ArtifactToolCompletionValue::Emit(Ok(emit), ephemeral) => {
                    if (!emit.artifact_mutations.is_empty() && !publication_lanes.contains(&ArtifactToolPublicationLane::Artifact))
                        || (!emit.config_mutations.is_empty() && !publication_lanes.contains(&ArtifactToolPublicationLane::Config))
                        || (!emit.window_config_mutations.is_empty() && !publication_lanes.contains(&ArtifactToolPublicationLane::WindowConfig))
                        || (!emit.draft_mutations.is_empty() && !publication_lanes.contains(&ArtifactToolPublicationLane::Draft))
                        || (!ephemeral.presence.is_empty() && !publication_lanes.contains(&ArtifactToolPublicationLane::Presence))
                        || (!ephemeral.transient.is_empty() && !publication_lanes.contains(&ArtifactToolPublicationLane::Transient))
                        || (!ephemeral.window_transient.is_empty() && !publication_lanes.contains(&ArtifactToolPublicationLane::WindowTransient))
                        || (!emit.child_emits.is_empty() && !publication_lanes.contains(&ArtifactToolPublicationLane::Child))
                        || (!emit.interaction_writes.is_empty() && !publication_lanes.contains(&ArtifactToolPublicationLane::Interaction))
                    {
                        return Err(plugin_sdk_fault("typed-operation emitted a store lane absent from its exact factory publication contract"));
                    }
                    if !emit.artifact_mutations.is_empty() {
                        self.require_operation_emitting_kind(&mounted.verb, self.declared_dispatch_kind(&mounted.verb))?;
                        if A::ROLE == AppRole::Viewer {
                            return Err(viewer_read_only_fault(&mounted.verb));
                        }
                        if self.tool_runs.freezes_local_emits() {
                            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("toolRun.busy"), format!("verb {:?} would emit artifact mutations while a freezing tool run is non-terminal on this instance", mounted.verb)));
                        }
                        if let Some(pending_txn_id) = self.pending_transaction.as_ref().map(|pending| pending.txn_id.clone()) {
                            return Err(Self::transaction_fault(FaultOrigin::Plugin, "transaction.instance-busy", format!("verb {:?} would emit artifact mutations while transaction {pending_txn_id:?} is pending on this instance", mounted.verb)));
                        }
                        if emit.artifact_mutations.iter().any(Mutation::may_emit_foreign_steps) {
                            let mut running = self.store.snapshot().map_err(|error| error.into_fault())?;
                            let mut foreign = Vec::new();
                            for op in emit.artifact_mutations.iter() {
                                foreign.extend(op.foreign_steps(&running));
                                let outcome = op.diff(&running);
                                if !outcome.is_applicable(protocol::MergePolicy::default()) {
                                    return Err(Self::transaction_fault(FaultOrigin::App, "transaction.member-rejected", format!("mutation outcome was rejected: {:?}", outcome.messages())));
                                }
                                running = outcome.diff().apply(&running).map_err(|error| Self::transaction_fault(FaultOrigin::App, "transaction.member-rejected", error.to_string()))?;
                            }
                            if !foreign.is_empty() {
                                let mut local_ops = Vec::with_capacity(emit.artifact_mutations.len());
                                for op in emit.artifact_mutations.iter() {
                                    local_ops.push(::protocol::OpBinary::encode_op(op).unwrap_or_default());
                                }
                                self.pending_transaction_proposal = Some(TransactionProposalDraft { local_ops, description: emit.description.clone().unwrap_or_default(), coalesce_key: emit.coalesce_key.clone().unwrap_or_default(), foreign });
                                emit.artifact_mutations.clear();
                                emit.description = None;
                                emit.coalesce_key = None;
                                return Ok(());
                            }
                        }
                    }
                    if let Some(fault) = tool_transaction_shape_fault(&mounted.verb, emit.transaction.as_ref(), emit.transaction_phase, !emit.child_emits.is_empty(), !emit.artifact_mutations.is_empty(), emit.artifact_mutations.iter().any(Mutation::may_emit_foreign_steps)) {
                        return Err(fault);
                    }
                    if (!emit.artifact_mutations.is_empty() || !emit.child_emits.is_empty()) && self.time_travel.freezes_local_emits() {
                        return Err(time_travel_frozen_fault(&mounted.verb));
                    }
                    self.close_streamed_transaction_unit(emit)?;
                    if emit.child_emits.is_empty() && !emit.artifact_mutations.is_empty() {
                        if let Some(fault) = self.open_transaction_admission_fault(emit.transaction.as_ref()) {
                            return Err(fault);
                        }
                        let streams = emit.transaction_phase == TransactionPhase::Stream;
                        let mutations = std::mem::take(&mut emit.artifact_mutations);
                        let description = emit.description.take();
                        let transaction = emit.transaction.take();
                        let publication_result = if self.store.backbone_ref().is_some() {
                            self.store.begin_outbound_apply_batch(mounted.operation.operation, mounted.artifact_generation, mounted.canonical_revision, mounted.meta.actor.clone(), mutations, description, self.artifact_one_item_factory.as_ref(), transaction)
                        } else {
                            self.store.begin_apply_batch(
                                mounted.operation.operation,
                                mounted.artifact_generation,
                                mounted.canonical_revision,
                                mounted.meta.actor.clone(),
                                mutations,
                                description,
                                HistoryLane::Document,
                                self.artifact_one_item_factory.as_ref(),
                                transaction,
                            )
                        };
                        match publication_result {
                            Ok(mut publication) => {
                                publication.set_transaction_open(streams);
                                publication.set_verb(Some(mounted.verb.clone()));
                                mounted.pending_artifact_publication = Some(PendingArtifactStorePublication::Artifact(publication));
                                return Ok(());
                            }
                            Err(rejected) => {
                                let (reason, mutations, description) = rejected.into_owners();
                                emit.artifact_mutations = mutations;
                                emit.description = description;
                                return Err(plugin_sdk_fault(reason));
                            }
                        }
                    }
                    if !emit.config_mutations.is_empty() {
                        let revision = self.config_store.content_revision_now();
                        match self.config_store.begin_apply_batch(
                            mounted.operation.operation,
                            mounted.config_generation,
                            revision,
                            mounted.meta.actor.clone(),
                            std::mem::take(&mut emit.config_mutations),
                            None,
                            HistoryLane::Document,
                            self.config_one_item_factory.as_ref(),
                            None,
                        ) {
                            Ok(mut publication) => {
                                publication.set_coalesce_key(emit.coalesce_key.clone());
                                publication.set_verb(Some(mounted.verb.clone()));
                                mounted.pending_artifact_publication = Some(PendingArtifactStorePublication::Config(publication));
                                return Ok(());
                            }
                            Err(rejected) => {
                                let (reason, mutations, _) = rejected.into_owners();
                                emit.config_mutations = mutations;
                                return Err(plugin_sdk_fault(reason));
                            }
                        }
                    } else if let Some(mutation) = emit.window_config_mutations.pop() {
                        let authority = mounted.window_config_authority.as_mut().ok_or_else(|| plugin_sdk_fault("window config emission requires one exact captured ViewModel window authority"))?;
                        self.window_config_store.refresh(authority)?;
                        let authority = mounted.window_config_authority.as_ref().expect("refreshed window config authority remains captured");
                        match self.window_config_store.begin(mounted.operation.operation, mounted.meta.actor.clone(), authority, mutation, emit.coalesce_key.as_deref()) {
                            Ok(publication) => {
                                mounted.pending_artifact_publication = Some(PendingArtifactStorePublication::WindowConfig(publication));
                                return Ok(());
                            }
                            Err(RejectedWindowConfigEmission { mutation, fault }) => {
                                emit.window_config_mutations.push(mutation);
                                return Err(fault);
                            }
                        }
                    } else if !emit.draft_mutations.is_empty() {
                        let revision = self.draft_store.content_revision_now();
                        match self.draft_store.begin_apply_batch(
                            mounted.operation.operation,
                            mounted.draft_generation,
                            revision,
                            mounted.meta.actor.clone(),
                            std::mem::take(&mut emit.draft_mutations),
                            None,
                            HistoryLane::Document,
                            self.draft_one_item_factory.as_ref(),
                            None,
                        ) {
                            Ok(publication) => {
                                mounted.pending_artifact_publication = Some(PendingArtifactStorePublication::Draft(publication));
                                return Ok(());
                            }
                            Err(rejected) => {
                                let (reason, mutations, _) = rejected.into_owners();
                                emit.draft_mutations = mutations;
                                return Err(plugin_sdk_fault(reason));
                            }
                        }
                    } else if let Some(mutation) = ephemeral.presence.pop() {
                        match self.presence_store.begin_publish_one(mounted.operation.operation, mounted.presence_generation, mutation, self.presence_one_item_factory.as_deref(), self.presence_local_root_retirement_factory.clone()) {
                            Ok(publication) => {
                                mounted.pending_artifact_publication = Some(PendingArtifactStorePublication::Presence(publication));
                                return Ok(());
                            }
                            Err(rejected) => {
                                let (reason, mutation) = rejected.into_owners();
                                ephemeral.presence.push(mutation);
                                return Err(plugin_sdk_fault(reason));
                            }
                        }
                    } else if let Some(mutation) = ephemeral.transient.pop() {
                        match self.transient_store.begin_publish_one(mounted.operation.operation, mounted.transient_generation, mutation, self.transient_one_item_factory.as_deref(), self.transient_local_root_retirement_factory.clone()) {
                            Ok(publication) => {
                                mounted.pending_artifact_publication = Some(PendingArtifactStorePublication::Transient(publication));
                                return Ok(());
                            }
                            Err(rejected) => {
                                let (reason, mutation) = rejected.into_owners();
                                ephemeral.transient.push(mutation);
                                return Err(plugin_sdk_fault(reason));
                            }
                        }
                    } else if let Some(mutation) = ephemeral.window_transient.pop() {
                        let authority = match mounted.window_transient_authority.as_mut() {
                            Some(authority) => authority,
                            None => {
                                ephemeral.window_transient.push(mutation);
                                return Err(plugin_sdk_fault("window transient emission requires one exact captured ViewModel window authority"));
                            }
                        };
                        if let Err(fault) = self.window_transient_store.refresh(authority) {
                            ephemeral.window_transient.push(mutation);
                            return Err(fault);
                        }
                        match self.window_transient_store.begin(mounted.operation.operation, authority, mutation) {
                            Ok(publication) => {
                                mounted.pending_artifact_publication = Some(PendingArtifactStorePublication::WindowTransient(publication));
                                return Ok(());
                            }
                            Err(super::window_transient::RejectedWindowTransientEmission { mutation, fault }) => {
                                ephemeral.window_transient.push(mutation);
                                return Err(fault);
                            }
                        }
                    } else if !emit.child_emits.is_empty() {
                        if mounted.pending_child_publication.is_some() {
                            return Err(plugin_sdk_fault("typed-operation retained more than one child-group publication owner"));
                        }
                        mounted.pending_child_publication = Some(PendingChildGroupPublication::new(std::mem::take(&mut emit.artifact_mutations), std::mem::take(&mut emit.child_emits), emit.description.take(), emit.transaction.take())?);
                        return Ok(());
                    } else {
                        Self::mint_extension_invocations(mounted.meta.instance_id, emit)?;
                        if let Some(effect) = emit.effects.pop() {
                            let effect = self.stamp_load_document_identity(effect)?;
                            if let Err(effect) = self.typed_effect_outbox.push(effect) {
                                emit.effects.push(effect);
                                return Err(plugin_sdk_fault("typed-operation effect receiver is saturated"));
                            }
                            TypedOperationResultPage::try_serialize(token, TypedOperationResultLane::Effect, &("accepted", self.typed_effect_outbox.len()))?
                        } else if let Some(event) = emit.events.pop() {
                            if let Err(event) = self.typed_event_outbox.push(event) {
                                emit.events.push(event);
                                return Err(plugin_sdk_fault("typed-operation event receiver is saturated"));
                            }
                            TypedOperationResultPage::try_serialize(token, TypedOperationResultLane::Event, &("accepted", self.typed_event_outbox.len()))?
                        } else {
                            match () {
                                () if !emit.tasks.is_empty() => {
                                    let task = emit.tasks.remove(0);
                                    crate::reactor::spawn_task(mounted.meta.instance_id, &mounted.meta, task).await?;
                                    return Ok(());
                                }
                                () if mounted.ui_pending => {
                                    if let Err(_scope) = self.typed_ui_outbox.push(emit.ui_scope.clone()) {
                                        return Err(plugin_sdk_fault("typed-operation UI receiver is saturated"));
                                    }
                                    mounted.ui_pending = false;
                                    TypedOperationResultPage::try_serialize(token, TypedOperationResultLane::Ui, &emit.ui_scope)?
                                }
                                () => {
                                    if self.typed_completion_outbox.push(TypedOperationCompletionWitness { operation: token.operation, ui_scope: emit.ui_scope.clone() }).is_err() {
                                        return Err(plugin_sdk_fault("typed-operation completion receiver is saturated"));
                                    }
                                    TypedOperationResultPage::try_new(token, TypedOperationResultLane::Terminal, b"typed-operation-complete")?
                                }
                            }
                        }
                    }
                }
            };
            mounted.queue_page(page)
        }

        fn require_tool_operation_authority(&self, admission: &AdmittedToolCommand) -> Result<(), Fault> {
            let contract = admission.proof.contract();
            let exact = admission.decoded_items <= contract.max_decoded_items
                && contract.max_work_units_per_step != 0
                && contract.max_output_bytes != 0
                && contract.max_step_micros != 0
                && contract.max_step_micros < semio_framework::ToolExecutionContract::INTERACTIVE_MAX_STEP_MICROS
                && matches!(contract.cancellation, semio_framework::ToolCancellationPolicy::PerOperation)
                && matches!(contract.freshness, semio_framework::ToolFreshnessPolicy::ValidateImmediatelyBeforeExposure)
                && matches!(contract.shape, semio_framework::ToolExecutionShape::Resumable | semio_framework::ToolExecutionShape::BoundedFirstStep);
            if !exact {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.incomplete-operation-authority"), format!("typed command '{}' has no complete bounded prepare/reducer/commit authority", admission.verb)));
            }
            Ok(())
        }

        fn require_complete_tool_operation_pipeline(&self, admission: &AdmittedToolCommand) -> Result<(), Fault> {
            self.require_tool_operation_authority(admission)?;
            match admission.proof {
                QualifiedToolProof::AppOwned(_) => Ok(()),
                QualifiedToolProof::FrameworkOwned(_) | QualifiedToolProof::Bounded(_) => {
                    Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.missing-owned-reducer"), format!("typed command '{}' has no exact app-owned retained decoder/reducer factory", admission.verb)))
                }
            }
        }

        fn can_admit_typed_operation(&self, operation: u64) -> bool {
            self.tool_operations.can_insert(operation) && self.typed_operation_reservations[operation as usize % ARTIFACT_LIVE_OUTPUT_SLOTS].is_none()
        }

        /// 🎰️ Whether every fixed typed-operation and segmented-output authority owns nothing in this one
        /// residue class of `id % ARTIFACT_LIVE_OUTPUT_SLOTS`.
        fn typed_operation_slot_is_vacant(&self, slot: usize) -> bool {
            self.tool_operations.slot_is_vacant(slot)
                && self.typed_operation_reservations[slot].is_none()
                && self.latest_wins_commands.slot_is_vacant(slot)
                && self.segmented_downloads.slot_is_vacant(slot)
                && self.segmented_closures.slot_is_vacant(slot)
        }

        /// 🎰️ How many of the fixed residue classes currently own a live typed operation or segmented
        /// output — the exact complement of what [`Self::admit_typed_operation_slot`] can still hand out,
        /// so `0` is the only value that proves every admitted slot reached its release path.
        fn live_typed_operation_slots(&self) -> usize {
            (0..ARTIFACT_LIVE_OUTPUT_SLOTS).filter(|slot| !self.typed_operation_slot_is_vacant(*slot)).count()
        }

        /// 🎫️ Pre-admits the exact operation slot BEFORE an operation id exists. Every typed authority is a
        /// direct-mapped table addressed by `id % ARTIFACT_LIVE_OUTPUT_SLOTS`, so minting a shared-counter id
        /// first and then testing its one residue class refuses an action whenever an unrelated live
        /// operation happens to share that class — a hover/tick/camera storm then fails while 63 slots sit
        /// empty. Ingress therefore chooses the vacant slot and mints the id for it, and refusal now means
        /// actual saturation of all fixed slots.
        fn admit_typed_operation_slot(&self) -> Option<semio_framework_job::OperationId> {
            if !self.latest_wins_order.allocation_admitted || self.latest_wins_order.len() >= ARTIFACT_LIVE_OUTPUT_SLOTS {
                return None;
            }
            let slot = (0..ARTIFACT_LIVE_OUTPUT_SLOTS).find(|slot| self.typed_operation_slot_is_vacant(*slot))?;
            Some(semio_framework_job::allocate_operation_id_in_slot(ARTIFACT_LIVE_OUTPUT_SLOTS as u64, slot as u64))
        }

        async fn dispatch_typed_command_inner(&mut self, command: Box<A::Command>, admission: AdmittedToolCommand, meta: &ActionMeta) -> Result<InvocationResult, Fault> {
            if self.live_runtime_instance_id != Some(meta.instance_id) {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.live-instance"), format!("typed command '{}' does not belong to the mounted live app instance", admission.verb)));
            }
            self.require_complete_tool_operation_pipeline(&admission)?;
            self.deliver_utility_host_events(meta).await?;
            let verb = A::command_id(&command).await.to_string();
            if admission.verb != verb {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.command-identity"), format!("exact admitted command '{}' decoded as '{verb}'", admission.verb)));
            }
            let Some(operation_id) = self.admit_typed_operation_slot() else {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.typed-operation-capacity"), "every fixed typed-operation and segmented-output slot already owns a live operation"));
            };
            if self.delivering_host_event {
                self.host_event_operations.insert(operation_id.0);
            }
            if let Some(tag) = self.tool_machines.ingress.take() {
                self.tool_machines.bind(operation_id.0, tag);
            }
            if let QualifiedToolProof::AppOwned(registration) = &admission.proof {
                if let Some(target) = (registration.latest_wins_target)(command.as_ref()) {
                    let disposer = (registration.latest_wins_command_disposer)()
                        .and_then(|owner| owner.downcast::<Box<dyn ArtifactOwnedDisposer<A::Command>>>().ok())
                        .map(|owner| *owner)
                        .ok_or_else(|| plugin_sdk_fault("latest-wins target requires its exact compiler-owned command retirement factory"))?;
                    let revision = self.store.content_revision_now();
                    let generation = semio_framework_job::Generation(self.store.generation_now());
                    let base_revision = semio_framework_job::RevisionId(u64::from_be_bytes(revision[..8].try_into().expect("revision lane width")));
                    let operation = semio_framework_job::Operation::new(operation_id, base_revision, generation, operation_id.0);
                    let key = ToolLatestWinsKeyCopy::new(meta.instance_id, [&self.store.envelope().id, &registration.key.controller_id, &registration.key.tool_id, target])?;
                    let lease = self.tool_cancellations.begin_keyed(ToolOperationKey { app_instance_id: meta.instance_id, document: ArtifactDocumentAuthority(meta.instance_id), operation_id, base_revision, generation })?;
                    self.typed_operation_reservations[operation_id.0 as usize % ARTIFACT_LIVE_OUTPUT_SLOTS] = Some(operation_id.0);
                    self.latest_wins_commands.insert_admitted(
                        operation_id.0,
                        PendingLatestWinsCommand {
                            command: std::mem::ManuallyDrop::new(Some(command)),
                            disposer,
                            admission: Some(admission),
                            meta: meta.clone(),
                            operation,
                            revision,
                            lease: Some(lease),
                            key_copy: Some(key),
                            key: None,
                            retired_key: None,
                            lookup_started: false,
                            accepted: false,
                            restarting: false,
                            closing: false,
                        },
                    );
                    self.latest_wins_order.push(operation_id.0).expect("exact FIFO command slot was pre-admitted");
                    let mut started = Self::empty_result(&verb, meta, Vec::new(), Vec::new(), UiDirtyScope::None).await;
                    started.output = DslValue::Object(vec![("operationId".into(), DslValue::String(operation_id.0.to_string())), ("generation".into(), DslValue::String(generation.0.to_string()))]);
                    return Ok(started);
                }
            }
            self.start_typed_command_operation(command, admission, meta, operation_id, None).await
        }

        /// 📸️ The roots one typed command runs against, captured once and identically for the shell lane
        /// that mounts the operation ([`Self::start_typed_command_operation`]) and for the agent lane's prepare
        /// phase that only previews it ([`Self::preview_addressed_action`]) — so the two lanes can never run
        /// the same verb against different state.
        async fn capture_typed_command_roots(&mut self, command: &A::Command, meta: &ActionMeta) -> Result<TypedCommandRoots<A>, Fault> {
            self.refresh_cache().await?;
            let (snapshot, config, history) = self.command_cache_inputs();
            let canonical_base_revision = self.store.content_revision();
            let window_config_authority = self.window_config_store.capture(meta.view_state.as_ref()).await?;
            let targeted_window_transient_view = match A::retained_window_transient_target(command) {
                Some((window_id, expected_kind)) => {
                    let view = meta.view_state.as_ref().ok_or_else(|| plugin_sdk_fault("targeted window transient capture requires an exact ViewModel roster"))?;
                    let window = view.window_instances.iter().find(|window| window.id == window_id).ok_or_else(|| plugin_sdk_fault("targeted window transient capture requires an attached window instance"))?;
                    if window.window_kind_id != expected_kind {
                        return Err(plugin_sdk_fault("targeted window transient capture does not match the command owner's expected window kind"));
                    }
                    Some(view.for_window_instance(window_id).ok_or_else(|| plugin_sdk_fault("targeted window transient capture lost its attached window instance"))?)
                }
                None => None,
            };
            let window_transient_authority = self.window_transient_store.capture(targeted_window_transient_view.as_ref().or(meta.view_state.as_ref()))?;
            Ok(TypedCommandRoots {
                snapshot,
                config,
                history,
                children: std::sync::Arc::new(ChildContentView::clone(&self.child_content_root)),
                draft_snapshot: self.draft_store.snapshot_root(),
                interaction_state: self.interaction_store.snapshot_root(),
                interaction_hover: self.interaction_hover.clone(),
                presence_peers: self.presence_store.peers_root(),
                transient: self.transient_store.current_root(),
                peer_presence: std::sync::Arc::clone(&self.peer_presence),
                canonical_base_revision,
                base_revision: semio_framework_job::RevisionId(u64::from_be_bytes(canonical_base_revision[..8].try_into().expect("revision lane width"))),
                generation: semio_framework_job::Generation(self.store.generation()),
                config_generation: self.config_store.generation(),
                draft_generation: self.draft_store.generation(),
                presence_generation: self.presence_store.generation().await,
                transient_generation: self.transient_store.generation().await,
                window_config_authority,
                window_transient_authority,
            })
        }

        /// 🧪️ Observes actual capture authority without exposing production dispatch preparation.
        #[cfg(test)]
        pub(crate) async fn test_capture_presence_roots(&mut self, command: &A::Command, meta: &ActionMeta) -> Result<(std::sync::Arc<PeerPresenceRoot>, std::sync::Arc<store::PresencePeersRoot<A::Presence>>), Fault> {
            let TypedCommandRoots { peer_presence, presence_peers, .. } = self.capture_typed_command_roots(command, meta).await?;
            Ok((peer_presence, presence_peers))
        }

        /// 🧪️ Mounts an exact typed admission so laws can observe the boundary before producer completion.
        #[cfg(test)]
        pub(crate) async fn test_mount_typed_command(&mut self, command: A::Command, verb: &str, meta: &ActionMeta) -> Result<InvocationResult, Fault> {
            let payload = ::protocol::OpBinary::encode_op(&command).map_err(|error| error.into_fault())?;
            let admission = self.admit_command_wire(verb, &payload, 1).await?;
            self.dispatch_typed_command_inner(Box::new(command), admission, meta).await
        }

        /// 🧵️ Captures immutable roots and mounts one admitted worker turn. Ephemeral producers
        /// execute inside their app-owned job and publish through its declared completion lanes.
        async fn start_typed_command_operation(
            &mut self,
            command: Box<A::Command>,
            admission: AdmittedToolCommand,
            meta: &ActionMeta,
            operation_id: semio_framework_job::OperationId,
            reserved_lease: Option<ToolCancellationLease>,
        ) -> Result<InvocationResult, Fault> {
            assert!(self.tool_operations.can_insert(operation_id.0), "typed worker handoff retains its exact empty operation slot");
            if reserved_lease.is_some() {
                assert_eq!(self.typed_operation_reservations[operation_id.0 as usize % ARTIFACT_LIVE_OUTPUT_SLOTS], Some(operation_id.0), "keyed worker handoff owns its exact pending reservation");
            } else {
                assert!(self.can_admit_typed_operation(operation_id.0), "ordinary worker cannot consume another pending operation reservation");
            }
            let verb = admission.verb.clone();
            let TypedCommandRoots {
                snapshot,
                config,
                history,
                children,
                draft_snapshot,
                interaction_state,
                interaction_hover,
                presence_peers,
                transient,
                peer_presence,
                canonical_base_revision,
                base_revision,
                generation,
                config_generation,
                draft_generation,
                presence_generation,
                transient_generation,
                window_config_authority,
                window_transient_authority,
            } = self.capture_typed_command_roots(command.as_ref(), meta).await?;
            let parent_document_id = self.store.envelope().id.clone();
            let seed_handle = artifact_handle_of(&format!("{}/{}/{verb}/{}", meta.instance_id, self.tool_job_controller_id, base_revision.0)).await;
            let operation = semio_framework_job::Operation::new(operation_id, base_revision, generation, (seed_handle.0 as u64) ^ ((seed_handle.0 >> 64) as u64));
            let operation_key = ToolOperationKey { app_instance_id: meta.instance_id, document: ArtifactDocumentAuthority(meta.instance_id), operation_id, base_revision, generation };
            let cancellation_lease = match reserved_lease {
                Some(lease) => lease,
                None => self.tool_cancellations.begin_keyed(operation_key)?,
            };
            assert_eq!(cancellation_lease.key.base_revision, base_revision, "fresh worker receives a revision-rebound cancellation lease");
            assert_eq!(cancellation_lease.key.generation, generation, "fresh worker receives a generation-rebound cancellation lease");
            let payload_schema_id = admission.proof.schema_id();
            let qualified_key = admission.proof.key();
            let publication_lanes = admission.proof.publication_lanes();
            let completion = ArtifactToolCompletion::<A>::new();
            let retained_wire_admission = admission.wire_admission.clone();
            let app_owned_retained_route = matches!(&admission.proof, QualifiedToolProof::AppOwned(_));
            let mut retained_wire = Some(admission.raw_wire);
            let raw_input = if app_owned_retained_route { ArtifactToolRawInput::transferred_to_factory() } else { ArtifactToolRawInput::new(retained_wire.take().expect("generic retained wire owner remains mounted")) };
            let output_chunks = ArtifactOutputChunks::new(admission.proof.contract().max_output_bytes);
            let owned_context = std::sync::Arc::new(
                ArtifactOwnedToolJobContext::new(
                    meta.instance_id,
                    meta.view_state.clone(),
                    canonical_base_revision,
                    draft_generation,
                    transient_generation,
                    ArtifactOwnedToolJobSnapshots {
                        children: std::sync::Arc::clone(&children),
                        draft: std::sync::Arc::clone(&draft_snapshot),
                        transient: std::sync::Arc::clone(&transient),
                        window_config: window_config_authority.as_ref().map(|authority| authority.snapshot.clone()),
                        window_transient: window_transient_authority.as_ref().map(|authority| authority.snapshot.clone()),
                    },
                )
                .with_presence(self.presence_store.local_read().map_err(Fault::from)?, std::sync::Arc::clone(&presence_peers))
                .with_tool_run(self.tool_runs.view_for(meta.view_state.as_ref().and_then(|view| view.window_id.as_deref())))
                .with_provisional(self.tool_machines.provisional_values(), self.tool_machines.provisional_generation()),
            );
            let operation_spec = match admission.proof.clone() {
                QualifiedToolProof::Bounded(_) => {
                    let job = TypedCommandFullOperationJob::<A> {
                        operation: None,
                        parent_document_id: Some(parent_document_id.clone()),
                        command: Some(std::sync::Arc::from(command)),
                        snapshot: Some(snapshot),
                        config: Some(config),
                        history: Some(history),
                        children: Some(std::sync::Arc::clone(&children)),
                        draft: Some(draft_snapshot),
                        interaction_state: Some(interaction_state),
                        interaction_hover: Some(std::sync::Arc::new(interaction_hover)),
                        peer_presence: Some(peer_presence),
                        presence_local: Some(self.presence_store.local_read().map_err(Fault::from)?),
                        presence_peers: Some(presence_peers),
                        transient: Some(transient),
                        contract: admission.proof.contract(),
                        decoded_items: admission.decoded_items,
                        phase: TypedCommandFullOperationPhase::Prepare,
                        prepare_cursor: 0,
                        reducer_cursor: 0,
                        output: Some(completion.clone()),
                        closing: false,
                    };
                    semio_framework::ToolOperationSpec::new(self.tool_job_controller_id.clone(), verb.clone(), payload_schema_id, job, operation)
                }
                QualifiedToolProof::AppOwned(_) => A::build_tool_job(ArtifactOwnedToolJobRequest {
                    command,
                    raw_wire: raw_input.clone(),
                    operation,
                    controller_id: qualified_key.controller_id,
                    tool_id: qualified_key.tool_id,
                    payload_schema_id,
                    contract: admission.proof.contract(),
                    decoded_items: admission.decoded_items,
                    app_instance_id: meta.instance_id,
                    parent_document_id,
                    canonical_base_revision,
                    authoring_seed: self.authoring_seed(&meta.actor),
                    snapshot,
                    config,
                    window_config: window_config_authority.as_ref().map(|authority| authority.snapshot.clone()),
                    history,
                    interaction_state,
                    interaction_hover: std::sync::Arc::new(interaction_hover),
                    context: owned_context,
                    instance_operation_owner: self.instance_operation_owner.clone(),
                    output_chunks: output_chunks.clone(),
                    completion: completion.clone(),
                })
                .await?
                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.missing-owned-builder"), format!("app-owned tool '{verb}' registered a factory but supplied no exact payload builder")))?,
                QualifiedToolProof::FrameworkOwned(_) => {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.framework-route"), format!("framework-owned tool '{verb}' cannot enter the application typed-command reducer")));
                }
            };
            let dispatch = if app_owned_retained_route {
                self.tool_jobs
                    .dispatch_wire_retained_with_spec(&retained_wire_admission, retained_wire.take().expect("app-owned retained wire owner transfers once"), None, operation_spec)
                    .map_err(|rejected| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.dispatch"), rejected.error.to_string()))?
            } else {
                self.tool_jobs.dispatch(operation_spec).map_err(|error| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.dispatch"), error.to_string()))?
            };
            let params = semio_framework_job::BatchJobParams {
                operation: operation_id,
                generation,
                cancel: cancellation_lease.cancel_token(),
                config: semio_framework_job::BatchDriveConfig {
                    site: "plugin_app_tool_command",
                    stage: semio_framework_job::InteractiveStage::InteractiveStep,
                    fuel_per_step: admission.proof.contract().max_work_units_per_step,
                    step_budget_us: u64::from(admission.proof.contract().max_step_micros),
                },
                now_us: semio_framework_job::default_now_us,
            };
            #[cfg(test)]
            let params = semio_framework_job::BatchJobParams { now_us: self.test_tool_clock.unwrap_or(params.now_us), ..params };
            let pool = semio_framework_async::process_worker_pool(semio_framework_async::WorkerPoolConfig::new(semio_framework_async::ProcessKind::InteractiveNative, std::thread::available_parallelism().map_or(1, std::num::NonZeroUsize::get)));
            let (session, session_rejected) = match semio_framework_job::MountedWorkerJobSession::try_new(dispatch.job, params) {
                Ok(session) => (Some(session), None),
                Err(rejected) => (None, Some(rejected)),
            };
            self.tool_operations.insert_admitted(
                operation_id.0,
                MountedTypedCommandFullOperation {
                    verb: verb.clone(),
                    meta: meta.clone(),
                    operation,
                    canonical_revision: canonical_base_revision,
                    artifact_generation: generation.0,
                    config_generation,
                    draft_generation,
                    presence_generation,
                    transient_generation,
                    window_config_authority,
                    window_transient_authority,
                    publication_lanes,
                    session,
                    session_rejected,
                    completion: Some(completion),
                    raw_input: (!app_owned_retained_route).then_some(raw_input),
                    output_chunks: Some(output_chunks),
                    cancellation_lease: Some(cancellation_lease),
                    terminal_outcome: None,
                    terminal_seen: false,
                    publication: None,
                    pending_artifact_publication: None,
                    pending_child_publication: None,
                    captured_child_content: Some(std::sync::Arc::clone(&children)),
                    captured_child_content_generation: self.child_content_generation,
                    result_page: None,
                    result_page_presented: false,
                    result_sequence: 0,
                    publication_progress: 0,
                    publication_checkpoint: None,
                    publication_attempt: 0,
                    ui_pending: false,
                    progress: None,
                    progress_pending: false,
                    user_cancel_requested: false,
                    published_artifact: false,
                    published_config: false,
                    published_window_config: false,
                    command_logged: false,
                    interaction_revalidated: false,
                    terminal_fault: None,
                    stage: MountedTypedCommandFullOperationStage::Worker,
                },
            );
            if let Some(active) = self.tool_operations.get_mut(operation_id.0) {
                self.typed_operation_reservations[operation_id.0 as usize % ARTIFACT_LIVE_OUTPUT_SLOTS] = None;
                let _ = active.drive_worker_step(&pool, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES)?;
            }
            let mut started = Self::empty_result(&verb, meta, Vec::new(), Vec::new(), UiDirtyScope::None).await;
            started.output = DslValue::Object(vec![("operationId".into(), DslValue::String(operation_id.0.to_string())), ("generation".into(), DslValue::String(generation.0.to_string()))]);
            Ok(started)
        }

        /// 🎯️ B1: the shared body behind both `dispatch_typed_command` (wire bytes, decoded above)
        /// 🧪️ Test-only typed-value helper. Production callers must enter with an exact
        /// owner-qualified retained raw-page admission and cannot infer identity from a bare command.
        pub fn dispatch_typed<'a>(&'a mut self, command: A::Command, meta: &'a ActionMeta) -> impl Future<Output = Result<InvocationResult, Fault>> + 'a {
            let command = Box::new(command);
            async move {
                let log_generation_before = self.log_generation;
                let verb = A::command_id(command.as_ref()).await;
                let payload = ::protocol::OpBinary::encode_op(command.as_ref()).map_err(|error| error.into_fault())?;
                let admission = self.admit_command_wire(verb, &payload, 1).await?;
                let result = self.dispatch_typed_command_inner(command, admission, meta).await?;
                Ok(self.finish_recorded(log_generation_before, verb, result).await)
            }
        }

        /// 🕰️ The actual body of `PluginApp::import_media` — see `dispatch_action`'s doc.
        ///
        /// 🔒️ Contract §2.3 clause 1 — `import` is not a string action (see `VIEWER_REJECTED_ACTION_IDS`'s
        /// own doc), so it is guarded here instead of `dispatch_action`.
        async fn dispatch_import_media(&mut self, port: &str, media: Media, meta: &ActionMeta) -> Result<InvocationResult, Fault> {
            if A::ROLE == AppRole::Viewer {
                return Err(viewer_read_only_fault("import"));
            }
            let proof = self.qualified_tool_proof("import-media")?;
            let key = proof.key();
            let admission = self.tool_jobs.admit_exact_wire(key.controller_id, key.tool_id, proof.schema_id(), &[]).map_err(|error| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.dispatch"), error.to_string()))?;
            if !proof.admits::<A>(&admission) {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.factory-identity"), "media import resolved outside its exact controller/owner/factory/tool/schema proof"));
            }
            let (job, completion) = self.build_artifact_reserved_media_job(port, media, meta).await?;
            let raw = Vec::new();
            let permit = self.run_framework_reserved_job("import-media", &raw, 1, job, meta, Some(admission)).await?;
            self.validate_framework_reserved_commit("import-media", &permit).await?;
            let (emit, ephemeral) = completion.take_emit()?.ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.missing-output"), format!("media import port '{port}' completed without producer output")))?;
            let emit = emit?;
            Self::ensure_reserved_emit_bounded("import-media", &emit, self.qualified_tool_proof("import-media")?.contract()).await?;
            self.presence_store.apply(&ephemeral.presence).await.map_err(|error| Fault::from(error.to_string()))?;
            self.transient_store.apply(&ephemeral.transient).await.map_err(|error| Fault::from(error.to_string()))?;
            let result = self.dispatch_emit("import-media", emit, meta).await;
            permit.finish();
            result
        }

        /// 🧮️ B1: dispatches a binary-encoded `store::ArtifactCommand<A::ConfigMutation>` against
        /// the config store — real work for `AppCommand::ConfigCommand` (replaces the deleted
        /// `apply_config_bytes` whole-record-replace legacy path).
        async fn dispatch_config_command_inner(&mut self, command_bytes: &[u8], meta: &ActionMeta) -> Result<InvocationResult, Fault> {
            let raw = command_bytes.to_vec();
            let decoded = std::sync::Arc::new(std::sync::Mutex::new(None));
            let job = FrameworkConfigurationBinaryJob::<A> { raw: raw.clone(), cursor: 0, stage: FrameworkConfigurationBinaryStage::Envelope, operation: None, decoded: std::mem::ManuallyDrop::new(Some(decoded.clone())), closing: false };
            let permit = self.run_framework_reserved_job("configuration-binary", &raw, 1, job, meta, None).await?;
            self.validate_framework_reserved_commit("configuration-binary", &permit).await?;
            let command = decoded
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .take()
                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.missing-output"), "configuration binary job completed without a decoded command"))??;
            if permit.is_cancelled().await {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.cancelled"), "configuration binary was cancelled before config-store commit"));
            }
            self.config_store.set_local_actor_id(Some(meta.actor.clone())).map_err(|error| error.into_fault())?;
            self.config_store.dispatch(command).await.map_err(|error| error.into_fault())?;
            self.cache = None;
            let config_edit_id = self.config_store.envelope().vcs.edits.last().map(|edit| edit.id.clone());
            self.record_command("configCommand", ActionKind::Shell, None, None, config_edit_id, None);
            permit.finish();
            Ok(Self::empty_result("configCommand", meta, Vec::new(), Vec::new(), UiDirtyScope::Full).await)
        }

        /// 🧾️ Whether a verb of this declared kind may dirty the history panel. `dispatch_emit` records a
        /// command-log row for EVERY dispatch, view actions included (`ActionKind::View` is also the
        /// fallback for an unresolved verb), so the log generation advancing is not by itself evidence that
        /// anything a user would call history happened. A `View` verb paints, it does not command; an
        /// `Interaction` verb moves selection/hover, which `dispatch_interaction_action` has always
        /// declared as kept out of the panel. Handing either one a history patch made every background
        /// tick a history update — measured 2026-09-09 20:55 as 90 host `readHistory` round trips beside
        /// 252 `fillBuildTick`s in 35 s.
        /// 🚫️async: E1 pure classification consumed by sync-only `matches!` call sites — see R9
        fn verb_dirties_history_panel(kind: Option<ActionKind>) -> bool {
            !matches!(kind, Some(ActionKind::View | ActionKind::Interaction))
        }

        /// 🧾️ Attaches the command-log delta directly to the accepted invocation response. History is
        /// no longer a plugin-rendered panel body, so this deliberately leaves `ui_scope` untouched.
        /// `verb` is the DECLARED action/command id — every caller must pass the real one, never a generic
        /// placeholder, or the kind lookup below silently resolves to nothing and the skip is unreachable.
        async fn finish_recorded(&mut self, log_generation_before: u64, verb: &str, mut result: InvocationResult) -> InvocationResult {
            if self.log_generation == log_generation_before {
                return result;
            }
            let kind = self.registry.get(verb).map(|definition| definition.kind).or_else(|| self.registry.get_command(verb).map(|command| command.kind));
            if !Self::verb_dirties_history_panel(kind) {
                return result;
            }
            result.history_patch = self.history_patch(false).await.ok();
            result
        }

        pub(crate) fn drive_envelope_field_decoder_returns(&mut self, maximum_items: usize, maximum_bytes: usize, closing: bool) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            let cursor = if closing { &mut self.close_envelope_field_decoder_cursor } else { &mut self.maintenance_envelope_field_decoder_cursor };
            if let Some((index, id)) = self.envelope_field_decoder_retirements.next_id_from(*cursor) {
                let retirement = self
                    .envelope_field_decoder_retirements
                    .get_mut(id)
                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.field-retirement-authority"), "returned envelope field decoder changed during one bounded maintenance step"))?;
                let step = store::ErasedSnapshotRetirement::close_step(retirement, maximum_items.min(1), maximum_bytes).map_err(|error| plugin_sdk_fault(error.to_string()))?;
                match step {
                    store::SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= 1 && released_items <= maximum_items && released_bytes <= maximum_bytes => {
                        *cursor = index;
                        return Ok(PluginCloseStep::Pending { released_items, released_bytes });
                    }
                    store::SnapshotRetirementStep::Pending { .. } => {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.field-retirement-over-budget"), "returned envelope field decoder exceeded its exact one-owner maintenance grant"));
                    }
                    store::SnapshotRetirementStep::Blocked => {
                        *cursor = index;
                        return Ok(PluginCloseStep::Blocked { reason: "returned envelope field decoder is externally blocked" });
                    }
                    store::SnapshotRetirementStep::Complete => {}
                }
                if !store::ErasedSnapshotRetirement::terminal_is_empty(retirement) {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.field-retirement-false-terminal"), "returned envelope field decoder reported Complete without terminal-empty ownership"));
                }
                let retirement = self
                    .envelope_field_decoder_retirements
                    .remove(id)
                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.field-retirement-authority"), "terminal envelope field decoder changed before exact removal"))?;
                drop(retirement);
                *cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            let Some(ticket) = self.envelope_field_decoders.next_returned_ticket() else {
                return if closing && !self.envelope_field_decoders.terminal_is_empty() {
                    Ok(PluginCloseStep::Blocked { reason: "artifact envelope field lease remains live outside the bounded app return pump" })
                } else {
                    Ok(PluginCloseStep::Complete)
                };
            };
            let id = ticket.index() as u64;
            if !self.envelope_field_decoder_retirements.can_insert(id) {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            let retirement = match self.envelope_field_decoders.take_returned_ticket(ticket) {
                Ok(retirement) => retirement,
                Err(store::ArtifactEnvelopeFieldDecoderRegistryFault::Contended | store::ArtifactEnvelopeFieldDecoderRegistryFault::Returned | store::ArtifactEnvelopeFieldDecoderRegistryFault::Stale) => {
                    return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                }
                Err(_) => {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.field-return-invalid"), "returned envelope field decoder lost its exact registry generation before bounded handoff"));
                }
            };
            self.envelope_field_decoder_retirements.insert_admitted(id, retirement);
            *cursor = ticket.index();
            Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
        }

        pub(crate) fn drive_envelope_completed_record_returns(&mut self, maximum_items: usize, maximum_bytes: usize, closing: bool) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            let cursor = if closing { &mut self.close_envelope_completed_record_cursor } else { &mut self.maintenance_envelope_completed_record_cursor };
            if let Some((index, id)) = self.envelope_completed_record_retirements.next_id_from(*cursor) {
                let retirement = self
                    .envelope_completed_record_retirements
                    .get_mut(id)
                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.completed-retirement-authority"), "completed envelope changed during one bounded maintenance step"))?;
                match retirement.close_step(maximum_items.min(1), maximum_bytes.min(store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES)).map_err(|error| plugin_sdk_fault(error.to_string()))? {
                    store::SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= 1 && released_items <= maximum_items && released_bytes <= maximum_bytes => {
                        *cursor = index;
                        return Ok(PluginCloseStep::Pending { released_items, released_bytes });
                    }
                    store::SnapshotRetirementStep::Pending { .. } => {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.completed-retirement-over-budget"), "completed envelope exceeded its exact one-owner maintenance grant"));
                    }
                    store::SnapshotRetirementStep::Blocked => {
                        *cursor = index;
                        return Ok(PluginCloseStep::Blocked { reason: "completed envelope retirement is externally blocked" });
                    }
                    store::SnapshotRetirementStep::Complete => {}
                }
                if !retirement.terminal_is_empty() {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.completed-retirement-false-terminal"), "completed envelope reported Complete without terminal-empty ownership"));
                }
                let retirement = self
                    .envelope_completed_record_retirements
                    .remove(id)
                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.completed-retirement-authority"), "terminal completed envelope changed before exact removal"))?;
                drop(retirement);
                *cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            let ticket = match if closing { self.envelope_completed_records.try_next_ticket(cursor) } else { self.envelope_completed_records.try_next_close_ticket(cursor) } {
                Ok(ticket) => ticket,
                Err(store::ArtifactEnvelopeCompletedRecordFault::Contended) => return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 }),
                Err(_) => {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.completed-registry-invalid"), "completed envelope registry lost its exact generation authority"));
                }
            };
            let Some(ticket) = ticket else {
                return if closing && !self.envelope_completed_records.terminal_is_empty() { Ok(PluginCloseStep::Blocked { reason: "completed envelope owner remains live outside the bounded app close pump" }) } else { Ok(PluginCloseStep::Complete) };
            };
            let id = ticket
                .generation()
                .checked_mul(ARTIFACT_LIVE_OUTPUT_SLOTS as u64)
                .and_then(|base| base.checked_add(ticket.index() as u64))
                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.completed-generation-exhausted"), "completed envelope retirement identity overflowed"))?;
            if !self.envelope_completed_record_retirements.can_insert(id) {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            let retirement = match self.envelope_completed_records.try_detach(ticket) {
                Ok(retirement) => retirement,
                Err(store::ArtifactEnvelopeCompletedRecordFault::Contended | store::ArtifactEnvelopeCompletedRecordFault::Stale) => {
                    return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                }
                Err(_) => {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.completed-detach-invalid"), "completed envelope could not transfer its exact owner into bounded retirement"));
                }
            };
            self.envelope_completed_record_retirements.insert_admitted(id, retirement);
            Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
        }

        fn close_projection_cache_step(&mut self, maximum_items: usize) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if self.close_cache.is_none() {
                if let Some((_, snapshot, config, history)) = self.cache.take() {
                    *self.close_cache = Some(ArtifactCacheRetirement { snapshot: Some(snapshot), config: Some(config), history: Some(history) });
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
            }
            if let Some(cache) = self.close_cache.as_mut() {
                let step = cache.close_step(maximum_items.min(1));
                if step != PluginCloseStep::Complete {
                    return Ok(step);
                }
                if !cache.terminal_is_empty() {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-cache-terminal-not-empty"), "cache retirement reported Complete before every retained root was released"));
                }
                drop(self.close_cache.take());
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            Ok(PluginCloseStep::Complete)
        }

        /// 🧹️ One grant-sized page of a retained string, `None` once the string is empty.
        ///
        /// ⚖️ A retained field is drained IN PLACE, in pages, never priced atomically against one
        /// turn's grant: a value larger than the grant that is pushed back unreleased is a
        /// permanent `Pending { 0, 0 }` — the close can never afford it however many turns the host
        /// spends. Measured 2026-09-16 (ticket 26/08/28/DEMONSTRATOR-END-TO-END-ALL-APPS): a
        /// `setContributions` config edit whose command-log LABEL carries the pack text (4 391 B)
        /// livelocked `close_step(1, 4_096)` for 15 M turns, which capped EVERY app's retained
        /// config at about one `ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES` page regardless of its declared
        /// maximum. The cut lands on a char boundary at or after the grant's, so a page never
        /// exceeds the grant; a grant too small for one UTF-8 scalar releases nothing.
        fn close_retained_string_page(value: &mut String, maximum_bytes: usize) -> Option<PluginCloseStep> {
            if value.is_empty() {
                return None;
            }
            let mut cut = value.len().saturating_sub(maximum_bytes);
            while cut < value.len() && !value.is_char_boundary(cut) {
                cut += 1;
            }
            let released_bytes = value.len() - cut;
            if released_bytes == 0 {
                return Some(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            value.truncate(cut);
            Some(PluginCloseStep::Pending { released_items: 0, released_bytes })
        }

        /// 🧹️ One grant-sized page of a retained byte buffer — the `Vec<u8>` twin of
        /// [`Self::close_retained_string_page`], with the same page-never-refuse law.
        fn close_retained_bytes_page(value: &mut Vec<u8>, maximum_bytes: usize) -> Option<PluginCloseStep> {
            if value.is_empty() {
                return None;
            }
            let released_bytes = value.len().min(maximum_bytes);
            if released_bytes == 0 {
                return Some(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            value.truncate(value.len() - released_bytes);
            Some(PluginCloseStep::Pending { released_items: 0, released_bytes })
        }

        fn close_retained_fields_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> PluginCloseStep {
            if maximum_items == 0 {
                return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
            }
            if let Some(entry) = self.command_log.last_mut() {
                if let Some(value) = entry.config_edit_ids.last_mut() {
                    if let Some(step) = Self::close_retained_string_page(value, maximum_bytes) {
                        return step;
                    }
                    drop(entry.config_edit_ids.pop());
                    return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
                }
                if let Some(value) = entry.child_edit_ids.last_mut() {
                    if let Some(step) = Self::close_retained_string_page(value, maximum_bytes) {
                        return step;
                    }
                    drop(entry.child_edit_ids.pop());
                    return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
                }
                for field in [&mut entry.action_id, &mut entry.timestamp] {
                    if let Some(step) = Self::close_retained_string_page(field, maximum_bytes) {
                        return step;
                    }
                }
                for cell in entry.label.texts_mut() {
                    if let Some(step) = Self::close_retained_string_page(cell, maximum_bytes) {
                        return step;
                    }
                }
                if let Some(value) = entry.edit_id.as_mut() {
                    if let Some(step) = Self::close_retained_string_page(value, maximum_bytes) {
                        return step;
                    }
                    drop(entry.edit_id.take());
                    return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
                }
            }
            if let Some(entry) = self.command_log.pop() {
                drop(entry);
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if let Some(sequence) = self.history_dirty_sequences.iter().next().copied() {
                self.history_dirty_sequences.remove(&sequence);
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if let Some(pin) = self.pending_child_pins.pop() {
                drop(pin);
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            match self.composition.close_step(maximum_items.min(1), maximum_bytes) {
                store::SnapshotRetirementStep::Pending { released_items, released_bytes } => return PluginCloseStep::Pending { released_items, released_bytes },
                store::SnapshotRetirementStep::Blocked => return PluginCloseStep::Blocked { reason: "composition graph retirement is externally blocked" },
                store::SnapshotRetirementStep::Complete => {}
            }
            if let Some((domain, hover)) = self.interaction_hover.pop_first() {
                let bytes = domain.len().min(maximum_bytes);
                drop((domain, hover));
                return PluginCloseStep::Pending { released_items: 1, released_bytes: bytes };
            }
            if let Some(domain) = self.interaction_ui_topology.keys().next() {
                let domain = domain.clone();
                let bytes = domain.len().min(maximum_bytes);
                drop(self.interaction_ui_topology.remove(&domain));
                return PluginCloseStep::Pending { released_items: 1, released_bytes: bytes };
            }
            if let Some(transaction) = self.pending_transaction.as_mut() {
                if let Some(operation) = transaction.ops.pop() {
                    drop(operation);
                    return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
                }
                if let Some(child) = transaction.children.last_mut() {
                    let step = child.close_one(1, maximum_bytes);
                    if step == PluginCloseStep::Complete {
                        transaction.children.pop();
                        return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
                    }
                    return step;
                }
            }
            if let Some(transaction) = self.pending_transaction.take() {
                drop(transaction);
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if let Some(proposal) = self.pending_transaction_proposal.as_mut() {
                if let Some(operation) = proposal.local_ops.last_mut() {
                    if let Some(step) = Self::close_retained_bytes_page(operation, maximum_bytes) {
                        return step;
                    }
                    drop(proposal.local_ops.pop());
                    return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
                }
                if let Some(foreign) = proposal.foreign.pop() {
                    drop(foreign);
                    return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
                }
            }
            if let Some(proposal) = self.pending_transaction_proposal.take() {
                drop(proposal);
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if let Some(presence) = self.pending_presence.pop() {
                drop(presence);
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if let Some(wire) = self.last_emit_wire.as_mut() {
                for bytes in [&mut wire.document, &mut wire.config, &mut wire.draft, &mut wire.children] {
                    if let Some(step) = Self::close_retained_bytes_page(bytes, maximum_bytes) {
                        return step;
                    }
                    if bytes.capacity() != 0 {
                        drop(std::mem::take(bytes));
                        return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
                    }
                }
            }
            if self.last_emit_wire.take().is_some() {
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if let Some(effect) = self.typed_effect_outbox.pop() {
                drop(effect);
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if let Some(event) = self.typed_event_outbox.pop() {
                drop(event);
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if let Some(scope) = self.typed_ui_outbox.pop() {
                drop(scope);
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if std::mem::take(&mut self.operation_progress_retired) {
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if let Some(completion) = self.typed_completion_outbox.pop() {
                drop(completion);
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if let Some(composed) = self.typed_composed_outbox.pop() {
                drop(composed);
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            let registry_step = self.registry.close_step(maximum_items.min(1), maximum_bytes);
            if registry_step != PluginCloseStep::Complete {
                return registry_step;
            }
            if self.bounded_tool_proofs.pop_first().is_some() {
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if let Some(contract) = self.bounded_tool_contracts.pop() {
                drop(contract);
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if let Some((_, registration)) = self.framework_tool_registrations.pop_first() {
                drop(registration);
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if let Some((_, registration)) = self.app_tool_registrations.pop_first() {
                drop(registration);
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if let Some(step) = Self::close_retained_string_page(&mut self.tool_job_controller_id, maximum_bytes) {
                return step;
            }
            if self.tool_job_controller_id.capacity() != 0 {
                drop(std::mem::take(&mut self.tool_job_controller_id));
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            PluginCloseStep::Complete
        }

        fn retained_fields_terminal_is_empty(&self) -> bool {
            self.cache.is_none()
                && self.close_cache.as_ref().is_none_or(ArtifactCacheRetirement::terminal_is_empty)
                && self.command_log.is_empty()
                && self.history_dirty_sequences.is_empty()
                && self.children.is_empty()
                && self.pending_child_pins.is_empty()
                && self.composition.terminal_is_empty()
                && self.interaction_hover.is_empty()
                && self.interaction_ui_topology.is_empty()
                && self.local_interaction_query.is_none()
                && self.snapshot_read_returns_terminal_is_empty()
                && self.pending_transaction.is_none()
                && self.pending_transaction_proposal.is_none()
                && self.pending_presence.is_empty()
                && self.last_emit_wire.is_none()
                && self.typed_effect_outbox.len() == 0
                && self.typed_event_outbox.len() == 0
                && self.typed_ui_outbox.len() == 0
                && !self.operation_progress_retired
                && self.typed_completion_outbox.len() == 0
                && self.typed_composed_outbox.len() == 0
                && self.registry.terminal_is_empty()
                && self.bounded_tool_proofs.is_empty()
                && self.bounded_tool_contracts.is_empty()
                && self.framework_tool_registrations.is_empty()
                && self.app_tool_registrations.is_empty()
                && self.tool_job_controller_id.is_empty()
        }

        /// 🪪️ The immutable identity this instance's live document revision is observed under — the ONE
        /// derivation every entry point that hands a plugin an [`ArtifactView`] stamps into it
        /// (`render`, `pending_effects`, `window_engagements`, `window_measures`, `tool_measures`,
        /// `context_menu`). Chrome that reaches for its own per-instance session (puzzle 3d's
        /// `puzzle3d_view_session_key`) read `None` on the four view-only lanes and ran cold against a
        /// session-less app; deriving the identity here — not per call site — makes that key total.
        /// 🚫️async: E1 pure identity projection over already-owned store fields — see R9.
        fn live_render_operation(&self) -> AppRenderOperationContext {
            let canonical_base_revision = self.store.content_revision();
            let [lane_0, lane_1, lane_2, lane_3, lane_4, lane_5, lane_6, lane_7, ..] = canonical_base_revision;
            AppRenderOperationContext {
                app_instance_id: self.live_runtime_instance_id.unwrap_or_default(),
                base_revision: semio_framework_job::RevisionId(u64::from_be_bytes([lane_0, lane_1, lane_2, lane_3, lane_4, lane_5, lane_6, lane_7])),
                generation: semio_framework_job::Generation(self.store.generation()),
                canonical_base_revision,
            }
        }

        #[cfg(test)]
        pub(crate) fn typed_operation_result_state_for_test(&self, operation_id: u64) -> Option<(TypedOperationResultToken, TypedOperationResultLane, bool, bool)> {
            let operation = self.tool_operations.get(operation_id)?;
            let page = operation.result_page.as_ref()?;
            Some((page.token, page.lane, operation.result_page_presented, operation.stage == MountedTypedCommandFullOperationStage::AwaitingAck))
        }
    }

    impl<A: ArtifactApp, M: SpaceMember + MemberFactory> Drop for VcsArtifactApp<A, M> {
        fn drop(&mut self) {
            self.tool_cancellations.cancel_scope_generation();
            while let Some((_, id)) = self.pending_reserved.next_id_from(0) {
                if let Some(pending) = self.pending_reserved.remove(id) {
                    pending.permit.finish();
                } else {
                    break;
                }
            }
            while let Some(commit) = self.reserved_commits.pop_front() {
                commit.permit.finish();
            }
        }
    }

    /// 📣️ Signals the shell that the document's checkpoint/alternative history changed (after an
    /// undo/redo/checkpoint/alternative command) so it can re-render history-dependent surfaces.
    async fn history_changed_event() -> AppEvent {
        AppEvent { kind: "history-changed".into(), payload: DslValue::Null }
    }

    /// 🧪 Guest laws in dependent crates (puzzle 3d) settle Isolated reserved admits the host would.
    pub async fn settle_framework_reserved_admission<A: ArtifactApp, M: SpaceMember + MemberFactory + Send + 'static>(app: &mut VcsArtifactApp<A, M>, admitted: InvocationResult) -> Result<InvocationResult, Fault> {
        initialize_framework_reserved_jobs();
        let Some((job, input)) = admitted.requested_effects.iter().find_map(|effect| match effect {
            Effect::SpawnJob { job, kind, input, .. } if kind == FRAMEWORK_RESERVED_JOB_KIND => Some((*job, input.clone())),
            _ => None,
        }) else {
            return Ok(admitted);
        };
        crate::reactor::jobs::start_job(job, FRAMEWORK_RESERVED_JOB_KIND, &input).await;
        let mut terminal = None;
        for _ in 0..8 {
            match crate::reactor::jobs::step_job(job, crate::reactor::jobs::JobBudget { fuel: 1, deadline_ms: 1 }).await {
                crate::reactor::jobs::JobStep::Running(_) => {}
                crate::reactor::jobs::JobStep::Done(bytes) => {
                    terminal = Some(Ok(bytes));
                    break;
                }
                crate::reactor::jobs::JobStep::Failed(bytes) => {
                    terminal = Some(Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.reserved-spawn-failed"), String::from_utf8_lossy(&bytes).into_owned())));
                    break;
                }
            }
        }
        let output = terminal.ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.reserved-spawn-stall"), "framework reserved spawn-job did not reach a terminal step"))?;
        settle_framework_reserved_commit(app, job, output).await
    }

    /// 🪜️ Most units one reserved commit may take in a settle law — one per composed child or undone
    /// edit, well above anything a fixture composes.
    pub const FRAMEWORK_RESERVED_COMMIT_SETTLE_UNITS: usize = 4_096;

    /// 🪜️ Hands a finished reserved spawn-job to `app`'s commit queue and drives the commit one unit
    /// per call — the same units the reactor's typed-operation continuation runs across turns — to its
    /// outcome.
    pub async fn settle_framework_reserved_commit<A: ArtifactApp, M: SpaceMember + MemberFactory + Send + 'static>(app: &mut VcsArtifactApp<A, M>, job: u64, output: Result<Vec<u8>, Fault>) -> Result<InvocationResult, Fault> {
        if !app.admit_framework_reserved_commit(job, output)? {
            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.reserved-spawn-missing"), "framework reserved spawn-job had no pending admit"));
        }
        for _ in 0..FRAMEWORK_RESERVED_COMMIT_SETTLE_UNITS {
            app.step_framework_reserved_commit().await?;
            if let Some(outcome) = app.take_framework_reserved_commit_outcome() {
                return outcome;
            }
        }
        Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.reserved-commit-stall"), format!("framework reserved commit did not finish within {FRAMEWORK_RESERVED_COMMIT_SETTLE_UNITS} units")))
    }

    /// 🧪 Browser `driveSpawnedJob` contract: one Isolated admission of 32 `step-job`s with the host's
    /// static budget. The dummy reserved job must reach Done in 2 steps — the #38 stall was the host
    /// never finishing that pump, not the guest body needing more slices.
    #[cfg(test)]
    pub async fn drive_framework_reserved_spawn_like_host<A: ArtifactApp, M: SpaceMember + MemberFactory + Send + 'static>(app: &mut VcsArtifactApp<A, M>, admitted: InvocationResult) -> Result<(InvocationResult, u32), Fault> {
        initialize_framework_reserved_jobs();
        let Some((job, input)) = admitted.requested_effects.iter().find_map(|effect| match effect {
            Effect::SpawnJob { job, kind, input, .. } if kind == FRAMEWORK_RESERVED_JOB_KIND => Some((*job, input.clone())),
            _ => None,
        }) else {
            return Ok((admitted, 0));
        };
        crate::reactor::jobs::start_job(job, FRAMEWORK_RESERVED_JOB_KIND, &input).await;
        let host_budget = crate::reactor::jobs::JobBudget { fuel: 50_000_000, deadline_ms: 100 };
        let mut steps = 0u32;
        let mut terminal = None;
        for _ in 0..32 {
            steps += 1;
            match crate::reactor::jobs::step_job(job, host_budget).await {
                crate::reactor::jobs::JobStep::Running(_) => {}
                crate::reactor::jobs::JobStep::Done(bytes) => {
                    terminal = Some(Ok(bytes));
                    break;
                }
                crate::reactor::jobs::JobStep::Failed(bytes) => {
                    terminal = Some(Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.reserved-spawn-failed"), String::from_utf8_lossy(&bytes).into_owned())));
                    break;
                }
            }
        }
        let output = terminal.ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.reserved-spawn-stall"), format!("framework reserved spawn-job did not reach Done within one host drive admission ({steps} steps)")))?;
        if steps > 2 {
            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.reserved-spawn-budget"), format!("framework reserved dummy job took {steps} steps; host noteShellCommand finishes in 2")));
        }
        let settled = settle_framework_reserved_commit(app, job, output).await?;
        Ok((settled, steps))
    }

    /// 🕰️ Length of [`PluginApp::maintenance_step`]'s fixed cooperative round robin. Every stage
    /// runs at most one bounded unit per call, so a step-budget law needs exactly this many calls
    /// to observe each stage once.
    pub const MAINTENANCE_STAGES: u8 = 26;
    /// 🧹️ The rotation stage that drains the document store's displaced-owner queue.
    pub const MAINTENANCE_DOCUMENT_DISPLACED_STAGE: u8 = 9;
    /// 🧹️ The rotation stage that drains the config-lane stores' displaced-owner queues.
    pub const MAINTENANCE_CONFIG_LANE_DISPLACED_STAGE: u8 = 25;
    /// 🍂️ The rotation stage that disposes retired child-content roots, also run out of turn under child pressure.
    pub(crate) const MAINTENANCE_CHILD_ROOT_STAGE: u8 = 4;
    /// 🥀️ The rotation stage that closes retired child members, also run out of turn under child pressure.
    pub(crate) const MAINTENANCE_CHILD_MEMBER_STAGE: u8 = 20;
    /// 🌡️ Occupancy of the child-root or child-member retirement registry at which maintenance spends out-of-turn steps on
    /// it — a quarter of the fixed [`ARTIFACT_LIVE_OUTPUT_SLOTS`], as the stores' displaced-owner pressure is of theirs.
    pub(crate) const MAINTENANCE_CHILD_RETIREMENT_PRESSURE_OCCUPANCY: usize = ARTIFACT_LIVE_OUTPUT_SLOTS / 4;
    /// ⏳️ Rounds one child publication spends reclaiming the retirements ahead of it before it waits instead.
    pub(crate) const CHILD_RETIREMENT_RECLAIM_STEPS: usize = ARTIFACT_LIVE_OUTPUT_SLOTS * 16;

    /// ♻️ Retirement grant of one [`VcsArtifactApp::reclaim_document_snapshot_read_returns`] pump step: a returned
    /// document root is disposed this many items at a time instead of the maintenance rotation's one.
    pub(crate) const PUBLICATION_SNAPSHOT_READ_RECLAIM_ITEMS: usize = 256;
    /// ♻️ Byte grant of the same pump step.
    pub(crate) const PUBLICATION_SNAPSHOT_READ_RECLAIM_BYTES: usize = 1 << 20;
    /// ♻️ Pump steps a batched publication spends reclaiming returned roots before it folds its next item.
    pub(crate) const PUBLICATION_SNAPSHOT_READ_RECLAIM_STEPS: usize = 4_096;

    /// 🐞️ `[TRACE]` last maintenance stage entered — temporary, ticket 26/09/02/PUZZLE-3D-END-TO-END.
    pub static LAST_MAINTENANCE_STAGE: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

    impl<A: ArtifactApp, M: SpaceMember + MemberFactory + Send + 'static> VcsArtifactApp<A, M> {
        /// 🌡️ True while the child-root or child-member retirement registry holds at least
        /// [`MAINTENANCE_CHILD_RETIREMENT_PRESSURE_OCCUPANCY`] retirements. An app that re-points a slot at a new
        /// content-addressed child per edit (writer mints one per keystroke) admits one of each per commit, which the single
        /// fair step per turn drains once per rotation: a typing run saturated the fixed slots with
        /// `interactive-job.child-root-retirement-saturated`.
        fn child_retirements_under_pressure(&self) -> bool {
            self.child_content_retirements.len() >= MAINTENANCE_CHILD_RETIREMENT_PRESSURE_OCCUPANCY || self.child_member_retirements.len() >= MAINTENANCE_CHILD_RETIREMENT_PRESSURE_OCCUPANCY
        }

        #[inline(never)]
        /// 🧹️ One displaced-owner step of the document store — the body of stage
        /// [`MAINTENANCE_DOCUMENT_DISPLACED_STAGE`], also run out of turn under pressure.
        fn maintenance_document_displaced_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            Ok(match self.store.maintenance_retirements_step(maximum_items, maximum_bytes).map_err(|error| plugin_sdk_fault(error.to_string()))? {
                store::SnapshotRetirementStep::Pending { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes },
                store::SnapshotRetirementStep::Blocked => PluginCloseStep::Blocked { reason: "artifact store displaced owner remains externally shared" },
                store::SnapshotRetirementStep::Complete => PluginCloseStep::Pending { released_items: 0, released_bytes: 0 },
            })
        }

        /// 🧹️ One displaced-owner step over the config-lane stores — app config, draft, and every
        /// live window-config partition — the body of stage [`MAINTENANCE_CONFIG_LANE_DISPLACED_STAGE`],
        /// also run out of turn under pressure. These are `ArtifactStore`s with the same fixed
        /// 1 024-slot displaced-owner queue the document stage drains, and nothing else ever drained
        /// THEIRS: a coalesced window-config amend per playback frame displaced ~3 owners a tick and a
        /// results window died after ~340 frames with `displaced-owner fixed retirement authority is
        /// saturated`.
        fn maintenance_config_lane_displaced_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            let step = if !self.config_store.maintenance_retirements_terminal_is_empty() {
                self.config_store.maintenance_retirements_step(maximum_items, maximum_bytes).map_err(|error| plugin_sdk_fault(error.to_string()))?
            } else if !self.draft_store.maintenance_retirements_terminal_is_empty() {
                self.draft_store.maintenance_retirements_step(maximum_items, maximum_bytes).map_err(|error| plugin_sdk_fault(error.to_string()))?
            } else {
                self.window_config_store.maintenance_retirements_step(maximum_items, maximum_bytes)?
            };
            Ok(match step {
                store::SnapshotRetirementStep::Pending { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes },
                store::SnapshotRetirementStep::Blocked => PluginCloseStep::Blocked { reason: "config-lane store displaced owner remains externally shared" },
                store::SnapshotRetirementStep::Complete => PluginCloseStep::Pending { released_items: 0, released_bytes: 0 },
            })
        }

        /// 🪜️ One bounded unit of ONE stage of the fixed round robin. The caller owns the cursor.
        ///
        /// 🧹️ The process-wide worker-job retirement array. A session dropped before it reached
        /// terminal-empty (a cancelled command, a closed document, an app torn down mid-flight)
        /// parks its node in one of the fixed [`semio_framework_job::WORKER_JOB_SESSION_SLOTS`]
        /// admissions, and ONLY this pump gives that slot back. Without a host that pumps it, the
        /// array fills up for the life of the process and every later `MountedWorkerJobSession`
        /// admission is refused — which is not a slow app but a dead one: the refused operation can
        /// never publish, because its job never ran.
        fn maintenance_stage_step(&mut self, stage: u8, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            match stage {
                0..=7 => self.maintenance_early_stage_step(stage, maximum_items, maximum_bytes),
                8 => {
                    let pump = &mut self.document_snapshot_read_returns;
                    let store = &mut self.store;
                    pump.drive(|| store.take_returned_snapshot_read_retirement().map_err(|error| error.into_fault()), maximum_items, maximum_bytes)
                }
                MAINTENANCE_DOCUMENT_DISPLACED_STAGE => self.maintenance_document_displaced_step(maximum_items, maximum_bytes),
                10 => match self.drive_envelope_ingress(maximum_items, maximum_bytes, false)? {
                    PluginCloseStep::Complete => Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 }),
                    step => Ok(step),
                },
                11 => {
                    self.drive_artifact_envelope_decode_worker()?;
                    Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 })
                }
                12 => match self.drive_envelope_field_decoder_returns(maximum_items, maximum_bytes, false)? {
                    PluginCloseStep::Complete => Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 }),
                    step => Ok(step),
                },
                13 => match self.drive_envelope_completed_record_returns(maximum_items, maximum_bytes, false)? {
                    PluginCloseStep::Complete => Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 }),
                    step => Ok(step),
                },
                14 => match self.drive_store_replacement_jobs(maximum_items, maximum_bytes, false)? {
                    PluginCloseStep::Complete => Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 }),
                    step => Ok(step),
                },
                15 => match self.live_runtime_instance_id {
                    Some(instance_id) => A::mounted_job_maintenance_step(instance_id, maximum_items.min(1), maximum_bytes),
                    None => Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 }),
                },
                16 => self.instance_operation_owner.maintenance_step(maximum_items.min(1), maximum_bytes),
                17 => Ok(self.latest_wins_keys.advance(maximum_items.min(1), maximum_bytes)),
                18 => {
                    if self.tool_cancellations.cleanup_finished_slot(self.maintenance_cancellation_cursor)?.is_none() {
                        return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    self.maintenance_cancellation_cursor = (self.maintenance_cancellation_cursor + 1) % (TOOL_CANCELLATION_SLOTS + ARTIFACT_LIVE_OUTPUT_SLOTS);
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                19 => self.presence_store.maintenance_local_reads_step(maximum_items.min(1), maximum_bytes).map_err(Fault::from).map(|step| match step {
                    store::SnapshotRetirementStep::Pending { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes },
                    store::SnapshotRetirementStep::Blocked => PluginCloseStep::Blocked { reason: "presence local returned owner is held" },
                    store::SnapshotRetirementStep::Complete => PluginCloseStep::Pending { released_items: 0, released_bytes: 0 },
                }),
                MAINTENANCE_CHILD_MEMBER_STAGE => self.child_member_retirement_step(maximum_items.min(1), maximum_bytes),
                21 => match self.retire_document_windows_step(maximum_items, maximum_bytes, false)? {
                    PluginCloseStep::Complete => Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 }),
                    step => Ok(step),
                },
                22 => match self.window_transient_store.maintenance_step(maximum_items.min(1), maximum_bytes)? {
                    PluginCloseStep::Complete => Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 }),
                    step => Ok(step),
                },
                23 => {
                    let advanced = semio_framework_job::pump_worker_job_retirements(1, maximum_items.min(1), maximum_bytes.min(semio_framework_job::JOB_PAYLOAD_PAGE_BYTES));
                    Ok(PluginCloseStep::Pending { released_items: advanced, released_bytes: 0 })
                }
                24 => match self.drive_document_archive_load_retirements(maximum_items, maximum_bytes, false)? {
                    PluginCloseStep::Complete => Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 }),
                    step => Ok(step),
                },
                MAINTENANCE_CONFIG_LANE_DISPLACED_STAGE => self.maintenance_config_lane_displaced_step(maximum_items, maximum_bytes),
                _ => unreachable!("fixed maintenance stage"),
            }
        }

        fn maintenance_early_stage_step(&mut self, stage: u8, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            match stage {
                0 => {
                    let mut selected = None;
                    let mut occupied = false;
                    let mut every_operation_awaits_presented_ack = true;
                    for offset in 0..ARTIFACT_LIVE_OUTPUT_SLOTS {
                        let index = (self.maintenance_tool_cursor + offset) % ARTIFACT_LIVE_OUTPUT_SLOTS;
                        let Some((operation_id, operation)) = self.tool_operations.entry(index) else { continue };
                        occupied = true;
                        match operation.stage {
                            MountedTypedCommandFullOperationStage::Worker | MountedTypedCommandFullOperationStage::Retiring => {
                                selected = Some((index, *operation_id));
                                break;
                            }
                            MountedTypedCommandFullOperationStage::AwaitingAck if operation.result_page_presented => {}
                            MountedTypedCommandFullOperationStage::Publishing | MountedTypedCommandFullOperationStage::AwaitingAck => {
                                every_operation_awaits_presented_ack = false;
                            }
                        }
                    }
                    let Some((index, operation_id)) = selected else {
                        return Ok(if occupied && every_operation_awaits_presented_ack {
                            PluginCloseStep::AwaitingInput { reason: "every typed operation awaits its exact presented host result ACK" }
                        } else {
                            PluginCloseStep::Pending { released_items: 0, released_bytes: 0 }
                        });
                    };
                    self.maintenance_tool_cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
                    if self.tool_operations.get(operation_id).is_some_and(|operation| operation.stage == MountedTypedCommandFullOperationStage::Retiring) {
                        return self.retire_typed_operation_unit(operation_id, maximum_items, maximum_bytes);
                    }
                    let pool =
                        semio_framework_async::process_worker_pool(semio_framework_async::WorkerPoolConfig::new(semio_framework_async::ProcessKind::InteractiveNative, std::thread::available_parallelism().map_or(1, std::num::NonZeroUsize::get)));
                    let operation = self
                        .tool_operations
                        .get_mut(operation_id)
                        .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-tool-authority"), "typed operation authority changed during one fixed maintenance step"))?;
                    let step = match operation.stage {
                        MountedTypedCommandFullOperationStage::Retiring => unreachable!("the retiring stage is released by its one exact retirement site"),
                        MountedTypedCommandFullOperationStage::Worker => operation.drive_worker_step(&pool, maximum_bytes)?,
                        MountedTypedCommandFullOperationStage::Publishing => PluginCloseStep::Pending { released_items: 0, released_bytes: 0 },
                        MountedTypedCommandFullOperationStage::AwaitingAck => PluginCloseStep::AwaitingInput { reason: "typed operation awaits its exact host result ACK" },
                    };
                    if step == PluginCloseStep::Complete {
                        if !self.tool_operations.get_mut(operation_id).is_some_and(|operation| operation.terminal_is_empty()) {
                            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.typed-operation-terminal"), "typed operation reported Complete without exact terminal emptiness"));
                        }
                        let operation =
                            self.tool_operations.remove(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-tool-authority"), "terminal typed operation changed before exact removal"))?;
                        self.operation_progress_retired |= operation.progress.is_some();
                        drop(operation);
                        self.typed_inline_interaction_verbs.retain(|(operation, _)| *operation != operation_id);
                        return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                    }
                    Ok(step)
                }
                1 => {
                    let Some((index, operation_id)) = self.media_closures.next_id_from(self.maintenance_media_cursor) else {
                        return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                    };
                    self.maintenance_media_cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
                    let step = self
                        .media_closures
                        .get_mut(operation_id)
                        .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-media-authority"), "live media cleanup authority changed during one fixed step"))?
                        .close_step(maximum_items, maximum_bytes)?;
                    match step {
                        PluginCloseStep::Complete => {
                            let active =
                                self.media_closures.get(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-media-authority"), "completed live media cleanup lost its exact fixed owner"))?;
                            if !active.terminal_is_empty()? {
                                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-media-terminal-not-empty"), "live media cleanup reported Complete without an exact terminal-empty witness"));
                            }
                            self.quarantine_media_snapshot(operation_id, active).map_err(|error| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-snapshot-quarantine"), error.to_string()))?;
                            let active =
                                self.media_closures.remove(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-media-authority"), "terminal live media cleanup changed before exact removal"))?;
                            drop(active);
                            Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                        }
                        step @ PluginCloseStep::Blocked { .. } => Ok(step),
                        step => Ok(step),
                    }
                }
                2 => {
                    let Some((index, operation_id)) = self.segmented_closures.next_id_from(self.maintenance_segment_cursor) else {
                        return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                    };
                    self.maintenance_segment_cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
                    if maximum_bytes < ARTIFACT_OUTPUT_CHUNK_BYTES {
                        return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    match self
                        .segmented_closures
                        .get(operation_id)
                        .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-segment-authority"), "live segmented cleanup authority changed during one fixed step"))?
                        .chunks
                        .close_take_chunk()?
                    {
                        Some(chunk) => Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: chunk.len() }),
                        None => {
                            let output = self
                                .segmented_closures
                                .remove(operation_id)
                                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-segment-authority"), "terminal live segmented cleanup changed before exact removal"))?;
                            if !output.terminal_is_empty() {
                                self.segmented_closures.insert_admitted(operation_id, output);
                                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-segment-terminal-not-empty"), "live segmented cleanup reached terminal without an empty exact chunk queue"));
                            }
                            drop(output);
                            Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                        }
                    }
                }
                3 => {
                    let Some((index, operation_id)) = self.snapshot_retirements.next_id_from(self.maintenance_snapshot_cursor) else {
                        return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                    };
                    self.maintenance_snapshot_cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
                    if self.media_exports.get(operation_id).is_some() || self.media_closures.get(operation_id).is_some() {
                        return Ok(PluginCloseStep::Blocked { reason: "snapshot retirement waits for its exact live media owner" });
                    }
                    let step = self
                        .snapshot_retirements
                        .get_mut(operation_id)
                        .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-snapshot-authority"), "live snapshot retirement authority changed during one fixed step"))?
                        .close_step(maximum_items, maximum_bytes)?;
                    if step != PluginCloseStep::Complete {
                        return Ok(match step {
                            step @ PluginCloseStep::Blocked { .. } => step,
                            step => step,
                        });
                    }
                    if !self.snapshot_retirements.get(operation_id).is_some_and(ArtifactSnapshotCloseRetention::terminal_is_empty) {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-snapshot-terminal-not-empty"), "live snapshot retirement reported Complete without its exact terminal-empty witness"));
                    }
                    let retirement = self
                        .snapshot_retirements
                        .remove(operation_id)
                        .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-snapshot-authority"), "terminal live snapshot retirement changed before exact removal"))?;
                    drop(retirement);
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                MAINTENANCE_CHILD_ROOT_STAGE => self.child_root_retirement_step(maximum_items, maximum_bytes),
                5 => {
                    let Some((index, generation)) = self.peer_presence_retirements.next_id_from(self.maintenance_peer_presence_cursor) else {
                        return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                    };
                    let step = self
                        .peer_presence_retirements
                        .get_mut(generation)
                        .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-peer-presence-authority"), "live peer-presence retirement authority changed during one fixed step"))?
                        .close_step(maximum_items, maximum_bytes)?;
                    if step != PluginCloseStep::Complete {
                        self.maintenance_peer_presence_cursor = index;
                        return Ok(step);
                    }
                    if !self.peer_presence_retirements.get(generation).is_some_and(PeerPresenceRootRetirement::terminal_is_empty) {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-peer-presence-terminal-not-empty"), "live peer-presence retirement reported Complete without its exact terminal-empty witness"));
                    }
                    let retirement = self
                        .peer_presence_retirements
                        .remove(generation)
                        .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-peer-presence-authority"), "terminal live peer-presence retirement changed before exact removal"))?;
                    drop(retirement);
                    self.maintenance_peer_presence_cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                6 => {
                    let Some((index, generation)) = self.presence_peer_retirements.next_id_from(self.maintenance_presence_peer_cursor) else {
                        return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                    };
                    let step = self
                        .presence_peer_retirements
                        .get_mut(generation)
                        .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-presence-peer-authority"), "live app-typed presence retirement authority changed during one fixed step"))?
                        .close_step(maximum_items, maximum_bytes)
                        .map_err(|error| plugin_sdk_fault(error.to_string()))?;
                    match step {
                        store::SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= maximum_items && released_bytes <= maximum_bytes => {
                            self.maintenance_presence_peer_cursor = index;
                            return Ok(PluginCloseStep::Pending { released_items, released_bytes });
                        }
                        store::SnapshotRetirementStep::Pending { .. } => {
                            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-presence-peer-over-budget"), "live app-typed presence retirement exceeded its exact maintenance grant"));
                        }
                        store::SnapshotRetirementStep::Blocked => {
                            self.maintenance_presence_peer_cursor = index;
                            return Ok(PluginCloseStep::Blocked { reason: "app-typed presence retirement waits for its exact captured root" });
                        }
                        store::SnapshotRetirementStep::Complete => {}
                    }
                    if !self.presence_peer_retirements.get(generation).is_some_and(store::PresencePeersRetirement::terminal_is_empty) {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-presence-peer-terminal-not-empty"), "live app-typed presence retirement reported Complete without its exact terminal-empty witness"));
                    }
                    let retirement = self
                        .presence_peer_retirements
                        .remove(generation)
                        .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-presence-peer-authority"), "terminal live app-typed presence retirement changed before exact removal"))?;
                    drop(retirement);
                    self.maintenance_presence_peer_cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                7 => {
                    let Some(generation) = self.peer_roster_processed_generation.checked_add(1) else {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-peer-roster-generation"), "peer roster maintenance generation exhausted"));
                    };
                    let generation = if self.peer_roster_publications.get(generation).is_some() {
                        generation
                    } else {
                        let Some(orphaned) = self.orphaned_peer_roster_generation() else {
                            return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                        };
                        orphaned
                    };
                    let index = Self::peer_roster_slot(generation);
                    let faulted = self.peer_roster_publications.get(generation).is_some_and(|publication| publication.faulted);
                    let step = if faulted {
                        self.peer_roster_publications
                            .get_mut(generation)
                            .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-peer-roster-authority"), "faulted peer roster publication changed during one fixed cleanup step"))?
                            .close_step(maximum_items, maximum_bytes)?
                    } else {
                        let step = {
                            let publications = &mut self.peer_roster_publications;
                            let presence_store = &self.presence_store;
                            publications.get_mut(generation).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-peer-roster-authority"), "peer roster publication changed during one fixed decode step"))?.step(
                                presence_store,
                                maximum_items,
                                maximum_bytes,
                            )
                        };
                        match step {
                            Ok(step) => step,
                            Err(fault) => {
                                self.peer_roster_publications
                                    .get_mut(generation)
                                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-peer-roster-authority"), "peer roster publication changed before retained fault transition"))?
                                    .fail(fault);
                                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                            }
                        }
                    };
                    if step != PluginCloseStep::Complete {
                        self.maintenance_peer_roster_cursor = index;
                        return Ok(step);
                    }
                    if faulted {
                        if !self.peer_roster_publications.get(generation).is_some_and(PeerRosterPublication::terminal_is_empty) {
                            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-peer-roster-terminal-not-empty"), "faulted peer roster publication reported Complete without its exact terminal-empty witness"));
                        }
                    } else {
                        let (seq, cancel) = {
                            let publication = self
                                .peer_roster_publications
                                .get(generation)
                                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-peer-roster-authority"), "complete peer roster publication changed before validation"))?;
                            (publication.seq, publication.cancel.clone())
                        };
                        let admission = match self.validate_peer_roster_publication(seq, generation, &cancel) {
                            Ok(admission) => admission,
                            Err(fault) => {
                                let publication = self
                                    .peer_roster_publications
                                    .get_mut(generation)
                                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-peer-roster-authority"), "stale peer roster publication changed before cleanup handoff"))?;
                                publication.fail(fault);
                                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                            }
                        };
                        let candidate = match self
                            .peer_roster_publications
                            .get_mut(generation)
                            .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-peer-roster-authority"), "complete peer roster publication changed before exact candidate commit"))?
                            .take_candidate()
                        {
                            Ok(candidate) => candidate,
                            Err(fault) => {
                                self.peer_roster_publications
                                    .get_mut(generation)
                                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-peer-roster-authority"), "peer roster publication changed before candidate fault transition"))?
                                    .fail(fault);
                                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                            }
                        };
                        if let Err(candidate) = self.publish_peer_roster_candidate_admitted(admission, candidate) {
                            self.peer_roster_publications.get_mut(generation).expect("exact peer candidate return owner").retain_rejected_candidate(candidate);
                            return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                        }
                    }
                    if !self.peer_roster_publications.get(generation).is_some_and(PeerRosterPublication::terminal_is_empty) {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-peer-roster-terminal-not-empty"), "peer roster publication reached outcome handoff without an exact empty terminal witness"));
                    }
                    let (seq, fault) = {
                        let publication = self
                            .peer_roster_publications
                            .get_mut(generation)
                            .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-peer-roster-authority"), "terminal peer roster publication changed before outcome handoff"))?;
                        (publication.seq, publication.fault.take())
                    };
                    if !self.peer_roster_outcomes.can_insert(generation) {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-peer-roster-outcome"), "pre-admitted peer roster outcome slot changed before exact handoff"));
                    }
                    self.peer_roster_outcomes.insert_admitted(generation, PresenceRosterOutcome { seq, fault });
                    let publication = self
                        .peer_roster_publications
                        .remove(generation)
                        .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-peer-roster-authority"), "terminal peer roster publication changed before exact removal"))?;
                    drop(publication);
                    let reservation_slot = Self::peer_roster_slot(generation);
                    if self.peer_roster_reservations[reservation_slot] != Some((generation, seq)) {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-peer-roster-reservation"), "terminal peer roster lost its exact ingress reservation"));
                    }
                    self.peer_roster_reservations[reservation_slot] = None;
                    self.peer_roster_processed_generation = self.peer_roster_processed_generation.max(generation);
                    self.maintenance_peer_roster_cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                _ => unreachable!("early maintenance stage"),
            }
        }
    }
    /// 🪪️ A document loaded from its text or pack belongs to the app that loads it: a pack that names no dialect is stamped
    /// with the app's own, exactly as every admission path (`try_adopt_completed`, the constructor) stamps it — without it the
    /// first child restore faulted "child restore requires the parent's exact declared dialect".
    fn loaded_with_app_dialect<A: ArtifactApp>(mut envelope: ArtifactEnvelope<A::Snapshot, A::Mutation>) -> ArtifactEnvelope<A::Snapshot, A::Mutation> {
        if envelope.dialect.is_none() {
            envelope.dialect = Some(A::DIALECT.into());
        }
        envelope
    }

    impl<A: ArtifactApp, M: SpaceMember + MemberFactory + Send + 'static> PluginApp for VcsArtifactApp<A, M> {
        async fn bind_instance_id(&mut self, instance_id: u32) {
            self.live_runtime_instance_id = Some(instance_id);
        }

        /// 🧾️ A stage that reports `Complete` HANDED OFF: one retained authority really did cross the
        /// close boundary, so the ladder owes `released_items: 1`, not `Pending { 0, 0 }` — the same
        /// convention `ArtifactStoreEnvelopeRetirement::close_step` was corrected to on 2026-09-10.
        /// `Pending { 0, 0 }` is what the structural livelock accountant reads as "this ladder is
        /// stuck" (`RUNTIME_CLOSE_ZERO_PROGRESS_LIMIT = 8`), and three consecutive hand-offs plus a
        /// couple of real waits spend that whole credit on a ladder that was making progress the
        /// entire time — reproduced intermittently by the close-cost fixture's eight-document session
        /// as `plugin.internal.zero-progress` (ticket 26/09/09).
        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if !self.close_started {
                self.tool_cancellations.cancel_scope_generation();
                self.peer_roster_scope.cancel_now();
                self.local_interaction_authority.close();
                if let Some(query) = self.local_interaction_query.as_mut() {
                    query.begin_close();
                }
                self.close_started = true;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if let Some((_, id)) = self.pending_reserved.next_id_from(0) {
                if let Some(pending) = self.pending_reserved.remove(id) {
                    pending.permit.finish();
                }
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if let Some(commit) = self.reserved_commits.pop_front() {
                commit.permit.finish();
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if self.reserved_commit_outcome.take().is_some() {
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if !self.tool_runs.terminal_is_empty() {
                let step = self.tool_runs.close_step(&mut self.store, maximum_items, maximum_bytes)?;
                return Ok(if step == PluginCloseStep::Complete { PluginCloseStep::Pending { released_items: 1, released_bytes: 0 } } else { step });
            }
            if !self.time_travel.terminal_is_empty() {
                let step = self.time_travel_close_step(maximum_items, maximum_bytes)?;
                return Ok(if step == PluginCloseStep::Complete { PluginCloseStep::Pending { released_items: 1, released_bytes: 0 } } else { step });
            }
            if self.local_interaction_query.is_some() {
                let step = self.advance_local_interaction_query_one(maximum_items, maximum_bytes)?;
                drop(self.take_local_interaction_query_reply());
                return Ok(if step == PluginCloseStep::Complete { PluginCloseStep::Pending { released_items: 1, released_bytes: 0 } } else { step });
            }
            if !self.snapshot_read_returns_terminal_is_empty() {
                let step = self.advance_snapshot_read_returns_one(maximum_bytes)?;
                return Ok(if step == PluginCloseStep::Complete { PluginCloseStep::Pending { released_items: 1, released_bytes: 0 } } else { step });
            }
            if !self.presence_store.retirement_started() && !self.presence_store.local_read_maintenance_is_idle() {
                return self.presence_store.maintenance_local_reads_step(1, maximum_bytes).map_err(Fault::from).map(|step| match step {
                    store::SnapshotRetirementStep::Pending { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes },
                    store::SnapshotRetirementStep::Blocked => PluginCloseStep::Blocked { reason: "presence returned local owner is held during app close" },
                    store::SnapshotRetirementStep::Complete => PluginCloseStep::Pending { released_items: 1, released_bytes: 0 },
                });
            }
            if let Some(instance_id) = self.live_runtime_instance_id {
                let mounted = A::mounted_job_close_step(instance_id, maximum_items.min(1), maximum_bytes)?;
                if mounted != PluginCloseStep::Complete {
                    return Ok(mounted);
                }
                if !A::mounted_jobs_terminal_is_empty(instance_id) {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-mounted-false-terminal"), "mounted app jobs reported Complete without an exact terminal-empty witness"));
                }
            }
            if self.close_cancellation_cursor < TOOL_CANCELLATION_SLOTS + ARTIFACT_LIVE_OUTPUT_SLOTS {
                let ceiling = self.close_cancellation_cursor.saturating_add(maximum_items).min(TOOL_CANCELLATION_SLOTS + ARTIFACT_LIVE_OUTPUT_SLOTS);
                let mut released_items = 0;
                while self.close_cancellation_cursor < ceiling {
                    let _ = self.tool_cancellations.cleanup_slot(self.close_cancellation_cursor)?;
                    self.close_cancellation_cursor = self.close_cancellation_cursor.saturating_add(1);
                    released_items += 1;
                }
                return Ok(PluginCloseStep::Pending { released_items, released_bytes: 0 });
            }
            if !self.latest_wins_keys.terminal_is_empty() {
                self.latest_wins_keys.begin_close();
                let step = self.latest_wins_keys.advance(maximum_items.min(1), maximum_bytes);
                return Ok(if step == PluginCloseStep::Complete { PluginCloseStep::Pending { released_items: 1, released_bytes: 0 } } else { step });
            }
            if let Some(operation_id) = self.latest_wins_order.items.front().copied() {
                return self.close_latest_wins_command_step(operation_id, maximum_items, maximum_bytes);
            }
            if !self.tool_operations.is_empty() {
                return self.close_typed_operation_step(maximum_items, maximum_bytes);
            }
            if !self.close_instance_operation_owner_drained {
                let step = self.instance_operation_owner.close_step(maximum_items.min(1), maximum_bytes)?;
                if step != PluginCloseStep::Complete {
                    return Ok(step);
                }
                if !self.instance_operation_owner.terminal_is_empty()? {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-instance-owner-false-terminal"), "app-instance operation owner reported Complete without an exact terminal-empty witness"));
                }
                self.close_instance_operation_owner_drained = true;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if self.close_media_cursor < ARTIFACT_LIVE_OUTPUT_SLOTS {
                let Some(operation_id) = self.media_exports.id_at(self.close_media_cursor) else {
                    let ceiling = self.close_media_cursor.saturating_add(maximum_items).min(ARTIFACT_LIVE_OUTPUT_SLOTS);
                    let mut released_items = 0;
                    while self.close_media_cursor < ceiling && self.media_exports.id_at(self.close_media_cursor).is_none() {
                        self.close_media_cursor = self.close_media_cursor.saturating_add(1);
                        released_items += 1;
                    }
                    return Ok(PluginCloseStep::Pending { released_items, released_bytes: 0 });
                };
                let step = self
                    .media_exports
                    .get_mut(operation_id)
                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-media-authority"), "media close authority changed during one fixed step"))?
                    .close_step(maximum_items, maximum_bytes)?;
                if step == PluginCloseStep::Complete {
                    let active = self.media_exports.get(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-media-authority"), "completed media close lost its exact fixed owner"))?;
                    if !active.terminal_is_empty()? {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-media-terminal-not-empty"), "media close reported Complete without an exact terminal-empty witness"));
                    }
                    self.quarantine_media_snapshot(operation_id, active).map_err(|error| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-snapshot-quarantine"), error.to_string()))?;
                    let active = self.media_exports.remove(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-media-authority"), "terminal media owner changed before exact removal"))?;
                    drop(active);
                    self.close_media_cursor = self.close_media_cursor.saturating_add(1);
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                return Ok(step);
            }
            if self.close_media_cleanup_cursor < ARTIFACT_LIVE_OUTPUT_SLOTS {
                let Some(operation_id) = self.media_closures.id_at(self.close_media_cleanup_cursor) else {
                    let ceiling = self.close_media_cleanup_cursor.saturating_add(maximum_items).min(ARTIFACT_LIVE_OUTPUT_SLOTS);
                    let mut released_items = 0;
                    while self.close_media_cleanup_cursor < ceiling && self.media_closures.id_at(self.close_media_cleanup_cursor).is_none() {
                        self.close_media_cleanup_cursor = self.close_media_cleanup_cursor.saturating_add(1);
                        released_items += 1;
                    }
                    return Ok(PluginCloseStep::Pending { released_items, released_bytes: 0 });
                };
                let step = self
                    .media_closures
                    .get_mut(operation_id)
                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-media-cleanup-authority"), "media cleanup authority changed during one fixed step"))?
                    .close_step(maximum_items, maximum_bytes)?;
                if step == PluginCloseStep::Complete {
                    let active = self.media_closures.get(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-media-cleanup-authority"), "completed media cleanup lost its exact fixed owner"))?;
                    if !active.terminal_is_empty()? {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-media-terminal-not-empty"), "media cleanup reported Complete without an exact terminal-empty witness"));
                    }
                    self.quarantine_media_snapshot(operation_id, active).map_err(|error| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-snapshot-quarantine"), error.to_string()))?;
                    let active = self.media_closures.remove(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-media-cleanup-authority"), "terminal media cleanup changed before exact removal"))?;
                    drop(active);
                    self.close_media_cleanup_cursor = self.close_media_cleanup_cursor.saturating_add(1);
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                return Ok(step);
            }
            if self.close_segment_cursor < ARTIFACT_LIVE_OUTPUT_SLOTS {
                let Some(operation_id) = self.segmented_downloads.id_at(self.close_segment_cursor) else {
                    let ceiling = self.close_segment_cursor.saturating_add(maximum_items).min(ARTIFACT_LIVE_OUTPUT_SLOTS);
                    let mut released_items = 0;
                    while self.close_segment_cursor < ceiling && self.segmented_downloads.id_at(self.close_segment_cursor).is_none() {
                        self.close_segment_cursor = self.close_segment_cursor.saturating_add(1);
                        released_items += 1;
                    }
                    return Ok(PluginCloseStep::Pending { released_items, released_bytes: 0 });
                };
                if maximum_bytes < ARTIFACT_OUTPUT_CHUNK_BYTES {
                    return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                }
                let chunk = self
                    .segmented_downloads
                    .get(operation_id)
                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-segment-authority"), "segmented close authority changed during one fixed step"))?
                    .chunks
                    .close_take_chunk()?;
                return match chunk {
                    Some(chunk) => Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: chunk.len() }),
                    None => {
                        let output =
                            self.segmented_downloads.remove(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-segment-authority"), "terminal segmented owner changed before exact removal"))?;
                        if !output.terminal_is_empty() {
                            self.segmented_downloads.insert_admitted(operation_id, output);
                            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-segment-terminal-not-empty"), "segmented owner reached terminal without an empty exact chunk queue"));
                        }
                        drop(output);
                        self.close_segment_cursor = self.close_segment_cursor.saturating_add(1);
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                };
            }
            if self.close_segment_cleanup_cursor < ARTIFACT_LIVE_OUTPUT_SLOTS {
                let Some(operation_id) = self.segmented_closures.id_at(self.close_segment_cleanup_cursor) else {
                    let ceiling = self.close_segment_cleanup_cursor.saturating_add(maximum_items).min(ARTIFACT_LIVE_OUTPUT_SLOTS);
                    let mut released_items = 0;
                    while self.close_segment_cleanup_cursor < ceiling && self.segmented_closures.id_at(self.close_segment_cleanup_cursor).is_none() {
                        self.close_segment_cleanup_cursor = self.close_segment_cleanup_cursor.saturating_add(1);
                        released_items += 1;
                    }
                    return Ok(PluginCloseStep::Pending { released_items, released_bytes: 0 });
                };
                if maximum_bytes < ARTIFACT_OUTPUT_CHUNK_BYTES {
                    return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                }
                let chunk = self
                    .segmented_closures
                    .get(operation_id)
                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-segment-cleanup-authority"), "segmented cleanup authority changed during one fixed step"))?
                    .chunks
                    .close_take_chunk()?;
                return match chunk {
                    Some(chunk) => Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: chunk.len() }),
                    None => {
                        let output = self
                            .segmented_closures
                            .remove(operation_id)
                            .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-segment-cleanup-authority"), "terminal segmented cleanup changed before exact removal"))?;
                        if !output.terminal_is_empty() {
                            self.segmented_closures.insert_admitted(operation_id, output);
                            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-segment-terminal-not-empty"), "segmented cleanup reached terminal without an empty exact chunk queue"));
                        }
                        drop(output);
                        self.close_segment_cleanup_cursor = self.close_segment_cleanup_cursor.saturating_add(1);
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                };
            }
            if self.close_snapshot_cursor < ARTIFACT_LIVE_OUTPUT_SLOTS {
                let Some(operation_id) = self.snapshot_retirements.id_at(self.close_snapshot_cursor) else {
                    let ceiling = self.close_snapshot_cursor.saturating_add(maximum_items).min(ARTIFACT_LIVE_OUTPUT_SLOTS);
                    let mut released_items = 0;
                    while self.close_snapshot_cursor < ceiling && self.snapshot_retirements.id_at(self.close_snapshot_cursor).is_none() {
                        self.close_snapshot_cursor = self.close_snapshot_cursor.saturating_add(1);
                        released_items += 1;
                    }
                    return Ok(PluginCloseStep::Pending { released_items, released_bytes: 0 });
                };
                let step = self
                    .snapshot_retirements
                    .get_mut(operation_id)
                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-snapshot-authority"), "snapshot retirement authority changed during one fixed step"))?
                    .close_step(maximum_items, maximum_bytes)?;
                if step == PluginCloseStep::Complete {
                    if !self.snapshot_retirements.get(operation_id).is_some_and(ArtifactSnapshotCloseRetention::terminal_is_empty) {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-snapshot-terminal-not-empty"), "snapshot retirement reported Complete without its exact terminal-empty witness"));
                    }
                    let retirement =
                        self.snapshot_retirements.remove(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-snapshot-authority"), "terminal snapshot retirement changed before exact removal"))?;
                    drop(retirement);
                    self.close_snapshot_cursor = self.close_snapshot_cursor.saturating_add(1);
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                return Ok(step);
            }
            if !self.child_member_retirements.is_empty() {
                let step = self.child_member_retirement_step(maximum_items, maximum_bytes)?;
                if !matches!(step, PluginCloseStep::Blocked { .. }) || self.child_content_retirements.is_empty() {
                    return Ok(step);
                }
            }
            if !self.child_content_retirements.is_empty() {
                let Some((index, generation)) = self.child_content_retirements.next_id_from(self.close_child_root_cursor) else {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-child-root-authority"), "child root retirement registry changed during one fixed close step"));
                };
                let step =
                    {
                        let retirements = &mut self.child_content_retirements;
                        let children = &mut self.children;
                        let retiring = &mut self.child_member_retirements;
                        let current = &*self.child_content_root;
                        let owners = retirements.sibling_content_owners(generation);
                        retirements
                            .get_mut(generation)
                            .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-child-root-authority"), "child root retirement authority changed during one fixed close step"))?
                            .close_step(children, Some(retiring), current, &owners, maximum_items, maximum_bytes)?
                    };
                if step != PluginCloseStep::Complete {
                    self.close_child_root_cursor = index;
                    return Ok(step);
                }
                if !self.child_content_retirements.get(generation).is_some_and(ChildContentRetirement::terminal_is_empty) {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-child-root-terminal-not-empty"), "child root retirement reported Complete without its exact terminal-empty witness"));
                }
                let retirement =
                    self.child_content_retirements.remove(generation).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-child-root-authority"), "terminal child root retirement changed before exact removal"))?;
                drop(retirement);
                self.close_child_root_cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if !self.close_child_root_detached {
                let retirement_generation = if self.child_content_root.root.as_ref().is_some_and(|root| root.len != 0) {
                    let generation = self
                        .child_content_generation
                        .checked_add(1)
                        .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-child-root-generation"), "child root close generation exhausted before exact ownership transfer"))?;
                    if !self.child_content_retirements.can_insert(generation) {
                        return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    Some(generation)
                } else {
                    None
                };
                let previous = std::mem::replace(&mut *self.child_content_root, ChildContentView::EMPTY);
                if let Some(generation) = retirement_generation {
                    self.child_content_retirements.insert_admitted(generation, ChildContentRetirement::new(previous, true));
                    self.child_content_generation = generation;
                } else {
                    drop(previous);
                }
                self.close_child_root_detached = true;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if let Some(retirement) = self.close_child_member.as_mut() {
                let step = retirement.close_step(maximum_items, maximum_bytes)?;
                if step != PluginCloseStep::Complete {
                    return Ok(step);
                }
                if !retirement.terminal_is_empty() {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-child-member-terminal-not-empty"), "child member retirement reported Complete without its exact terminal-empty witness"));
                }
                drop(self.close_child_member.take());
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if !self.children.is_empty() {
                if self.close_child_member_cursor >= CHILD_CONTENT_SLOTS {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-child-member-cursor"), "fixed child-member close cursor exhausted before every exact owner was detached"));
                }
                let index = self.close_child_member_cursor;
                self.close_child_member_cursor += 1;
                if let Some(entry) = self.children.take_at(index) {
                    *self.close_child_member = Some(ChildMemberRetirement::new(entry));
                }
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if !self.peer_roster_publications.is_empty() {
                let Some((index, generation)) = self.peer_roster_publications.next_id_from(self.close_peer_roster_cursor) else {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-peer-roster-authority"), "peer roster publication registry changed during one fixed close step"));
                };
                let step = self
                    .peer_roster_publications
                    .get_mut(generation)
                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-peer-roster-authority"), "peer roster publication authority changed during one fixed close step"))?
                    .close_step(maximum_items, maximum_bytes)?;
                if step != PluginCloseStep::Complete {
                    self.close_peer_roster_cursor = index;
                    return Ok(step);
                }
                if !self.peer_roster_publications.get(generation).is_some_and(PeerRosterPublication::terminal_is_empty) {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-peer-roster-terminal-not-empty"), "peer roster publication reported Complete without its exact terminal-empty witness"));
                }
                let publication =
                    self.peer_roster_publications.remove(generation).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-peer-roster-authority"), "terminal peer roster publication changed before exact removal"))?;
                drop(publication);
                let reservation_slot = Self::peer_roster_slot(generation);
                if self.peer_roster_reservations[reservation_slot].is_some_and(|(reserved, _)| reserved == generation) {
                    self.peer_roster_reservations[reservation_slot] = None;
                }
                self.close_peer_roster_cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if let Some((index, generation)) = self.peer_roster_outcomes.next_id_from(self.close_peer_roster_cursor) {
                let outcome = self.peer_roster_outcomes.remove(generation).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-peer-roster-outcome"), "peer roster outcome changed during exact close removal"))?;
                drop(outcome);
                self.close_peer_roster_cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if !self.peer_presence_retirements.is_empty() {
                let Some((index, generation)) = self.peer_presence_retirements.next_id_from(self.close_peer_presence_cursor) else {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-peer-presence-authority"), "peer-presence retirement registry changed during one fixed close step"));
                };
                let step = self
                    .peer_presence_retirements
                    .get_mut(generation)
                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-peer-presence-authority"), "peer-presence retirement authority changed during one fixed close step"))?
                    .close_step(maximum_items, maximum_bytes)?;
                if step != PluginCloseStep::Complete {
                    self.close_peer_presence_cursor = index;
                    return Ok(step);
                }
                if !self.peer_presence_retirements.get(generation).is_some_and(PeerPresenceRootRetirement::terminal_is_empty) {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-peer-presence-terminal-not-empty"), "peer-presence retirement reported Complete without its exact terminal-empty witness"));
                }
                let retirement = self
                    .peer_presence_retirements
                    .remove(generation)
                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-peer-presence-authority"), "terminal peer-presence retirement changed before exact removal"))?;
                drop(retirement);
                self.close_peer_presence_cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if !self.presence_peer_retirements.is_empty() {
                let Some((index, generation)) = self.presence_peer_retirements.next_id_from(self.close_presence_peer_cursor) else {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-presence-peer-authority"), "app-typed presence retirement registry changed during one fixed close step"));
                };
                let step = self
                    .presence_peer_retirements
                    .get_mut(generation)
                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-presence-peer-authority"), "app-typed presence retirement authority changed during one fixed close step"))?
                    .close_step(maximum_items, maximum_bytes)
                    .map_err(|error| plugin_sdk_fault(error.to_string()))?;
                match step {
                    store::SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= maximum_items && released_bytes <= maximum_bytes => {
                        self.close_presence_peer_cursor = index;
                        return Ok(PluginCloseStep::Pending { released_items, released_bytes });
                    }
                    store::SnapshotRetirementStep::Pending { .. } => {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-presence-peer-over-budget"), "app-typed presence retirement exceeded its exact close grant"));
                    }
                    store::SnapshotRetirementStep::Blocked => {
                        self.close_presence_peer_cursor = index;
                        return Ok(PluginCloseStep::Blocked { reason: "app-typed presence retirement waits for its exact captured root" });
                    }
                    store::SnapshotRetirementStep::Complete => {}
                }
                if !self.presence_peer_retirements.get(generation).is_some_and(store::PresencePeersRetirement::terminal_is_empty) {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-presence-peer-terminal-not-empty"), "app-typed presence retirement reported Complete without its exact terminal-empty witness"));
                }
                let retirement = self
                    .presence_peer_retirements
                    .remove(generation)
                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-presence-peer-authority"), "terminal app-typed presence retirement changed before exact removal"))?;
                drop(retirement);
                self.close_presence_peer_cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if !self.close_peer_presence_detached {
                let retirement_generation = if self.peer_presence.is_empty() {
                    None
                } else {
                    let generation = self
                        .peer_presence_generation
                        .checked_add(1)
                        .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-peer-presence-generation"), "peer-presence close generation exhausted before exact ownership transfer"))?;
                    if !self.peer_presence_retirements.can_insert(generation) {
                        return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    Some(generation)
                };
                let previous = std::mem::replace(&mut *self.peer_presence, PeerPresenceRoot::empty_shared());
                if let Some(generation) = retirement_generation {
                    self.peer_presence_retirements.insert_admitted(generation, PeerPresenceRootRetirement::new(previous));
                    self.peer_presence_generation = generation;
                } else {
                    drop(previous);
                }
                self.close_peer_presence_detached = true;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if !self.close_envelope_ingress_drained {
                let step = self.drive_envelope_ingress(maximum_items, maximum_bytes, true)?;
                if step != PluginCloseStep::Complete {
                    return Ok(step);
                }
                self.close_envelope_ingress_drained = true;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if !self.close_envelope_decode_jobs_drained {
                let stage = self.close_envelope_decode_stage;
                self.close_envelope_decode_stage = (stage + 1) % 3;
                let step = match stage {
                    0 => self.drive_envelope_decode_jobs(maximum_items, maximum_bytes, true)?,
                    1 => self.drive_envelope_field_decoder_returns(maximum_items, maximum_bytes, true)?,
                    2 => self.drive_envelope_completed_record_returns(maximum_items, maximum_bytes, true)?,
                    _ => unreachable!("fixed envelope close stage"),
                };
                if self.envelope_decode_jobs.is_empty() {
                    self.close_envelope_decode_jobs_drained = true;
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                return Ok(step);
            }
            if !self.close_envelope_field_decoders_drained {
                let step = self.drive_envelope_field_decoder_returns(maximum_items, maximum_bytes, true)?;
                if step != PluginCloseStep::Complete {
                    return Ok(step);
                }
                self.close_envelope_field_decoders_drained = true;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if !self.close_envelope_completed_records_drained {
                let step = self.drive_envelope_completed_record_returns(maximum_items, maximum_bytes, true)?;
                if step != PluginCloseStep::Complete {
                    return Ok(step);
                }
                self.close_envelope_completed_records_drained = true;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if !self.close_store_replacement_jobs_drained {
                let step = self.drive_store_replacement_jobs(maximum_items, maximum_bytes, true)?;
                if step != PluginCloseStep::Complete {
                    return Ok(step);
                }
                if !self.store_replacement_jobs.is_empty() {
                    return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                }
                self.close_store_replacement_jobs_drained = true;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if !self.close_document_archive_loads_drained {
                let step = self.drive_document_archive_load_retirements(maximum_items, maximum_bytes, true)?;
                if step != PluginCloseStep::Complete {
                    return Ok(step);
                }
                self.close_document_archive_loads_drained = true;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            let cache_step = self.close_projection_cache_step(maximum_items)?;
            if cache_step != PluginCloseStep::Complete {
                return Ok(cache_step);
            }
            if !self.close_snapshot_reads_drained {
                let pump = &mut self.document_snapshot_read_returns;
                let store = &mut self.store;
                let step = pump.drive(|| store.take_returned_snapshot_read_retirement().map_err(|error| error.into_fault()), maximum_items, maximum_bytes)?;
                if step != PluginCloseStep::Complete {
                    return Ok(step);
                }
                if !self.store.snapshot_read_leases_terminal_is_empty() {
                    return Ok(PluginCloseStep::Blocked { reason: "document snapshot read remains live outside the bounded return pump" });
                }
                self.close_snapshot_reads_drained = true;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            let window_retirement = self.retire_document_windows_step(maximum_items, maximum_bytes, true)?;
            if window_retirement != PluginCloseStep::Complete {
                return Ok(window_retirement);
            }
            let owned_step = match self.close_owned_stage {
                0 => drive_artifact_owned_disposer("document-store", &mut self.store, &mut self.close_document_disposer, maximum_items, maximum_bytes),
                1 => drive_artifact_owned_disposer("config-store", &mut self.config_store, &mut self.close_config_disposer, maximum_items, maximum_bytes),
                2 => drive_artifact_owned_disposer("draft-store", &mut self.draft_store, &mut self.close_draft_disposer, maximum_items, maximum_bytes),
                3 => drive_artifact_owned_disposer("presence-store", &mut self.presence_store, &mut self.close_presence_disposer, maximum_items, maximum_bytes),
                4 => drive_artifact_owned_disposer("transient-store", &mut self.transient_store, &mut self.close_transient_disposer, maximum_items, maximum_bytes),
                5 => self.window_config_store.close_step(maximum_items, maximum_bytes),
                6 => self.window_transient_store.close_step(maximum_items, maximum_bytes),
                7 => drive_artifact_owned_disposer("interaction-store", &mut self.interaction_store, &mut self.close_interaction_disposer, maximum_items, maximum_bytes),
                _ => return Ok(self.close_retained_fields_step(maximum_items, maximum_bytes)),
            }?;
            if owned_step == PluginCloseStep::Complete {
                self.close_owned_stage = self.close_owned_stage.saturating_add(1);
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            Ok(owned_step)
        }

        fn close_terminal_is_empty(&self) -> bool {
            self.close_started
                && self.tool_runs.terminal_is_empty()
                && self.time_travel.terminal_is_empty()
                && self.close_owned_stage >= 8
                && self.close_document_disposer.is_none()
                && self.close_config_disposer.is_none()
                && self.close_draft_disposer.is_none()
                && self.close_presence_disposer.is_none()
                && self.close_transient_disposer.is_none()
                && self.window_config_store.terminal_is_empty()
                && self.window_transient_store.terminal_is_empty()
                && self.retired_window_transient_stores.is_empty()
                && self.close_interaction_disposer.is_none()
                && self.tool_cancellations.active_operation_count() == 0
                && self.tool_operations.is_empty()
                && self.latest_wins_commands.is_empty()
                && self.typed_operation_reservations.iter().all(Option::is_none)
                && self.latest_wins_order.len() == 0
                && self.latest_wins_keys.terminal_is_empty()
                && self.close_instance_operation_owner_drained
                && self.instance_operation_owner.terminal_is_empty().unwrap_or(false)
                && self.media_exports.is_empty()
                && self.pending_reserved.is_empty()
                && self.reserved_commits.is_empty()
                && self.reserved_commit_outcome.is_none()
                && self.media_closures.is_empty()
                && self.snapshot_retirements.is_empty()
                && self.segmented_downloads.is_empty()
                && self.segmented_closures.is_empty()
                && self.child_content_retirements.is_empty()
                && self.close_child_member.is_none()
                && self.child_member_retirements.is_empty()
                && self.children.is_empty()
                && self.peer_roster_publications.is_empty()
                && self.peer_roster_outcomes.is_empty()
                && self.peer_presence_retirements.is_empty()
                && self.presence_peer_retirements.is_empty()
                && self.envelope_ingress.is_empty()
                && self.envelope_decode_jobs.is_empty()
                && self.store_replacement_jobs.is_empty()
                && self.document_archive_loads.is_empty()
                && self.envelope_field_decoder_retirements.is_empty()
                && self.envelope_completed_record_retirements.is_empty()
                && self.retained_fields_terminal_is_empty()
        }

        /// 🌡️ Pressure beats fairness: a queue a quarter full is drained out of turn until it is
        /// under the mark again, and the stage cursor does not move — the rotation resumes where
        /// it stood once the burst is over.
        ///
        /// 🎡️ The rotation is FAIR, not lazy. Every stage still runs at most one bounded unit, but an
        /// EMPTY stage must not consume the whole call: it answers `Pending { 0, 0 }`, releases
        /// nothing, and the cursor moves on to the next stage inside the same call. Until this loop
        /// existed a caller that drove `maintenance_step` once per turn released about one owner per
        /// [`MAINTENANCE_STAGES`] turns, because 25 of every 26 turns landed on an idle stage —
        /// measured on the assembled `s.flow.flow@1/*#editor` surface as 2_051 items released in
        /// 100_000 close turns, 96_588 of which released nothing, so a real editor could not finish
        /// closing inside any committed turn budget. The grant is still respected exactly: the scan
        /// only continues past a stage that released NOTHING, so at most one stage in a call spends
        /// it. A `Blocked` stage no longer hides a later stage that can still progress — it is
        /// remembered and reported only if the whole rotation had nothing else to give.
        fn maintenance_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            LAST_MAINTENANCE_STAGE.store(u64::MAX, std::sync::atomic::Ordering::Relaxed);
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if self.tool_operations.is_empty()
                && self.tool_cancellations.active_operation_count() == 0
                && self.latest_wins_commands.is_empty()
                && self.latest_wins_keys.map.as_ref().is_some_and(|map| map.is_empty())
                && self.latest_wins_keys.can_begin()
                && self.media_closures.is_empty()
                && self.segmented_closures.is_empty()
                && self.snapshot_retirements.is_empty()
                && self.child_content_retirements.is_empty()
                && self.child_member_retirements.is_empty()
                && self.peer_roster_publications.is_empty()
                && self.peer_presence_retirements.is_empty()
                && self.presence_peer_retirements.is_empty()
                && self.envelope_ingress.is_empty()
                && self.envelope_decode_jobs.is_empty()
                && self.store_replacement_jobs.is_empty()
                && self.document_archive_loads.is_empty()
                && self.envelope_field_decoder_retirements.is_empty()
                && self.envelope_field_decoders.next_returned_ticket().is_none()
                && self.envelope_completed_record_retirements.is_empty()
                && self.envelope_completed_records.terminal_is_empty()
                && self.store.maintenance_retirements_terminal_is_empty()
                && self.config_store.maintenance_retirements_terminal_is_empty()
                && self.draft_store.maintenance_retirements_terminal_is_empty()
                && self.window_config_store.maintenance_retirements_terminal_is_empty()
                && self.retired_window_transient_stores.is_empty()
                && self.presence_store.local_read_maintenance_is_idle()
                && !semio_framework_job::worker_job_retirements_are_parked()
                && self.live_runtime_instance_id.is_none_or(|instance_id| A::mounted_jobs_terminal_is_empty(instance_id))
            {
                return self.advance_snapshot_read_returns_one(maximum_bytes);
            }
            if self.store.maintenance_retirements_under_pressure() {
                LAST_MAINTENANCE_STAGE.store(u64::from(MAINTENANCE_DOCUMENT_DISPLACED_STAGE), std::sync::atomic::Ordering::Relaxed);
                return self.maintenance_document_displaced_step(maximum_items, maximum_bytes);
            }
            if self.config_store.maintenance_retirements_under_pressure() || self.draft_store.maintenance_retirements_under_pressure() || self.window_config_store.maintenance_retirements_under_pressure() {
                LAST_MAINTENANCE_STAGE.store(u64::from(MAINTENANCE_CONFIG_LANE_DISPLACED_STAGE), std::sync::atomic::Ordering::Relaxed);
                return self.maintenance_config_lane_displaced_step(maximum_items, maximum_bytes);
            }
            if self.child_retirements_under_pressure() {
                for stage in [MAINTENANCE_CHILD_ROOT_STAGE, MAINTENANCE_CHILD_MEMBER_STAGE] {
                    LAST_MAINTENANCE_STAGE.store(u64::from(stage), std::sync::atomic::Ordering::Relaxed);
                    let step = self.maintenance_stage_step(stage, maximum_items, maximum_bytes)?;
                    if matches!(step, PluginCloseStep::Pending { released_items, released_bytes } if released_items > 0 || released_bytes > 0) {
                        return Ok(step);
                    }
                }
            }
            let mut unproductive = PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
            for _ in 0..MAINTENANCE_STAGES {
                let stage = self.maintenance_stage;
                LAST_MAINTENANCE_STAGE.store(stage as u64, std::sync::atomic::Ordering::Relaxed);
                self.maintenance_stage = (self.maintenance_stage + 1) % MAINTENANCE_STAGES;
                match self.maintenance_stage_step(stage, maximum_items, maximum_bytes)? {
                    PluginCloseStep::Pending { released_items: 0, released_bytes: 0 } => {}
                    PluginCloseStep::Complete => unproductive = PluginCloseStep::Complete,
                    answer => return Ok(answer),
                }
            }
            Ok(unproductive)
        }

        fn maintenance_under_pressure(&self) -> bool {
            self.store.maintenance_retirements_under_pressure()
                || self.config_store.maintenance_retirements_under_pressure()
                || self.draft_store.maintenance_retirements_under_pressure()
                || self.window_config_store.maintenance_retirements_under_pressure()
                || self.child_retirements_under_pressure()
        }

