        fn media_fingerprint(port: &str, doc: &ArtifactView<'_, Self::Snapshot>) -> Result<MediaFingerprint, MediaError> {
            match Self::export_media(port, doc) {
                Ok(media) => Ok(MediaFingerprint::of(&media)),
                Err(error) => Err(error),
            }
        }
