                    });
                    match outcome.await {
                        Ok(()) => {
                            mutated = true;
                            frames.push(protocol::AppFrame::Done { in_reply_to: seq });
                        }
                        Err(fault) => push_app_fault(&mut frames, Some(seq), fault).await,
                    }
