            assert!(result.as_ref().unwrap_err().contains(diagnostic), "{name}: {result:?}");
        }
        if let Ok(facts) = result {
            assert_eq!(facts.workspace_root, workspace);
            assert!(facts.mutation_root.ends_with("domain/🧬️mutations"));
