//! 🎖️ Trust-ladder branded types after strict lex/validation.

//#region 🔖️Trust
/// 🛂️ A value that has passed [`self::lex`] in strict mode. Constructible only within
/// this crate/its trusted callers — public API never lets a caller wrap arbitrary text as
/// `Sanitized` without going through the real check.
#[derive(Clone, Debug)]
pub struct Sanitized<T>(T);

impl<T> Sanitized<T> {
    pub(crate) fn new_trusted(value: T) -> Self {
        Self(value)
    }

    pub fn into_inner(self) -> T {
        self.0
    }

    pub fn get(&self) -> &T {
        &self.0
    }
}

/// 🛂️ A value that has additionally passed schema validation. Reserved for the
/// `dsl_schema` layer to construct.
#[derive(Clone, Debug)]
pub struct SchemaValid<T>(T);

impl<T> SchemaValid<T> {
    pub fn new_trusted(value: T) -> Self {
        Self(value)
    }

    pub fn into_inner(self) -> T {
        self.0
    }

    pub fn get(&self) -> &T {
        &self.0
    }
}
//#endregion 🔖️Trust

//! 🌍️ `dsl_family_geo` — geo/crs family kit for spatial artifacts.

pub use crate::os_dsl::notation::{print_edge, EdgeLabel, EdgeLink, EdgeNode, EdgeValue};

use crate::os_dsl::{lex, Limits, TextError, TokenKind};

/// 📍 Parses `lon lat [alt]` tuples.
pub async fn parse_point_text(text: &str) -> Result<(f64, f64, Option<f64>), TextError> {
    let limits = Limits::default();
    let nums: Vec<f64> = lex(text, &limits, false)?.into_iter().filter(|t| matches!(t.kind, TokenKind::Float | TokenKind::Int)).map(|t| t.text.as_str().parse().map_err(|_| TextError::new("bad number", t.span))).collect::<Result<_, _>>()?;
    if nums.len() < 2 {
        return Err(TextError::new("expected at least lon lat", crate::os_dsl::TextSpan::at(1, 1)));
    }
    Ok((nums[0], nums[1], nums.get(2).copied()))
}

