//#region 🔖️P2M2Protocol
// Item 1a+1: repeated tag-dispatched block — length-first order, ASCII fixed(4) tag (PNG/GLB
// shape), unknown-type skip via declared length, repeat-until-sentinel-tag ("IEND").
#[semio_framework_async_macros::async_test]
async fn repeat_block_dispatches_png_shaped_chunks_and_skips_unknown_type() {
    let source = r#"dialect protocol
protocol demo.pngish
version 1
schema demo.pngish
start frame
framing record
repeat chunks {
tag fixed 4
length u32be
order length-first
trailer u32be
until "IEND"
arm "IHDR" { width u32be height u32be }
arm "IEND" { }
}
"#;
    let spec = parse_protocol(source).expect("parse pngish");
    let mut bytes = Vec::new();
    // Known arm: IHDR, length=8, two u32be fields, then a crc32be trailer.
    bytes.extend_from_slice(&8u32.to_be_bytes());
    bytes.extend_from_slice(b"IHDR");
    bytes.extend_from_slice(&100u32.to_be_bytes());
    bytes.extend_from_slice(&200u32.to_be_bytes());
    bytes.extend_from_slice(&0xDEAD_BEEFu32.to_be_bytes());
    // Unknown chunk type ("tEXt"): must be skipped as opaque via its declared length.
    bytes.extend_from_slice(&5u32.to_be_bytes());
    bytes.extend_from_slice(b"tEXt");
    bytes.extend_from_slice(&[1, 2, 3, 4, 5]);
    bytes.extend_from_slice(&0x1234_5678u32.to_be_bytes());
    // Sentinel: IEND, length=0, no fields, trailer crc, then the repeat block must stop.
    bytes.extend_from_slice(&0u32.to_be_bytes());
    bytes.extend_from_slice(b"IEND");
    bytes.extend_from_slice(&0xCAFE_BABEu32.to_be_bytes());

    let trace = walk_protocol(&spec, &bytes).expect("walk pngish");
    assert_eq!(trace.consumed, bytes.len(), "every declared+skipped+trailer byte must be consumed exactly");

    // Truncating the unknown chunk's declared payload must fail (proves the skip genuinely
    // reads `length`, not a fixed/guessed amount).
    let mut truncated = bytes.clone();
    truncated.truncate(bytes.len() - 9);
    assert!(walk_protocol(&spec, &truncated).is_err());
}

// Item 1b: two-level nested tag dispatch — GIF 89a shape (outer introducer byte, extension
// introducer's arm dispatches AGAIN on the label byte), tag-first order, no per-iteration
// length (all top-level introducers are known), repeat-until-trailer-byte (0x3B).
#[semio_framework_async_macros::async_test]
async fn repeat_block_two_level_nested_dispatch_gif89a_shaped() {
    let source = r#"dialect protocol
protocol demo.gifish
version 1
schema demo.gifish
start frame
framing record
repeat blocks {
tag u8
until 0x3B
arm 0x2C { left u16 top u16 }
arm 0x21 {
nested label u8 {
arm 0xF9 { flags u8 delay u16 }
arm 0xFE { }
}
}
arm 0x3B { }
}
"#;
    let spec = parse_protocol(source).expect("parse gifish");
    let mut bytes = Vec::new();
    // Image descriptor (0x2C): left/top u16 LE.
    bytes.push(0x2C);
    bytes.extend_from_slice(&10u16.to_le_bytes());
    bytes.extend_from_slice(&20u16.to_le_bytes());
    // Extension introducer (0x21) -> nested dispatch on label 0xF9 (GCE): flags u8, delay u16.
    bytes.push(0x21);
    bytes.push(0xF9);
    bytes.push(0);
    bytes.extend_from_slice(&100u16.to_le_bytes());
    // Trailer (0x3B) — sentinel, empty fields, loop must stop right after.
    bytes.push(0x3B);

    let trace = walk_protocol(&spec, &bytes).expect("walk gifish");
    assert_eq!(trace.consumed, bytes.len());

    // An unrecognized nested label must fail (proves the second dispatch level is real, not a
    // no-op fallthrough).
    let mut bad = bytes.clone();
    bad[5] = 0xAA; // corrupt the label byte inside the extension block
    assert!(walk_protocol(&spec, &bad).is_err());
}

// Item 1c: marker-prefix scanning — JPG shape. `marker(0xFF)` skips fill bytes before reading
// the real marker code, distinct from a fixed-position tag read.
#[semio_framework_async_macros::async_test]
async fn marker_scan_prim_finds_next_marker_byte_over_fill_bytes_jpg_style() {
    let source = r#"dialect protocol
protocol demo.jpgish
version 1
schema demo.jpgish
start frame
framing record
repeat segments {
tag marker(0xFF)
until 0xD9
arm 0xD8 { }
arm 0xE0 { version u16be }
arm 0xD9 { }
}
"#;
    let spec = parse_protocol(source).expect("parse jpgish");
    let mut bytes = Vec::new();
    // SOI preceded by an extra 0xFF fill byte — the scan must skip both leading 0xFFs and land
    // on the real 0xD8 marker code.
    bytes.extend_from_slice(&[0xFF, 0xFF, 0xD8]);
    // APP0 (0xE0), ordinary single-prefix marker, with a u16be field.
    bytes.extend_from_slice(&[0xFF, 0xE0]);
    bytes.extend_from_slice(&5u16.to_be_bytes());
    // EOI (0xD9) — sentinel.
    bytes.extend_from_slice(&[0xFF, 0xD9]);

    let trace = walk_protocol(&spec, &bytes).expect("walk jpgish");
    assert_eq!(trace.consumed, bytes.len());
}

// Item 2: BE `Prim` variants — a real round trip (parse/print/reparse) AND proof the decode is
// genuinely big-endian (a `Field(count)`-driven Array only walks cleanly if `count` was decoded
// with the declared byte order; LE-misreading a BE 3 as 0x0300 would overrun the buffer).
#[semio_framework_async_macros::async_test]
async fn be_prim_variants_round_trip_and_decode_big_endian_for_real() {
    let source = "dialect protocol\nprotocol demo.be\nversion 1\nschema demo.be\nstart frame\nframing record\nfield count u16be\nfield items Array(u8, Field(count))\n";
    let spec = parse_protocol(source).expect("parse");
    let printed = print_protocol(&spec);
    assert!(printed.contains("u16be"), "u16be must round trip through the printer");
    assert_eq!(parse_protocol(&printed).expect("reparse"), spec);

    let mut bytes = Vec::new();
    bytes.extend_from_slice(&3u16.to_be_bytes());
    bytes.extend_from_slice(&[9, 9, 9]);
    let trace = walk_protocol(&spec, &bytes).expect("walk be-driven array");
    assert_eq!(trace.consumed, bytes.len());

    // The same 2 count bytes read as LE (0x0900 = 2304) must NOT satisfy the buffer — proves a
    // real big-endian decode happened, not an accidental LE fallback.
    let le_misread_would_want = u16::from_le_bytes([3u8.to_be_bytes()[0], 0]);
    let _ = le_misread_would_want; // documentation only; the real proof is the failing walk below
    let mut too_short = bytes.clone();
    too_short.truncate(2); // count bytes only, no item bytes at all
    assert!(walk_protocol(&spec, &too_short).is_err());
}

// Item 3: cross-block field-env threading — a HEADER block's field is consumed by a LATER,
// separate SEGMENT block's `Array(_, Field(name))`. Pre-M2, `walk_fields` created a fresh
// per-call-local env, so this would fail to resolve; post-M2 the env is walk-wide.
#[semio_framework_async_macros::async_test]
async fn cross_block_field_env_threads_header_field_into_a_later_segment_las_vlr_style() {
    let source = r#"dialect protocol
protocol demo.crossblock
version 1
schema demo.crossblock
start frame
framing record
header fixed 2
field count u16
segment payload {
items Array(u8, Field(count))
}
"#;
    let spec = parse_protocol(source).expect("parse crossblock");
    let mut bytes = Vec::new();
    bytes.extend_from_slice(&4u16.to_le_bytes());
    bytes.extend_from_slice(&[1, 2, 3, 4]);
    let trace = walk_protocol(&spec, &bytes).expect("segment must resolve `count` decoded by the earlier header block");
    assert_eq!(trace.consumed, bytes.len());

    // A `count` that doesn't match the actual trailing bytes must fail, proving the segment
    // genuinely used the decoded value (not silently accepting anything).
    let mut wrong = bytes.clone();
    wrong[0] = 9; // count now claims 9 items but only 4 bytes of payload exist
    assert!(walk_protocol(&spec, &wrong).is_err());
}

// Item 4: conditional field/segment presence — bmp shape (`if compression eq 3` gates one
// field, `if bpp le 8` gates a whole segment).
#[semio_framework_async_macros::async_test]
async fn conditional_field_and_segment_presence_gate_on_an_earlier_field_bmp_style() {
    let source = r#"dialect protocol
protocol demo.bmpish
version 1
schema demo.bmpish
start frame
framing record
field compression u8
field mask u32 if compression eq 3
field bpp u8
segment palette if bpp le 8 { colors u8 }
field trailer u8
"#;
    let spec = parse_protocol(source).expect("parse bmpish");

    // compression==3 -> mask present; bpp==8 -> palette present.
    let mut present = Vec::new();
    present.push(3u8);
    present.extend_from_slice(&0x0000_00FFu32.to_le_bytes());
    present.push(8u8);
    present.push(200u8); // palette.colors
    present.push(1u8); // trailer
    let trace = walk_protocol(&spec, &present).expect("walk with mask+palette present");
    assert_eq!(trace.consumed, present.len());

    // compression==0 -> mask absent; bpp==24 -> palette absent.
    let mut absent = Vec::new();
    absent.push(0u8);
    absent.push(24u8);
    absent.push(1u8); // trailer
    let trace2 = walk_protocol(&spec, &absent).expect("walk with mask+palette absent");
    assert_eq!(trace2.consumed, absent.len());

    // A buffer sized for the ABSENT shape must not satisfy the PRESENT shape's byte demands
    // (proves presence genuinely changes how many bytes are consumed, not a no-op guard).
    assert!(walk_protocol(&spec, &absent[..2]).is_err());
}

// Item 5: ZIP-shaped backward-scan (EOCD located by scanning backward from EOF for its magic)
// + absolute-offset jump (EOCD's `cd_offset` field -> central-directory-entry block).
#[semio_framework_async_macros::async_test]
async fn backward_scan_and_jump_to_resolve_zip_eocd_and_central_directory_offset() {
    let source = r#"dialect protocol
protocol demo.zipish
version 1
schema demo.zipish
start frame
framing record
backward eocd magic 0x504B0506 {
cd_offset u32
entry_count u16
}
jump central from cd_offset {
entry_tag u32
entry_value u32
}
"#;
    let spec = parse_protocol(source).expect("parse zipish");

    let mut bytes = Vec::new();
    // 16 bytes standing in for a "local header region" this protocol doesn't describe at all.
    bytes.extend(std::iter::repeat_n(0xAAu8, 16));
    let central_dir_offset = bytes.len() as u32;
    // Central-directory entry (jumped to via `cd_offset`).
    bytes.extend_from_slice(&0xCAFE_BABEu32.to_le_bytes());
    bytes.extend_from_slice(&42u32.to_le_bytes());
    // EOCD: magic + cd_offset (points back at the entry above) + entry_count.
    bytes.extend_from_slice(&[0x50, 0x4B, 0x05, 0x06]);
    bytes.extend_from_slice(&central_dir_offset.to_le_bytes());
    bytes.extend_from_slice(&1u16.to_le_bytes());

    let trace = walk_protocol(&spec, &bytes).expect("walk zipish");
    // The walk's FINAL position is wherever the last-declared block (the jump) left `pos` —
    // NOT bytes.len(), since a jump is a deliberate exception to linear forward accounting
    // (see `walk_protocol`'s own doc comment). Here that's right after the jumped-to entry's
    // two u32 fields.
    assert_eq!(trace.consumed, central_dir_offset as usize + 8);

    // Corrupting the EOCD magic must make the backward scan fail to find it at all.
    let mut corrupt_magic = bytes.clone();
    let magic_at = bytes.len() - 10;
    corrupt_magic[magic_at] = 0x00;
    assert!(walk_protocol(&spec, &corrupt_magic).is_err());

    // Print/reparse round trip for the new block syntax itself.
    let printed = print_protocol(&spec);
    assert!(printed.contains("backward eocd magic"));
    assert!(printed.contains("jump central from cd_offset"));
    assert_eq!(parse_protocol(&printed).expect("reparse zipish"), spec);
}

// Item 6: TIFF-style runtime-selected endianness — a leading marker field's VALUE selects
// LE-vs-BE for every subsequent plain (non-`Be`-suffixed) `Prim` read for the rest of the walk.
#[semio_framework_async_macros::async_test]
async fn endian_marker_field_switches_runtime_byte_order_for_the_rest_of_the_walk_tiff_style() {
    let source = "dialect protocol\nprotocol demo.tiffish\nversion 1\nschema demo.tiffish\nstart frame\nframing record\nfield byte_order endian { \"II\"=le \"MM\"=be }\nfield count u16\nfield items Array(u8, Field(count))\n";
    let spec = parse_protocol(source).expect("parse tiffish");

    // "II" -> little-endian mode for the rest of the walk.
    let mut le_bytes = Vec::new();
    le_bytes.extend_from_slice(b"II");
    le_bytes.extend_from_slice(&2u16.to_le_bytes());
    le_bytes.extend_from_slice(&[7, 8]);
    let trace_le = walk_protocol(&spec, &le_bytes).expect("walk II/LE");
    assert_eq!(trace_le.consumed, le_bytes.len());

    // "MM" -> big-endian mode for the rest of the walk — the SAME declared field (`count u16`,
    // no `Be` suffix) must now be read big-endian, proving the marker genuinely flips a runtime
    // mode rather than being cosmetic.
    let mut be_bytes = Vec::new();
    be_bytes.extend_from_slice(b"MM");
    be_bytes.extend_from_slice(&2u16.to_be_bytes());
    be_bytes.extend_from_slice(&[7, 8]);
    let trace_be = walk_protocol(&spec, &be_bytes).expect("walk MM/BE");
    assert_eq!(trace_be.consumed, be_bytes.len());

    // An unrecognized marker must be rejected outright.
    let mut bad = le_bytes.clone();
    bad[0] = b'X';
    assert!(walk_protocol(&spec, &bad).is_err());

    // Round trip the `endian {...}` syntax itself.
    let printed = print_protocol(&spec);
    assert!(printed.contains("endian {"));
    assert_eq!(parse_protocol(&printed).expect("reparse tiffish"), spec);
}
//#endregion 🔖️P2M2Protocol

//! 🔍 The shared DSL lexer and bare-ident predicate.

use crate::os_dsl::diagnostic::{Limits, TextError, TextSpan};
use crate::os_dsl::token::*;
use crate::os_dsl::trust::Sanitized;

//#region 🔖️Dialect
/// 🎛️ How a quoted-string region decodes its escapes once the lexer commits to using
/// `quote` as its delimiter — the P2-M1 generalized string/text mechanism serving json's
/// `\uXXXX`, csv's `""`, and step's `''`-doubling uniformly instead of four bespoke fixes.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StringEscape {
    /// `\` + any char is copied verbatim into the token text (both chars kept, undecoded) — the
    /// lexer's only behavior before P2-M1, kept as the default so every grammar that doesn't
    /// declare a `string` header directive lexes byte-identically to before this type existed.
    Raw,
    /// Standard backslash decode: `\" \\ \/ \b \f \n \r \t` plus `\uXXXX` (4 hex digits, with
    /// UTF-16 surrogate-pair combination for astral codepoints) — JSON's escape grammar
    /// (RFC 8259 §7). An unrecognized escape is a strict-mode error / kept literal when forgiving.
    Backslash,
    /// The delimiter doubled (`""` / `''`) decodes to one literal delimiter char inside the
    /// string; `\` has no special meaning. CSV's RFC 4180 quoted-field escape / STEP Part 21's
    /// `''`-doubled strings.
    Doubled,
}

/// 🔤️ One configured quote delimiter + the escape scheme active while scanning it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct StringMode {
    pub quote: char,
    pub escape: StringEscape,
}

/// 💬️ Per-grammar comment syntax — `#`-to-EOL is the shared default; a grammar dialect
/// header can swap/disable the line marker or add a block form. Exists because STEP/IFC's `#` is
/// the entity-reference sigil (`#123=...`), not a comment — it directly collides with the shared
/// lexer's old hardcoded-global `#`-comment rule.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct CommentDialect {
    pub line: Option<String>,
    pub block: Option<(String, String)>,
}

impl Default for CommentDialect {
    fn default() -> Self {
        Self { line: Some("#".to_string()), block: None }
    }
}

/// 🧬️ Full per-grammar lexer configuration. `Default` reproduces the fixed alphabet exactly
/// as it existed before P2-M1 (single `"`-delimited `Raw` string, `#`-to-EOL comment, no block
/// comment) — every grammar that doesn't declare `string`/`comment` header directives is
/// unaffected, byte-for-byte, by this type's existence (the plan's "extension-only" gate).
#[derive(Clone, Debug, PartialEq, Default)]
pub struct LexOptions {
    pub strings: Vec<StringMode>,
    pub comment: CommentDialect,
}

impl LexOptions {
    fn string_mode(&self, c: char) -> Option<StringMode> {
        if self.strings.is_empty() {
            return (c == '"').then_some(StringMode { quote: '"', escape: StringEscape::Raw });
        }
        self.strings.iter().copied().find(|m| m.quote == c)
    }
}

/// 🔓️ Decodes one backslash escape unit starting at `chars[j] == '\\'` under
/// [`StringEscape::Backslash`] — JSON's scheme (RFC 8259 §7) incl. `\uXXXX` surrogate-pair
/// combination. Returns the decoded text plus the index just past the consumed escape, or `None`
/// if `chars[j..]` isn't a recognized escape (caller decides raw-fallback vs. strict error).
fn decode_backslash_unit(chars: &[char], j: usize) -> Option<(String, usize)> {
    let next = *chars.get(j + 1)?;
    match next {
        '"' => Some(("\"".to_string(), j + 2)),
        '\'' => Some(("'".to_string(), j + 2)),
        '\\' => Some(("\\".to_string(), j + 2)),
        '/' => Some(("/".to_string(), j + 2)),
        'b' => Some(("\u{8}".to_string(), j + 2)),
        'f' => Some(("\u{c}".to_string(), j + 2)),
        'n' => Some(("\n".to_string(), j + 2)),
        'r' => Some(("\r".to_string(), j + 2)),
        't' => Some(("\t".to_string(), j + 2)),
        'u' => {
            let (hi, after_hi) = read_hex4(chars, j + 2)?;
            if (0xD800..=0xDBFF).contains(&hi) {
                if chars.get(after_hi) == Some(&'\\') && chars.get(after_hi + 1) == Some(&'u') {
                    if let Some((lo, after_lo)) = read_hex4(chars, after_hi + 2) {
                        if (0xDC00..=0xDFFF).contains(&lo) {
                            let scalar = 0x10000u32 + ((hi - 0xD800) << 10) + (lo - 0xDC00);
                            if let Some(ch) = char::from_u32(scalar) {
                                return Some((ch.to_string(), after_lo));
                            }
                        }
                    }
                }
                Some((char::REPLACEMENT_CHARACTER.to_string(), after_hi))
            } else if (0xDC00..=0xDFFF).contains(&hi) {
                Some((char::REPLACEMENT_CHARACTER.to_string(), after_hi))
            } else {
                char::from_u32(hi).map(|ch| (ch.to_string(), after_hi))
            }
        }
        _ => None,
    }
}

fn read_hex4(chars: &[char], start: usize) -> Option<(u32, usize)> {
    if start + 4 > chars.len() {
        return None;
    }
    let text: String = chars[start..start + 4].iter().collect();
    u32::from_str_radix(&text, 16).ok().map(|v| (v, start + 4))
}

/// 🔎️ True iff `chars[i..]` begins with `needle`'s chars — the multi-char-marker match
/// used by both configurable comment forms (line marker, block open/close).
fn chars_start_with(chars: &[char], i: usize, needle: &str) -> bool {
    let needle_chars: Vec<char> = needle.chars().collect();
    if i + needle_chars.len() > chars.len() {
        return false;
    }
    chars[i..i + needle_chars.len()] == needle_chars[..]
}
//#endregion 🔖️Dialect

//#region 🔖️Lexer
// 🚫️async: E1 pure char classifier consumed by `Option::is_some_and`/`Iterator::filter` sync closures (`:475`, `:614`) — see R9
fn is_ident_start(c: char) -> bool {
    c.is_alphabetic() || c == '_'
}

// 🚫️async: E1 pure char classifier consumed by `Option::is_some_and` sync closure (`:475`) — see R9
fn is_ident_continue(c: char) -> bool {
    c.is_alphanumeric() || matches!(c, '_' | '-' | '.' | '/')
}

/// 🔢️ Bounds an explicitly sized IEEE NaN word before any adjacent unit suffix.
fn ieee_word_end(chars:&[char],start:usize)->Option<usize>{for(prefix,width)in[("nan64_",16),("nan32_",8)]{let first=start+prefix.len();let end=first+width;if end<=chars.len()&&chars[start..first].iter().copied().eq(prefix.chars())&&chars[first..end].iter().all(|value|value.is_ascii_hexdigit()){return Some(end);}}None}
fn nonfinite_unit_end(chars:&[char],start:usize)->Option<usize>{for prefix in ["inf","-inf","nan"]{let first=start+prefix.len();if first<chars.len()&&chars[start..first].iter().copied().eq(prefix.chars())&&is_ident_start(chars[first]){let mut end=first+1;while end<chars.len()&&is_ident_continue(chars[end]){end+=1;}let suffix:String=chars[first..end].iter().collect();if unit_by_symbol(&suffix).is_some(){return Some(first);}}}None}

/// ➡️ Fused edge arrow `-id:Kind>` or `-id-` (not `->` / `--`).
fn lex_fused_edge_arrow(chars: &[char], i: usize) -> Option<(usize, String)> {
    if chars.get(i) != Some(&'-') {
        return None;
    }
    let mut j = i + 1;
    if j >= chars.len() {
        return None;
    }
    if chars[j] == ':' {
        j += 1;
        if j >= chars.len() || !is_ident_start(chars[j]) {
            return None;
        }
        while j < chars.len() && is_ident_continue(chars[j]) && chars[j] != '-' {
            j += 1;
        }
    } else if is_ident_start(chars[j]) {
        while j < chars.len() && is_ident_continue(chars[j]) && chars[j] != '-' {
            j += 1;
        }
        if j < chars.len() && chars[j] == ':' {
            j += 1;
            if j >= chars.len() || !is_ident_start(chars[j]) {
                return None;
            }
            while j < chars.len() && is_ident_continue(chars[j]) && chars[j] != '-' {
                j += 1;
            }
        }
    } else {
        return None;
    }
    if j < chars.len() && chars[j] == '>' {
        j += 1;
        return Some((j, chars[i..j].iter().collect()));
    }
    if j < chars.len() && chars[j] == '-' && chars.get(j + 1) != Some(&'-') {
        j += 1;
        return Some((j, chars[i..j].iter().collect()));
    }
    None
}

/// 🔬️ Grammar-independent lexer for the fixed token alphabet shared by every DSL grammar
/// declared on this engine. `forgiving = true` never fails (malformed regions become `Error`
/// tokens instead), which is what editor/completion mode needs; `forgiving = false` is strict
/// parse mode and returns the first lexical error. The fixed-alphabet default entry point — every
/// pre-P2-M1 caller keeps this exact 3-arg signature; equivalent to
/// `lex_with(text, limits, forgiving, &LexOptions::default())`.
pub fn lex(text: &str, limits: &Limits, forgiving: bool) -> Result<Vec<SpannedToken>, TextError> {
    lex_with(text, limits, forgiving, &LexOptions::default())
}

/// 🎛️ P2-M1: same lexer, parameterized by a per-grammar [`LexOptions`] (string quote+escape
/// modes, comment syntax). `lex` is the fixed-default entry point every pre-M1 caller still uses.
pub fn lex_with(text: &str, limits: &Limits, forgiving: bool, opts: &LexOptions) -> Result<Vec<SpannedToken>, TextError> {
    limits.check_bytes(text.len())?;
    let chars: Vec<char> = text.chars().collect();
    let mut tokens = Vec::new();
    let mut i = 0usize;
    let mut line = 1u32;
    let mut column = 1u32;
    let mut byte_offset = 0u32;
    let mut next_id = 0u32;

    macro_rules! push {
        ($kind:expr, $start_line:expr, $start_col:expr, $start_byte:expr, $text:expr) => {{
            let text_str: String = $text;
            let len = text_str.chars().count() as u32;
            tokens.push(SpannedToken { id: TokenId(next_id), kind: $kind, text: Symbol::intern(&text_str), span: TextSpan::with_length($start_line, $start_col, len), byte_range: ($start_byte, byte_offset) });
            next_id += 1;
        }};
    }

    while i < chars.len() {
        limits.check_tokens(tokens.len(), TextSpan::at(line, column))?;
        let c = chars[i];
        let start_line = line;
        let start_col = column;
        let start_byte = byte_offset;

        if c == '\n' {
            i += 1;
            byte_offset += c.len_utf8() as u32;
            push!(TokenKind::Newline, start_line, start_col, start_byte, "\n".to_string());
            line += 1;
            column = 1;
            continue;
        }
        if c.is_whitespace() {
            let mut j = i;
            let mut buf = String::new();
            while j < chars.len() && chars[j].is_whitespace() && chars[j] != '\n' {
                buf.push(chars[j]);
                byte_offset += chars[j].len_utf8() as u32;
                column += 1;
                j += 1;
            }
            i = j;
            push!(TokenKind::Whitespace, start_line, start_col, start_byte, buf);
            continue;
        }
        // Line comment: marker is a configurable string (default "#"), `None` disables it
        // entirely — STEP/IFC declare `comment line none` because `#` is their entity-ref sigil.
        if let Some(marker) = opts.comment.line.as_deref() {
            if chars_start_with(&chars, i, marker) {
                let mut j = i;
                let mut buf = String::new();
                while j < chars.len() && chars[j] != '\n' {
                    buf.push(chars[j]);
                    byte_offset += chars[j].len_utf8() as u32;
                    column += 1;
                    j += 1;
                }
                i = j;
                push!(TokenKind::Comment, start_line, start_col, start_byte, buf);
                continue;
            }
        }
        // Block comment: configurable `(open, close)` pair, disabled by default. May span lines —
        // line/column tracked through the body like the Fence token below. An unterminated block
        // comment falls through unconsumed in forgiving mode (its open-marker chars — e.g. `/*`'s
        // `/` and `*` — are each already ordinary single-char tokens) instead of looping forever.
        if let Some((open, close)) = &opts.comment.block {
            if chars_start_with(&chars, i, open) {
                let open_len = open.chars().count();
                let mut k = i + open_len;
                let mut found_end: Option<usize> = None;
                while k < chars.len() {
                    if chars_start_with(&chars, k, close) {
                        found_end = Some(k + close.chars().count());
                        break;
                    }
                    k += 1;
                }
                if let Some(end) = found_end {
                    let buf: String = chars[i..end].iter().collect();
                    for idx in i..end {
                        if chars[idx] == '\n' {
                            line += 1;
                            column = 1;
                        } else {
                            byte_offset += chars[idx].len_utf8() as u32;
                            column += 1;
                        }
                    }
                    i = end;
                    push!(TokenKind::Comment, start_line, start_col, start_byte, buf);
                    continue;
                }
                if !forgiving {
                    return Err(TextError::new("unterminated block comment (no closing marker)", TextSpan::at(start_line, start_col)));
                }
                // forgiving: fall through — the open marker's own chars lex as ordinary tokens.
            }
        }
        if let Some(mode) = opts.string_mode(c) {
            let quote = mode.quote;
            let mut j = i + 1;
            let mut buf = String::new();
            let mut closed = false;
            byte_offset += c.len_utf8() as u32;
            column += 1;
            match mode.escape {
                StringEscape::Raw => {
                    while j < chars.len() {
                        let cj = chars[j];
                        if cj == '\\' && j + 1 < chars.len() {
                            buf.push(cj);
                            buf.push(chars[j + 1]);
                            byte_offset += cj.len_utf8() as u32 + chars[j + 1].len_utf8() as u32;
                            column += 2;
                            j += 2;
                            continue;
                        }
                        if cj == quote {
                            byte_offset += cj.len_utf8() as u32;
                            column += 1;
                            j += 1;
                            closed = true;
                            break;
                        }
                        if cj == '\n' {
                            if forgiving {
                                break;
                            }
                            return Err(TextError::new("unterminated string literal (newline before closing quote)", TextSpan::at(start_line, start_col)));
                        }
                        buf.push(cj);
                        byte_offset += cj.len_utf8() as u32;
                        column += 1;
                        j += 1;
                    }
                }
                StringEscape::Backslash => {
                    while j < chars.len() {
                        let cj = chars[j];
                        if cj == quote {
                            byte_offset += cj.len_utf8() as u32;
                            column += 1;
                            j += 1;
                            closed = true;
                            break;
                        }
                        if cj == '\n' {
                            if forgiving {
                                break;
                            }
                            return Err(TextError::new("unterminated string literal (newline before closing quote)", TextSpan::at(start_line, start_col)));
                        }
                        if cj == '\\' {
                            match decode_backslash_unit(&chars, j) {
                                Some((decoded, next_j)) => {
                                    buf.push_str(&decoded);
                                    for k in j..next_j {
                                        byte_offset += chars[k].len_utf8() as u32;
                                        column += 1;
                                    }
                                    j = next_j;
                                }
                                None if forgiving || j + 1 >= chars.len() => {
                                    buf.push('\\');
                                    byte_offset += cj.len_utf8() as u32;
                                    column += 1;
                                    j += 1;
                                }
                                None => {
                                    return Err(TextError::new("unknown backslash escape in string literal", TextSpan::at(start_line, start_col)));
                                }
                            }
                            continue;
                        }
                        buf.push(cj);
                        byte_offset += cj.len_utf8() as u32;
                        column += 1;
                        j += 1;
                    }
                }
                StringEscape::Doubled => {
                    while j < chars.len() {
                        let cj = chars[j];
                        if cj == quote {
                            if chars.get(j + 1) == Some(&quote) {
                                buf.push(quote);
                                byte_offset += quote.len_utf8() as u32 * 2;
                                column += 2;
                                j += 2;
                                continue;
                            }
                            byte_offset += cj.len_utf8() as u32;
                            column += 1;
                            j += 1;
                            closed = true;
                            break;
                        }
                        if cj == '\n' {
                            if forgiving {
                                break;
                            }
                            return Err(TextError::new("unterminated string literal (newline before closing quote)", TextSpan::at(start_line, start_col)));
                        }
                        buf.push(cj);
                        byte_offset += cj.len_utf8() as u32;
                        column += 1;
                        j += 1;
                    }
                }
            }
            i = j;
            if !closed && !forgiving {
                return Err(TextError::new("unterminated string literal", TextSpan::at(start_line, start_col)));
            }
            push!(if closed { TokenKind::Text } else { TokenKind::Error }, start_line, start_col, start_byte, buf);
            continue;
        }
        // Fenced block: ```lang\ncontent\n``` — the ONE place this lexer scans raw multi-line
        // content instead of token-by-token (`Shape::Embed`'s only consumer). The lang tag is
        // everything up to the first newline (may be empty); content is everything up to a line
        // that is EXACTLY three backticks (no leading/trailing whitespace on that line — a fence
        // can never be indented, matching every other "structural" line in this grammar). Encoded
        // as one token, text = "lang\u{0}content" (NUL can't occur in valid authored text, so it's
        // a safe separator without adding a field to `SpannedToken`) — `dsl_schema`'s `Shape::Embed`
        // splits on it, the same trick `Shape::Dim` uses for its glued `x`-separated components.
        if c == '`' && chars.get(i + 1) == Some(&'`') && chars.get(i + 2) == Some(&'`') {
            let mut j = i + 3;
            while j < chars.len() && chars[j] != '\n' {
                j += 1;
            }
            let lang: String = chars[i + 3..j].iter().collect();
            let mut closing: Option<(usize, usize)> = None;
            if j < chars.len() {
                let content_start = j + 1;
                let mut k = content_start;
                loop {
                    let line_start = k;
                    let mut line_end = k;
                    while line_end < chars.len() && chars[line_end] != '\n' {
                        line_end += 1;
                    }
                    if chars[line_start..line_end].iter().collect::<String>() == "```" {
                        let content_end = if line_start > content_start { line_start - 1 } else { line_start };
                        let resume = if line_end < chars.len() { line_end + 1 } else { line_end };
                        closing = Some((content_end, resume));
                        break;
                    }
                    if line_end >= chars.len() {
                        break;
                    }
                    k = line_end + 1;
                }
            }
            if let Some((content_end, resume)) = closing {
                let content_start = j + 1;
                let content: String = chars[content_start..content_end.max(content_start)].iter().collect();
                for idx in i..resume {
                    if chars[idx] == '\n' {
                        line += 1;
                        column = 1;
                    } else {
                        byte_offset += chars[idx].len_utf8() as u32;
                        column += 1;
                    }
                }
                i = resume;
                push!(TokenKind::Fence, start_line, start_col, start_byte, format!("{lang}\u{0}{content}"));
                continue;
            }
            if !forgiving {
                return Err(TextError::new("unterminated fenced block (no closing '```' line)", TextSpan::at(start_line, start_col)));
            }
            // forgiving mode: fall through to "unknown character" for the opening backtick, then
            // the lexer naturally re-tries from the next character on its next loop iteration.
        }
        // `-inf` is its own special float literal (the negative-infinity half of the "nan/inf/-inf"
        // ident convention `format_f64`/`parse_f64` round-trip) — unlike ordinary numbers, `-` isn't
        // followed by a digit here, and `-` isn't a valid ident-start character either, so without
        // this it falls through every branch below to "unknown character".
        if c == '-' && i + 4 <= chars.len() && chars[i + 1] == 'i' && chars[i + 2] == 'n' && chars[i + 3] == 'f' && !chars.get(i + 4).is_some_and(|next| is_ident_continue(*next)) {
            i += 4;
            byte_offset += 4;
            column += 4;
            push!(TokenKind::Float, start_line, start_col, start_byte, "-inf".to_string());
            continue;
        }
        if c=='n'{if let Some(end)=ieee_word_end(&chars,i){let text:String=chars[i..end].iter().collect();byte_offset+=(end-i)as u32;column+=(end-i)as u32;i=end;push!(TokenKind::Float,start_line,start_col,start_byte,text);continue;}}
        if matches!(c,'i'|'-'|'n'){if let Some(end)=nonfinite_unit_end(&chars,i){let text:String=chars[i..end].iter().collect();byte_offset+=(end-i)as u32;column+=(end-i)as u32;i=end;push!(TokenKind::Float,start_line,start_col,start_byte,text);continue;}}
        if c.is_ascii_digit() || (c == '-' && i + 1 < chars.len() && chars[i + 1].is_ascii_digit()) {
            let mut j = i;
            let mut buf = String::new();
            let mut is_float = false;
            if chars[j] == '-' {
                buf.push('-');
                byte_offset += 1;
                column += 1;
                j += 1;
            }
            while j < chars.len() && chars[j].is_ascii_digit() {
                buf.push(chars[j]);
                byte_offset += 1;
                column += 1;
                j += 1;
            }
            // Trailing-dot floats (P2-M1): `0.` / `10.` — STEP Part 21's `read_number` accepts a
            // dot with no following digit. The one case that must NOT be swallowed here is a `.`
            // immediately followed by another `.` (the Range literal `0..10`) — anything else
            // after the dot (digit, letter, whitespace, EOF) commits to a trailing-dot float.
            if j < chars.len() && chars[j] == '.' && chars.get(j + 1) != Some(&'.') {
                is_float = true;
                buf.push('.');
                byte_offset += 1;
                column += 1;
                j += 1;
                while j < chars.len() && chars[j].is_ascii_digit() {
                    buf.push(chars[j]);
                    byte_offset += 1;
                    column += 1;
                    j += 1;
                }
            }
            if j < chars.len() && (chars[j] == 'e' || chars[j] == 'E') {
                let mut k = j + 1;
                if k < chars.len() && (chars[k] == '+' || chars[k] == '-') {
                    k += 1;
                }
                if k < chars.len() && chars[k].is_ascii_digit() {
                    is_float = true;
                    while j < k {
                        buf.push(chars[j]);
                        byte_offset += 1;
                        column += 1;
                        j += 1;
                    }
                    while j < chars.len() && chars[j].is_ascii_digit() {
                        buf.push(chars[j]);
                        byte_offset += 1;
                        column += 1;
                        j += 1;
                    }
                }
            }
            i = j;
            push!(if is_float { TokenKind::Float } else { TokenKind::Int }, start_line, start_col, start_byte, buf);
            continue;
        }
        if is_ident_start(c) {
            let mut j = i;
            let mut buf = String::new();
            while j < chars.len() && is_ident_continue(chars[j]) {
                // A '-' that starts an `->`/`--` operator terminates the ident here instead of
                // being swallowed into it, so kebab-case idents ("hexagonal-mushroom-column")
                // and the Arrow/DashArrow operators coexist without ambiguity.
                if chars[j] == '-' && j + 1 < chars.len() && matches!(chars[j + 1], '>' | '-') {
                    break;
                }
                buf.push(chars[j]);
                byte_offset += chars[j].len_utf8() as u32;
                column += 1;
                j += 1;
            }
            i = j;
            // A lone `_` is the placeholder sigil (positional "absent" marker), never an ident —
            // `_foo`/`foo_bar` still lex as ordinary idents since the buffer differs from "_".
            let kind = if buf == "_" { TokenKind::Placeholder } else { TokenKind::Ident };
            push!(kind, start_line, start_col, start_byte, buf);
            continue;
        }
        if c == '<' && i + 1 < chars.len() && chars[i + 1] == '-' {
            i += 2;
            byte_offset += 2;
            column += 2;
            push!(TokenKind::BackArrow, start_line, start_col, start_byte, "<-".to_string());
            continue;
        }
        if c == '-' && i + 1 < chars.len() && chars[i + 1] == '>' {
            i += 2;
            byte_offset += 2;
            column += 2;
            push!(TokenKind::Arrow, start_line, start_col, start_byte, "->".to_string());
            continue;
        }
        if c == '-' && i + 1 < chars.len() && chars[i + 1] == '-' {
            i += 2;
            byte_offset += 2;
            column += 2;
            push!(TokenKind::DashArrow, start_line, start_col, start_byte, "--".to_string());
            continue;
        }
        if c == '-' {
            if let Some((end_j, fused_text)) = lex_fused_edge_arrow(&chars, i) {
                let _len = end_j - i;
                for k in i..end_j {
                    byte_offset += chars[k].len_utf8() as u32;
                    column += 1;
                }
                i = end_j;
                push!(TokenKind::EdgeArrow, start_line, start_col, start_byte, fused_text);
                continue;
            }
            i += 1;
            byte_offset += 1;
            column += 1;
            push!(TokenKind::Minus, start_line, start_col, start_byte, "-".to_string());
            continue;
        }
        // `..` (Range literal `lo..hi`) must be checked before the single-char table below since
        // a lone `.` isn't `is_ident_start` and would otherwise fall through to "unknown character".
        if c == '.' && i + 1 < chars.len() && chars[i + 1] == '.' {
            i += 2;
            byte_offset += 2;
            column += 2;
            push!(TokenKind::DotDot, start_line, start_col, start_byte, "..".to_string());
            continue;
        }
        // Leading-dot enum literal (P2-M1): STEP Part 21's `.T.` / `.UNSPECIFIED.` — a dot, an
        // ident-shaped run, a closing dot, captured as one `DotEnum` token (text keeps both dots).
        // Checked after `..` (so a bare `..` still wins) and only commits when the closing dot is
        // actually found; otherwise falls through untouched, leaving today's behavior (a lone `.`
        // becomes "unknown character") unchanged for every format that never used this shape.
        if c == '.' && chars.get(i + 1).is_some_and(|next| is_ident_start(*next)) {
            let mut j = i + 1;
            // Deliberately narrower than `is_ident_continue` (which allows '.'/'-'/'/' so ordinary
            // idents like "a..b" or "hexagonal-mushroom-column" stay one token) — a dot-enum body
            // must stop AT its own closing dot rather than swallowing it as if it continued.
            while j < chars.len() && (chars[j].is_alphanumeric() || chars[j] == '_') {
                j += 1;
            }
            if chars.get(j) == Some(&'.') {
                let end = j + 1;
                let text: String = chars[i..end].iter().collect();
                for k in i..end {
                    byte_offset += chars[k].len_utf8() as u32;
                    column += 1;
                }
                i = end;
                push!(TokenKind::DotEnum, start_line, start_col, start_byte, text);
                continue;
            }
        }
        let single = match c {
            '=' => Some(TokenKind::Equals),
            ',' => Some(TokenKind::Comma),
            ':' => Some(TokenKind::Colon),
            '@' => Some(TokenKind::At),
            '^' => Some(TokenKind::Caret),
            '+' => Some(TokenKind::Plus),
            '*' => Some(TokenKind::Star),
            '/' => Some(TokenKind::Slash),
            '{' => Some(TokenKind::LBrace),
            '}' => Some(TokenKind::RBrace),
            '[' => Some(TokenKind::LBracket),
            ']' => Some(TokenKind::RBracket),
            '(' => Some(TokenKind::LParen),
            ')' => Some(TokenKind::RParen),
            // Promoted single-char tokens (P2-M1 item 3). `<` only reaches here when it wasn't the
            // start of `<-` (checked earlier and `continue`s on match), so no collision with
            // BackArrow; `>` is only ever swallowed by `lex_fused_edge_arrow` from a leading `-`,
            // never checked standalone before this table, so no collision there either.
            '<' => Some(TokenKind::Lt),
            '>' => Some(TokenKind::Gt),
            '&' => Some(TokenKind::Amp),
            '$' => Some(TokenKind::Dollar),
            ';' => Some(TokenKind::Semicolon),
            _ => None,
        };
        if let Some(kind) = single {
            i += 1;
            byte_offset += c.len_utf8() as u32;
            column += 1;
            push!(kind, start_line, start_col, start_byte, c.to_string());
            continue;
        }
        // Unknown character.
        i += 1;
        byte_offset += c.len_utf8() as u32;
        column += 1;
        if !forgiving {
            return Err(TextError::new(format!("unexpected character '{c}'"), TextSpan::at(start_line, start_col)));
        }
        push!(TokenKind::Error, start_line, start_col, start_byte, c.to_string());
    }
    let eof_line = line;
    let eof_col = column;
    tokens.push(SpannedToken { id: TokenId(next_id), kind: TokenKind::Eof, text: Symbol::intern(""), span: TextSpan::at(eof_line, eof_col), byte_range: (byte_offset, byte_offset) });
    // Strict-mode success is exactly the invariant `Sanitized` documents — brand it here so the
    // type isn't just a paper promise, then unwrap since callers still want plain tokens.
    if forgiving {
        Ok(tokens)
    } else {
        // `Sanitized::new_trusted`/`.into_inner` (`🗣️dsl/🎖️trust/🦀️.rs`) were reverted to
        // sync per R9 (trivial wrapper types, 0 await/0 io) — direct sync calls now.
        Ok(Sanitized::new_trusted(tokens).into_inner())
    }
}

/// 🎨️ Maps lexed tokens to editor highlighting classes. `keywords` is the live set of
/// idents that are structural keywords in the current grammar context (schema-declared).
pub fn token_classes(tokens: &[SpannedToken], keywords: &[&str]) -> Vec<(TokenClass, TextSpan)> {
    tokens
        .iter()
        .filter(|t| !t.kind.is_trivia() && t.kind != TokenKind::Eof)
        .map(|t| {
            let class = match t.kind {
                TokenKind::Ident => {
                    let text = t.text.as_str();
                    if keywords.contains(&text.as_ref()) {
                        TokenClass::Keyword
                    } else {
                        TokenClass::Ident
                    }
                }
                TokenKind::Int | TokenKind::Float => TokenClass::Number,
                TokenKind::Text => TokenClass::String,
                TokenKind::Placeholder | TokenKind::DotEnum => TokenClass::Ident,
                TokenKind::Equals
                | TokenKind::Arrow
                | TokenKind::DashArrow
                | TokenKind::BackArrow
                | TokenKind::EdgeArrow
                | TokenKind::At
                | TokenKind::Colon
                | TokenKind::Caret
                | TokenKind::DotDot
                | TokenKind::Plus
                | TokenKind::Minus
                | TokenKind::Star
                | TokenKind::Slash
                | TokenKind::Lt
                | TokenKind::Gt
                | TokenKind::Amp
                | TokenKind::Dollar => TokenClass::Operator,
                TokenKind::Fence => TokenClass::String,
                TokenKind::Semicolon => TokenClass::Punctuation,
                TokenKind::Comma | TokenKind::LBrace | TokenKind::RBrace | TokenKind::LBracket | TokenKind::RBracket | TokenKind::LParen | TokenKind::RParen => TokenClass::Punctuation,
                TokenKind::Comment => TokenClass::Comment,
                TokenKind::Error => TokenClass::Error,
                TokenKind::Whitespace | TokenKind::Newline | TokenKind::Eof => unreachable!("filtered above"),
            };
            (class, t.span)
        })
        .collect()
}
/// 🪪️ True iff `s` lexes (strict) as exactly one `Ident` token whose text equals `s` —
/// i.e. `s` is safe to print bare (unquoted) wherever `Shape::Text` is expected. Excludes the
/// reserved literal idents (`_`/`true`/`false`/`null`/`nan`/`inf`) and anything number-shaped
/// (those lex as `Int`/`Float`/`Placeholder`, not `Ident`, so they're already excluded by
/// construction — the reserved-word list catches the ones that would otherwise lex as `Ident`).
/// Implemented defensively by actually calling the lexer rather than hand-rolling a second
/// notion of "identifier-shaped" that could drift from the real grammar.
pub fn is_bare_ident(s: &str) -> bool {
    if matches!(s, "_" | "true" | "false" | "null" | "nan" | "inf") {
        return false;
    }
    match lex(s, &Limits::default(), false) {
        Ok(tokens) => {
            let significant: Vec<&SpannedToken> = tokens.iter().filter(|t| t.kind != TokenKind::Eof).collect();
            matches!(significant.as_slice(), [only] if only.kind == TokenKind::Ident && only.text.as_str().as_ref() == s)
        }
        Err(_) => false,
    }
}
