fn oracle(body:&[u8],words:&[u64]){use std::{io::Write,process::{Command,Stdio}};let expected=serde_json::to_string(&words.iter().map(|word|format!("{word:016x}")).collect::<Vec<_>>()).unwrap();let script=r#"import assert from 'node:assert/strict';import{Database}from'bun:sqlite';const words=__WORDS__.map(value=>BigInt('0x'+value));const bytes=new Uint8Array(await Bun.stdin.arrayBuffer()),view=new DataView(bytes.buffer);let offset=0;function integer(){let value=0,shift=0;for(;;){const byte=bytes[offset++];assert.ok(byte!==undefined);value+=(byte&127)*2**shift;if(!(byte&128))return value;shift+=7;assert.ok(shift<53)}}function word(expected){assert.equal(view.getBigUint64(offset,true),expected);offset+=8}assert.equal(integer(),0);const count=integer();if(count===2){assert.equal(integer(),1);assert.equal(bytes[offset++],5);word(words[0]);assert.equal(integer(),2);assert.equal(bytes[offset++],21);assert.equal(integer(),words.length);for(const expected of words)word(expected)}else{assert.equal(count,1);assert.equal(integer(),1);assert.equal(bytes[offset++],20);assert.equal(integer(),words.length);assert.equal(integer(),1);assert.equal(integer(),1);assert.equal(bytes[offset++],0);assert.equal(bytes[offset++],4);for(const expected of words)word(expected)}assert.equal(offset,bytes.length);const db=new Database(':memory:');db.run('CREATE TABLE exact_word(ordinal INTEGER PRIMARY KEY,word BLOB NOT NULL CHECK(length(word)=8))');for(let index=0;index<words.length;index++){const raw=new Uint8Array(8);new DataView(raw.buffer).setBigUint64(0,words[index],true);db.run('INSERT INTO exact_word VALUES(?,?)',index,raw)}assert.equal(db.query('PRAGMA integrity_check').get().integrity_check,'ok');for(const row of db.query('SELECT ordinal,word FROM exact_word ORDER BY ordinal').all()){assert.equal(new DataView(row.word.buffer,row.word.byteOffset,row.word.byteLength).getBigUint64(0,true),words[row.ordinal])}db.close();await Bun.write(Bun.stdout,bytes);"#.replace("__WORDS__",&expected);let mu